/**
 * Processes an auto-login cookie to authenticate a user.
 * 
 * @param cookieTokens The array of tokens from the cookie.
 * @param request The HTTP request.
 * @param response The HTTP response.
 * @return The UserDetails of the authenticated user.
 * @throws InvalidCookieException If the cookie does not contain exactly two tokens.
 * @throws RememberMeAuthenticationException If no token is found for the series, the token does not match, or the token has expired.
 * @throws CookieTheftException If the token is stolen.
 */
protected UserDetails processAutoLoginCookie(String[] cookieTokens, HttpServletRequest request, HttpServletResponse response) {
    if (cookieTokens.length != 2) {
        throw new InvalidCookieException("Cookie token did not contain 2 tokens, but contained '" + Arrays.asList(cookieTokens) + "'");
    }
    String presentedSeries = cookieTokens[0];
    String presentedToken = cookieTokens[1];
    PersistentRememberMeToken token = tokenRepository.getTokenForSeries(presentedSeries);
    if (token == null) {
        throw new RememberMeAuthenticationException("No persistent token found for series id: " + presentedSeries);
    }
    if (!presentedToken.equals(token.getTokenValue())) {
        tokenRepository.removeUserTokens(token.getUsername());
        throw new CookieTheftException(messages.getMessage("PersistentTokenBasedRememberMeServices.cookieStolen", "Invalid remember-me token (Series/token) mismatch. Implies previous cookie theft attack."));
    }
    if (token.getDate().getTime() + getTokenValiditySeconds() * 1000L < System.currentTimeMillis()) {
        throw new RememberMeAuthenticationException("Remember-me login has expired");
    }
    PersistentRememberMeToken newToken = new PersistentRememberMeToken(token.getUsername(), token.getSeries(), generateTokenData(), new Date());
    try {
        tokenRepository.updateToken(newToken.getSeries(), newToken.getTokenValue(), newToken.getDate());
        addCookie(newToken, request, response);
    } catch (Exception e) {
        logger.error("Failed to update token: ", e);
        throw new RememberMeAuthenticationException("Autologin failed due to data access problem");
    }
    return getUserDetailsService().loadUserByUsername(token.getUsername());
}

