 * @throws AuthenticationCredentialsNotFoundException If the current user or original authentication object is not found.
 */
protected Authentication attemptExitUser(HttpServletRequest request) throws AuthenticationCredentialsNotFoundException {
    // Get the current authentication object
    Authentication current = SecurityContextHolder.getContext().getAuthentication();
    if (current == null) {
        throw new AuthenticationCredentialsNotFoundException("No current user associated with this request");
    }

    // Get the original authentication object
    Authentication original = getSourceAuthentication(current);
    if (original == null) {
        logger.debug("Could not find original user Authentication object!");
        throw new AuthenticationCredentialsNotFoundException("Could not find original Authentication object");
    }

    // Get the original user details
    UserDetails originalUser = null;
    Object obj = original.getPrincipal();
    if (obj != null && obj instanceof UserDetails) {
        originalUser = (UserDetails) obj;
    }

    // Publish an authentication switch event
    if (eventPublisher != null) {
        eventPublisher.publishEvent(new AuthenticationSwitchUserEvent(current, originalUser));
    }

    return original;
}

