/**
 * Determines the target URL for redirection based on the request and response.
 * 
 * @param request The HTTP request object.
 * @param response The HTTP response object.
 * @return The target URL for redirection.
 */
protected String determineTargetUrl(HttpServletRequest request, HttpServletResponse response) {
    // Check if always use default target URL
    if (isAlwaysUseDefaultTargetUrl()) {
        return defaultTargetUrl;
    }

    // Check for the target URL parameter in the request
    String targetUrl = null;
    if (targetUrlParameter != null) {
        targetUrl = request.getParameter(targetUrlParameter);
        if (StringUtils.hasText(targetUrl)) {
            logger.debug("Found targetUrlParameter in request: " + targetUrl);
            return targetUrl;
        }
    }

    // Use the Referer header if available and target URL is not set
    if (useReferer && !StringUtils.hasLength(targetUrl)) {
        targetUrl = request.getHeader("Referer");
        logger.debug("Using Referer header: " + targetUrl);
    }

    // If target URL is still not set, use the default target URL
    if (!StringUtils.hasText(targetUrl)) {
        targetUrl = defaultTargetUrl;
        logger.debug("Using default URL: " + targetUrl);
    }

    return targetUrl;
}

