/**
 * Determines if method `b` overrides method `a`.
 * 
 * @param a The method to be overridden.
 * @param b The method that might override `a`.
 * @return `true` if `b` overrides `a`, `false` otherwise.
 */
private static boolean overrides(Method a, Method b) {
    int modifiers = b.getModifiers();
    if (Modifier.isPublic(modifiers) || Modifier.isProtected(modifiers)) {
        return true;
    }
    if (Modifier.isPrivate(modifiers)) {
        return false;
    }
