    if (wrappedPrimitives != null) {
        return wrappedPrimitives;
    }
    if (typeLiteral.getClass() == TypeLiteral.class) {
        return typeLiteral;
    }
    @SuppressWarnings("unchecked")
    TypeLiteral<T> recreated = (TypeLiteral<T>) TypeLiteral.get(typeLiteral.getType());
    return recreated;
