/**
 * Dispatches an RPC request to the appropriate user processor.
 *
 * @param ctx The remoting context containing the user processor.
 * @param cmd The RPC request command.
 */
private void dispatchToUserProcessor(RemotingContext ctx, RpcRequestCommand cmd) {
    int id = cmd.getId();
    byte type = cmd.getType();
    UserProcessor processor = ctx.getUserProcessor(cmd.getRequestClass());

    if (processor instanceof AsyncUserProcessor) {
        try {
            processor.handleRequest(processor.preHandleRequest(ctx, cmd.getRequestObject()), new RpcAsyncContext(ctx, cmd, this), cmd.getRequestObject());
        } catch (RejectedExecutionException e) {
            logWarning("RejectedExecutionException occurred when doing ASYNC process in RpcRequestProcessor");
            sendResponseIfNecessary(ctx, type, createExceptionResponse(id, ResponseStatus.SERVER_THREADPOOL_BUSY));
        } catch (Throwable t) {
            logError("ASYNC process rpc request failed in RpcRequestProcessor, id=" + id, t);
            sendResponseIfNecessary(ctx, type, createExceptionResponse(id, t, "AYSNC process rpc request failed in RpcRequestProcessor, id=" + id));
        }
    } else {
        try {
            Object responseObject = processor.handleRequest(processor.preHandleRequest(ctx, cmd.getRequestObject()), cmd.getRequestObject());
            sendResponseIfNecessary(ctx, type, createResponse(responseObject, cmd));
        } catch (RejectedExecutionException e) {
            logWarning("RejectedExecutionException occurred when doing SYNC process in RpcRequestProcessor");
            sendResponseIfNecessary(ctx, type, createExceptionResponse(id, ResponseStatus.SERVER_THREADPOOL_BUSY));
        } catch (Throwable t) {
            logError("SYNC process rpc request failed in RpcRequestProcessor, id=" + id, t);
            sendResponseIfNecessary(ctx, type, createExceptionResponse(id, t, "SYNC process rpc request failed in RpcRequestProcessor, id=" + id));
        }
    }
}

