/**
 * Selects a random connection from a list and returns it if it is fine.
 * If no fine connection is found after a maximum number of tries, returns null.
 *
 * @param conns the list of connections to select from
 * @return a fine connection or null if none found
 */
private Connection randomGet(List<Connection> conns) {
    if (conns == null || conns.isEmpty()) {
        return null;
    }
    int size = conns.size();
    int tries = 0;
    Connection result = null;
    while ((result == null || !result.isFine()) && tries++ < MAX_TIMES) {
        result = conns.get(this.random.nextInt(size));
    }
    if (result != null && !result.isFine()) {
        result = null;
    }
    return result;
}

