        log.error("Protocol error: Payload is not UTF-8");
        throw new InvalidDataException(CloseFrame.NO_UTF8);
    }

    // Check if the current continuous frame contains a correct payload with the other frames combined
    if (curop == Opcode.CONTINUOUS && currentContinuousFrame != null) {
        addToBufferList(frame.getPayloadData());
    }
