/**
 * Processes the frame closing event for a WebSocket connection.
 * 
 * @param webSocketImpl The WebSocket implementation instance.
 * @param frame The frame data received.
 */
private void processFrameClosing(WebSocketImpl webSocketImpl, Framedata frame) {
    int code = CloseFrame.NOCODE;
    String reason = "";

    // Extract close code and reason from the frame if it's a CloseFrame
    if (frame instanceof CloseFrame) {
        CloseFrame cf = (CloseFrame) frame;
        code = cf.getCloseCode();
        reason = cf.getMessage();
    }

    // Check the current ready state of the WebSocket
    if (webSocketImpl.getReadyState() == ReadyState.CLOSING) {
        // Complete the close handshake by disconnecting the WebSocket
        webSocketImpl.closeConnection(code, reason, true);
    } else {
        // Echo the close handshake based on the handshake type
        if (getCloseHandshakeType() == CloseHandshakeType.TWOWAY) {
            webSocketImpl.close(code, reason, true);
        } else {
            webSocketImpl.flushAndClose(code, reason, false);
        }
    }
}

