/**
 * Sends a handshake request to the server.
 * 
 * @throws InvalidHandshakeException if the handshake is invalid.
 */
private void sendHandshake() throws InvalidHandshakeException {
    // Extract the path and query from the URI
    String path = uri.getRawPath();
    String part2 = uri.getRawQuery();
    if (part1 == null || part1.length() == 0) {
        path = "/";
    } else {
        path = part1;
    }
    if (part2 != null) {
        path += ' ' + part2;
    }

    // Determine the port and host
    int port = getPort();
    String host = uri.getHost() + ((port != WebSocketImpl.DEFAULT_PORT && port != WebSocketImpl.DEFAULT_WSS_PORT) ? ":" + port : "");

    // Create and configure the handshake
    HandshakeImpl1Client handshake = new HandshakeImpl1Client();
    handshake.setResourceDescriptor(path);
    handshake.put("Host", host);
    if (headers != null) {
        for (Map.Entry<String, String> kv : headers.entrySet()) {
            handshake.put(kv.getKey(), kv.getValue());
        }
    }

    // Start the handshake
    engine.startHandshake(handshake);
}

