/**
 * Broadcasts data to a collection of WebSocket clients.
 * 
 * @param data The data to broadcast, which can be a String or ByteBuffer.
 * @param clients The collection of WebSocket clients to receive the data.
 */
private void doBroadcast(Object data, Collection<WebSocket> clients) {
    String sData = null;
    ByteBuffer bData = null;

    // Convert data to appropriate type
    if (data instanceof String) {
        sData = (String) data;
    } else if (data instanceof ByteBuffer) {
        bData = (ByteBuffer) data;
    }

    // If no valid data, return
    if (sData == null && bData == null) {
        return;
    }

    // Map to hold draft frames for each draft
    Map<Draft, List<Framedata>> draftFrames = new HashMap<>();

    // Iterate over each client
    for (WebSocket client : clients) {
        if (client != null) {
            Draft draft = client.getDraft();
            fillFrames(draft, draftFrames, sData, bData);

            try {
                // Send frames to the client
                client.sendFrame(draftFrames.get(draft));
            } catch (WebsocketNotConnectedException e) {
                // Ignore this exception
            }
        }
    }
}

