/**
 * Fills the frames for a given draft.
 * 
 * @param draft The draft to fill frames for.
 * @param draftFrames A map to store the draft and its corresponding frames.
 * @param sData A string data to create frames from.
 * @param bData A byte buffer data to create frames from.
 */
private void fillFrames(Draft draft, Map<Draft, List<Framedata>> draftFrames, String sData, ByteBuffer bData) {
    if (!draftFrames.containsKey(draft)) {
        List<Framedata> frames = null;
        if (sData != null) {
            frames = draft.createFrames(sData, false);
        }
        if (bData != null) {
            frames = draft.createFrames(bData, false);
        }
        if (frames != null) {
            draftFrames.put(draft, frames);
        }
    }
}

