/**
 * This method handles the execution of a request within a context. It first attempts to retrieve a context from the thread-local storage. If a context is found, it updates the context with the new request and calls itself recursively with the updated context. If no context is found, it creates a new context, updates it with the new request, and calls itself recursively with the new context.
 *
 * @param req The request to be executed.
 * @return A CompletionStage containing the result of the request execution.
 */
public CompletionStage<Result> call(Request req) {
    return Context.safeCurrent()
        .map(threadLocalCtx -> {
            Context newCtx = threadLocalCtx.withRequest(req.removeAttr(CTX_ARGS));
            Context.setCurrent(newCtx);
            return call(newCtx);
        })
        .orElseGet(() -> {
            Context ctx = new Context(req.removeAttr(CTX_ARGS), contextComponents);
            ctx.args = req.attrs().getOptional(CTX_ARGS).orElse(new HashMap<>());
            return call(ctx);
        });
}

