/**
 * Removes a range of handlers from a linked list of handlers.
 *
 * @param firstHandler The first handler in the linked list.
 * @param start The start label of the range to remove.
 * @param end The end label of the range to remove.
 * @return The updated linked list of handlers with the specified range removed.
 */
static Handler removeRange(final Handler firstHandler, final Label start, final Label end) {
    if (firstHandler == null) {
        return null;
    }

    firstHandler.nextHandler = removeRange(firstHandler.nextHandler, start, end);

    int handlerStart = firstHandler.startPc.bytecodeOffset;
    int handlerEnd = firstHandler.endPc.bytecodeOffset;
    int rangeStart = start.bytecodeOffset;
    int rangeEnd = end == null ? Integer.MAX_VALUE : end.bytecodeOffset;

    if (rangeStart >= handlerEnd || rangeEnd <= handlerStart) {
        return firstHandler;
    }

    if (rangeStart <= handlerStart) {
        if (rangeEnd >= handlerEnd) {
            return firstHandler.nextHandler;
        } else {
            return new Handler(firstHandler, end, firstHandler.endPc);
        }
    } else if (rangeEnd >= handlerEnd) {
        return new Handler(firstHandler, firstHandler.startPc, start);
    } else {
        firstHandler.nextHandler = new Handler(firstHandler, end, firstHandler.endPc);
        return new Handler(firstHandler, firstHandler.startPc, start);
    }
}

