 * 
 * @param file The JAR file to scan.
 */
protected void scanJarFile(final File file) {
    ZipFile zipFile = null;
    try {
        zipFile = new ZipFile(file);
        Enumeration entries = zipFile.entries();
        while (entries.hasMoreElements()) {
            ZipEntry zipEntry = (ZipEntry) entries.nextElement();
            String zipEntryName = zipEntry.getName();
            if (StringUtil.endsWithIgnoreCase(zipEntryName, CLASS_FILE_EXT)) {
                scanEntry(new ClassPathEntry(prepareEntryName(zipEntryName, true), zipFile, zipEntry));
            } else if (includeResources) {
                scanEntry(new ClassPathEntry(prepareEntryName(zipEntryName, false), zipFile, zipEntry));
            }
        }
    } catch (IOException ioex) {
        if (!ignoreException) {
            throw new FindFileException("Invalid zip: " + file.getName(), ioex);
        }
    } catch (RuntimeException rex) {
        if (!ignoreException) {
            ZipUtil.close(zipFile);
            throw rex;
        }
    } finally {
        ZipUtil.close(zipFile);
    }
}

