/**
 * Resolves bean names for a given type.
 * 
 * @param type The class type to resolve bean names for.
 * @return An array of bean names that match the given type.
 */
protected String[] resolveBeanNamesForType(final Class type) {
    // Retrieve bean names from cache
    String[] beanNames = beanCollections.get(type);
    if (beanNames != null) {
        return beanNames;
    }

    // Create a list to store matching bean names
    ArrayList<String> list = new ArrayList<>();

    // Iterate through all bean definitions
    for (Map.Entry<String, BeanDefinition> entry : beans.entrySet()) {
        BeanDefinition beanDefinition = entry.getValue();
        // Check if the bean definition type matches the given type
        if (ClassUtil.isTypeOf(beanDefinition.type, type)) {
            String beanName = entry.getKey();
            list.add(beanName);
        }
    }

    // If no matching bean names are found, return an empty array
    if (list.isEmpty()) {
        beanNames = StringPool.EMPTY_ARRAY;
    } else {
        // Convert the list to an array and store in cache
        beanNames = list.toArray(new String[0]);
    }

    // Store the resolved bean names in cache
    beanCollections.put(type, beanNames);
    return beanNames;
}

