public static void loadMethodArgument(MethodVisitor mv, MethodInfo methodInfo, int index) {
    int offset = methodInfo.getArgumentOffset(index);
    int type = methodInfo.getArgument(index).getOpcode();
    switch (type) {
        case 'I': mv.visitVarInsn(ILOAD, offset); break;
        case 'J': mv.visitVarInsn(LLOAD, offset); break;
        case 'F': mv.visitVarInsn(FLOAD, offset); break;
        case 'D': mv.visitVarInsn(DLOAD, offset); break;
        default: mv.visitVarInsn(ALOAD, offset);
    }
}

