 * If no dot is found, returns the index of the last space. If neither is found, returns -1.
 *
 * @param str The input string to search.
 * @return The index of the last dot or space, or -1 if neither is found.
 */
public static int lastIndexOfSlashDot(final String str) {
    int slashNdx = str.lastIndexOf(' ');
    int dotNdx = StringUtil.lastIndexOf(str, ' ', str.length(), slashNdx);
    if (dotNdx == -1) {
        if (slashNdx == -1) {
            return -1;
        }
        slashNdx++;
        if (slashNdx < str.length() - 1) {
            dotNdx = slashNdx;
        } else {
            dotNdx = -1;
        }
    }
    return dotNdx;
}

