/**
 * Adds a file or directory to a ZIP output stream.
 *
 * @param zos        the ZIP output stream
 * @param file       the file or directory to add
 * @param path       the path of the file or directory in the ZIP archive
 * @param comment    the comment for the ZIP entry
 * @param recursive  whether to add the directory recursively
 * @throws IOException if an I/O error occurs
 */
public static void addToZip(final ZipOutputStream zos, final File file, String path, final String comment, final boolean recursive) throws IOException {
    if (!file.exists()) {
        throw new FileNotFoundException(file.toString());
    }
    if (path == null) {
        path = file.getName();
    }
    while (path.length() != 0 && path.charAt(0) == ' ') {
        path = path.substring(1);
    }
    boolean isDir = file.isDirectory();
    if (isDir) {
        if (!StringUtil.endsWithChar(path, ' ')) {
            path += ' ';
        }
    }
    ZipEntry zipEntry = new ZipEntry(path);
    zipEntry.setTime(file.lastModified());
    if (comment != null) {
        zipEntry.setComment(comment);
    }
    if (isDir) {
        zipEntry.setSize(0);
        zipEntry.setCrc(0);
    }
    zos.putNextEntry(zipEntry);
    if (!isDir) {
        InputStream is = new FileInputStream(file);
        try {
            StreamUtil.copy(is, zos);
        } finally {
            StreamUtil.close(is);
        }
    }
    zos.closeEntry();
    if (recursive && file.isDirectory()) {
        boolean noRelativePath = StringUtil.isEmpty(path);
        final File[] children = file.listFiles();
        if (children != null && children.length != 0) {
            for (File child : children) {
                String childRelativePath = (noRelativePath ? StringPool.EMPTY : path) + child.getName();
                addToZip(zos, child, childRelativePath, comment, recursive);
            }
        }
    }
}

