public static void addToZip(ZipOutputStream zos, byte[] content, String path, String comment) throws IOException {
    // Trim leading spaces from the path
    while (path.length() != 0 && path.charAt(0) == ' ') {
        path = path.substring(1);
    }
    // Trim trailing spaces from the path
    if (StringUtil.endsWithChar(path, ' ')) {
        path = path.substring(0, path.length() - 1);
    }
    // Create a new ZipEntry with the trimmed path
    ZipEntry zipEntry = new ZipEntry(path);
    // Set the current time as the entry's modification time
    zipEntry.setTime(System.currentTimeMillis());
    // Set the comment for the zip entry if provided
    if (comment != null) {
        zipEntry.setComment(comment);
    }
    // Add the zip entry to the zip output stream
    zos.putNextEntry(zipEntry);
    // Create an input stream from the content bytes
    InputStream is = new ByteArrayInputStream(content);
    try {
        // Copy the content to the zip output stream
        StreamUtil.copy(is, zos);
    } finally {
        // Close the input stream
        StreamUtil.close(is);
    }
    // Close the current zip entry
    zos.closeEntry();
}

