/**
 * Reads verification type information from a given offset in a bytecode frame.
 *
 * @param verificationTypeInfoOffset The offset in the bytecode where the verification type information starts.
 * @param frame The array representing the current frame.
 * @param index The index in the frame array where the verification type information should be stored.
 * @param charBuffer A buffer to read class names.
 * @param labels An array of labels for uninitialized types.
 * @return The updated offset after reading the verification type information.
 * @throws IllegalArgumentException If the tag is not recognized.
 */
private int readVerificationTypeInfo(final int verificationTypeInfoOffset, final Object[] frame, final int index, final char[] charBuffer, final Label[] labels) {
    int currentOffset = verificationTypeInfoOffset;
    int tag = b[currentOffset++] & 0xFF;
    switch (tag) {
        case Frame.ITEM_TOP:
            frame[index] = Opcodes.TOP;
            break;
        case Frame.ITEM_INTEGER:
            frame[index] = Opcodes.INTEGER;
            break;
        case Frame.ITEM_FLOAT:
            frame[index] = Opcodes.FLOAT;
            break;
        case Frame.ITEM_DOUBLE:
            frame[index] = Opcodes.DOUBLE;
            break;
        case Frame.ITEM_LONG:
            frame[index] = Opcodes.LONG;
            break;
        case Frame.ITEM_NULL:
            frame[index] = Opcodes.NULL;
            break;
        case Frame.ITEM_UNINITIALIZED_THIS:
            frame[index] = Opcodes.UNINITIALIZED_THIS;
            break;
        case Frame.ITEM_OBJECT:
            frame[index] = readClass(currentOffset, charBuffer);
            currentOffset += 2;
            break;
        case Frame.ITEM_UNINITIALIZED:
            frame[index] = createLabel(readUnsignedShort(currentOffset), labels);
            currentOffset += 2;
            break;
        default:
            throw new IllegalArgumentException();
    }
    return currentOffset;
}

