/**
 * Requests a resource of the specified type.
 * 
 * @param <E> The type of the resource.
 * @param resourceType The class of the resource to request.
 * @return The requested resource.
 * @throws JtxException If the transaction is already completed, marked as rollback only, or not active.
 * @throws JtxException If the transaction has already reached the maximum number of resources.
 */
public <E> E requestResource(final Class<E> resourceType) {
    if (isCompleted()) {
        throw new JtxException("TX is already completed, resources are not available after commit or rollback");
    }
    if (isRollbackOnly()) {
        throw new JtxException("TX is marked as rollback only, resources are not available", rollbackCause);
    }
    if (!isNoTransaction() && !isActive()) {
        throw new JtxException("Resources are not available since TX is not active");
    }
    checkTimeout();
    E resource = lookupResource(resourceType);
    if (resource == null) {
        int maxResources = txManager.getMaxResourcesPerTransaction();
        if ((maxResources != -1) && (resources.size() >= maxResources)) {
            throw new JtxException("TX already has attached max. number of resources");
        }
        JtxResourceManager<E> resourceManager = txManager.lookupResourceManager(resourceType);
        resource = resourceManager.beginTransaction(mode, isActive());
        resources.add(new JtxResource<>(this, resourceManager, resource));
    }
    return resource;
}

