/**
 * Removes the last child node from the given parent node if it is a text node and its content is blank.
 * If the parent node has a closed tag and only one child node, it will not remove the last child node.
 *
 * @param parentNode The parent node from which the last child node may be removed.
 * @param closedTag  Indicates whether the parent node has a closed tag.
 */
protected void removeLastChildNodeIfEmptyText(final Node parentNode, final boolean closedTag) {
    if (parentNode == null) {
        return;
    }
    Node lastChild = parentNode.getLastChild();
    if (lastChild == null) {
        return;
    }
    if (lastChild.getNodeType() != Node.NodeType.TEXT) {
        return;
    }
    if (closedTag && parentNode.getChildNodesCount() == 1) {
        return;
    }
    Text text = (Text) lastChild;
    if (text.isBlank()) {
        lastChild.detachFromParent();
    }
}

