/**
 * Converts a type descriptor to a class name.
 *
 * @param desc The type descriptor to convert.
 * @return The corresponding class name.
 * @throws IllegalArgumentException if the type descriptor is invalid.
 */
public static String typedesc2ClassName(final String desc) {
    String className = desc;
    switch (desc.charAt(0)) {
        case 'L':
            if (desc.length() != 1) {
                throw new IllegalArgumentException(INVALID_BASE_TYPE + desc);
            }
            break;
        case '[':
            className = className.substring(1, className.length() - 1);
            break;
        case 'L':
            className = className.replace(' ', ' ');
            break;
        default:
            throw new IllegalArgumentException(INVALID_TYPE_DESCRIPTION + desc);
    }
    return className;
}

