/**
 * Converts a type descriptor to its corresponding signature.
 *
 * @param desc The type descriptor.
 * @param from The starting index and mutable integer.
 * @return The signature of the type.
 * @throws IllegalArgumentException if the type description is invalid.
 */
public static String typedescToSignature(final String desc, final MutableInteger from) {
    int fromIndex = from.get();
    from.value++; // default usage for most cases

    switch (desc.charAt(fromIndex)) {
        case 'B': return "byte";
        case 'C': return "char";
        case 'D': return "double";
        case 'F': return "float";
        case 'I': return "int";
        case 'J': return "long";
        case 'S': return "short";
        case 'Z': return "boolean";
        case 'V': return "void";
        case 'L': {
            int index = desc.indexOf(' ', fromIndex);
            if (index < 0) {
                throw new IllegalArgumentException(INVALID_TYPE_DESCRIPTION + desc);
            }
            from.set(index + 1);
            String str = desc.substring(fromIndex + 1, index);
            return str.replace(' ', '');
        }
        case '[': {
            StringBuilder brackets = new StringBuilder();
            int n = fromIndex;
            while (desc.charAt(n) == '[') { // count opening brackets
                brackets.append("[]");
                n++;
            }
            from.value = n;
            String type = typedescToSignature(desc, from); // the rest of the string denotes a `<field_type>'
            return type + brackets;
        }
        default: {
            if (from.value == 0) {
                throw new IllegalArgumentException(INVALID_TYPE_DESCRIPTION + desc);
            }
            // generics!
            return desc.substring(from.value);
        }
    }
}

