/**
 * Creates a collection of type T with the specified length.
 * If the collection type is an interface, it creates an instance of the interface.
 * If the length is greater than 0, it attempts to create a collection with the specified length using a constructor that takes an int parameter.
 * If the length is 0, it attempts to create a collection without specifying the length.
 * If the collection type is not an interface or the constructor throws an exception, it attempts to create a collection using the default constructor.
 * If all attempts fail, it throws a TypeConversionException.
 *
 * @param length the length of the collection to create
 * @return a collection of type T
 * @throws TypeConversionException if the collection type is unknown or the constructor throws an exception
 */
@SuppressWarnings("unchecked")
protected Collection<T> createCollection(final int length) {
    if (collectionType.isInterface()) {
        if (collectionType == List.class) {
            return length > 0 ? new ArrayList<>(length) : new ArrayList<>();
        } else if (collectionType == Set.class) {
            return length > 0 ? new HashSet<>(length) : new HashSet<>();
        } else {
            throw new TypeConversionException("Unknown collection: " + collectionType.getName());
        }
    }
    if (length > 0) {
        try {
            Constructor<Collection<T>> ctor = (Constructor<Collection<T>>) collectionType.getConstructor(int.class);
            return ctor.newInstance(Integer.valueOf(length));
        } catch (Exception ex) {
            // ignore exception
        }
    }
    try {
        return collectionType.getDeclaredConstructor().newInstance();
    } catch (Exception ex) {
        throw new TypeConversionException(ex);
    }
}

