/**
 * Puts a reference into the bytecode.
 *
 * @param code the bytecode vector
 * @param sourceInsnBytecodeOffset the offset of the source instruction bytecode
 * @param wideReference whether the reference is wide
 */
final void put(final ByteVector code, final int sourceInsnBytecodeOffset, final boolean wideReference) {
    if ((flags & FLAG_RESOLVED) == 0) {
        if (wideReference) {
            addForwardReference(sourceInsnBytecodeOffset, FORWARD_REFERENCE_TYPE_WIDE, code.length);
            code.putInt(-1);
        } else {
            addForwardReference(sourceInsnBytecodeOffset, FORWARD_REFERENCE_TYPE_SHORT, code.length);
            code.putShort(-1);
        }
    } else {
        if (wideReference) {
            code.putInt(bytecodeOffset - sourceInsnBytecodeOffset);
        } else {
            code.putShort(bytecodeOffset - sourceInsnBytecodeOffset);
        }
    }
}

