/**
 * Authenticates a user via HTTP session and rotates the authentication token.
 *
 * @param actionRequest The action request containing the HTTP servlet request.
 * @return The new authentication token if rotation is successful, otherwise null.
 */
protected T authenticateUserViaHttpSession(final ActionRequest actionRequest) {
    final HttpServletRequest servletRequest = actionRequest.getHttpServletRequest();
    final UserSession<T> userSession = UserSession.get(servletRequest);
    if (userSession == null) {
        return null;
    }
    final T authToken = userSession.getAuthToken();
    if (authToken == null) {
        return null;
    }
    // Rotate the token
    final T newAuthToken = userAuth().rotateToken(authToken);
    if (newAuthToken != authToken) {
        final UserSession<T> newUserSession = new UserSession<>(newAuthToken, userAuth().tokenValue(newAuthToken));
        newUserSession.start(servletRequest, actionRequest.getHttpServletResponse());
    }
    return newAuthToken;
}

