        // Check if the type is a collection
        if (ClassUtil.isTypeOf(type, Collection.class)) {
            // Get the component type of the collection
            Class<?> componentType = setter.getSetterRawComponentType();
            // Convert the value to a collection
            value = convertToCollection(value, type, componentType);
        } else {
            // Convert the value to the setter's type
            value = convertType(value, type);
        }

        // Invoke the setter method
        setter.invokeSetter(bp.bean, value);
    } catch (Exception ex) {
        // Handle exceptions based on the silent flag
        if (isSilent) {
            return null;
