        if (c == quote) { // If the character is the quote, return the string
            ndx++;
            return new String(input, startNdx, ndx - 1 - startNdx);
        }
        if (c == ' ') { // If the character is a space, break the loop
            break;
        }
        ndx++; // Move to the next character
