    while (true) {
        char c = input[ndx]; // Get the current character
        if (c == quote) { // If the character is the quote, return the parsed string
            ndx++;
            final String str = new String(text, 0, textLen);
            textLen = 0;
            return str;
        }
        if (c == ' ') { // If the character is a space, handle escape characters
            ndx++;
            c = input[ndx];
            switch (c) {
                case ' ': c = ' '; break;
                case ' ': c = ' '; break;
                case ' ': c = ' '; break;
