public void runJoy(Consumer<JoddJoyRuntime> consumer) {
    // Initialize JoddJoy and start the backend
    JoddJoy joddJoy = new JoddJoy();
    JoddJoyRuntime joyRuntime = joddJoy.startOnlyBackend();

    // Set the JtxManager from JoddJoyRuntime
    joddJoy.withDb(joyDb -> setJtxManager(joyRuntime.getJtxManager()));

    // Start a read-write transaction
    JtxTransaction tx = startRwTx();

    // Create a Print object for logging
    Print print = new Print();

    try {
        // Log the start of the operation
        print.line("START", 80);
        print.newLine();

        // Execute the provided consumer with the JoddJoyRuntime
        consumer.accept(joyRuntime);

        // Log the end of the operation
        print.newLine();
        print.line("END", 80);

        // Commit the transaction if it was started
        if (tx != null) {
            tx.commit();
        }
    } catch (Throwable throwable) {
        // Print the stack trace if an exception occurs
        throwable.printStackTrace();

        // Rollback the transaction if it was started
        if (tx != null) {
            tx.rollback();
        }
    } finally {
        // Stop the JoddJoy instance
        joddJoy.stop();
    }
}

