/**
 * Parses a descriptor string to determine the abstract type.
 *
 * @param symbolTable The symbol table to use for adding types.
 * @param buffer The buffer containing the descriptor string.
 * @param offset The offset within the buffer where the descriptor starts.
 * @return The abstract type represented by the descriptor.
 * @throws IllegalArgumentException If the descriptor is invalid.
 */
private static int getAbstractTypeFromDescriptor(final SymbolTable symbolTable, final String buffer, final int offset) {
    char descriptorChar = buffer.charAt(offset);
    switch (descriptorChar) {
        case ' ':
            return 0;
        case 'I':
            return INTEGER;
        case 'F':
            return FLOAT;
        case 'J':
            return LONG;
        case 'D':
            return DOUBLE;
        case 'L':
            String internalName = buffer.substring(offset + 1, buffer.length() - 1);
            return REFERENCE_KIND | symbolTable.addType(internalName);
        case '[':
            int elementDescriptorOffset = offset + 1;
            while (buffer.charAt(elementDescriptorOffset) == '[') {
                ++elementDescriptorOffset;
            }
            int typeValue;
            switch (buffer.charAt(elementDescriptorOffset)) {
                case 'Z':
                    typeValue = BOOLEAN;
                    break;
                case 'C':
                    typeValue = CHAR;
                    break;
                case 'B':
                    typeValue = BYTE;
                    break;
                case 'S':
                    typeValue = SHORT;
                    break;
                case 'I':
                    typeValue = INTEGER;
                    break;
                case 'F':
                    typeValue = FLOAT;
                    break;
                case 'J':
                    typeValue = LONG;
                    break;
                case 'D':
                    typeValue = DOUBLE;
                    break;
                case 'L':
                    internalName = buffer.substring(elementDescriptorOffset + 1, buffer.length() - 1);
                    typeValue = REFERENCE_KIND | symbolTable.addType(internalName);
                    break;
                default:
                    throw new IllegalArgumentException();
            }
            return ((elementDescriptorOffset - offset) << DIM_SHIFT) | typeValue;
        default:
            throw new IllegalArgumentException();
    }
}

