/**
 * Determines if a given value matches a specific condition based on the values of `a` and `b`.
 * 
 * @param value The value to be checked.
 * @return true if the value matches the condition, false otherwise.
 */
public boolean match(final int value) {
    if (a == 0) {
        return value == b;
    }
    if (a > 0) {
        if (value < b) {
            return false;
        }
        return (value - b) % a == 0;
    }
    if (value > b) {
        return false;
    }
    return (b - value) % (-a) == 0;
}

