/**
 * Attempts to unblock a term in a log buffer.
 *
 * @param termBuffers       Array of term buffers.
 * @param logMetaDataBuffer Log metadata buffer.
 * @param blockedPosition   Position of the blocked term.
 * @param termLength        Length of each term.
 * @return true if the term is successfully unblocked, false otherwise.
 */
public static boolean unblock(final UnsafeBuffer[] termBuffers, final UnsafeBuffer logMetaDataBuffer, final long blockedPosition, final int termLength) {
    int positionBitsToShift = LogBufferDescriptor.positionBitsToShift(termLength);
    int blockedTermCount = (int)(blockedPosition >> positionBitsToShift);
    int blockedOffset = (int)blockedPosition & (termLength - 1);
    int activeTermCount = activeTermCount(logMetaDataBuffer);

    if (activeTermCount == (blockedTermCount - 1) && blockedOffset == 0) {
        int currentTermId = termId(rawTailVolatile(logMetaDataBuffer, indexByTermCount(activeTermCount)));
        return rotateLog(logMetaDataBuffer, activeTermCount, currentTermId);
    }

    int blockedIndex = indexByTermCount(blockedTermCount);
    long rawTail = rawTailVolatile(logMetaDataBuffer, blockedIndex);
    int termId = termId(rawTail);
    int tailOffset = termOffset(rawTail, termLength);
    UnsafeBuffer termBuffer = termBuffers[blockedIndex];

    switch (TermUnblocker.unblock(logMetaDataBuffer, termBuffer, blockedOffset, tailOffset, termId)) {
        case UNBLOCKED_TO_END:
            rotateLog(logMetaDataBuffer, blockedTermCount, termId);
            // fall through
        case UNBLOCKED:
            return true;
    }

    return false;
}

