public void setByte(long index, byte value) {
    // Check if the index is within the current size of bytesUsed
    checkArgument(index < bytesUsed, "Index: " + index + " is >= the current size of: " + bytesUsed);

    long seen = 0;
    // Iterate through each slab in the slabs list
    for (int i = 0; i < slabs.size(); i++) {
        ByteBuffer slab = slabs.get(i);
        // Check if the index is within the current slab
        if (index < seen + slab.limit()) {
            // Set the byte value at the specified index within the slab
            slab.put((int)(index - seen), value);
            break;
        }
        // Update the seen variable to account for the current slab's limit
        seen += slab.limit();
    }
}

