                LOGGER.info(e.getMessage());
                return RowRanges.createSingle(rowCount);
            }
        }

        @Override
        public RowRanges visit(UnboundRecordFilterCompat unboundRecordFilterCompat) {
            return RowRanges.createSingle(rowCount);
        }

        @Override
        public RowRanges visit(NoOpFilter noOpFilter) {
            return RowRanges.createSingle(rowCount);
