    // Check if data upgrade is needed
    if (!issues.isEmpty()) {
        return null;
    }

    upgrade = needsUpgrade(library, pipelineConf, issues);
    if (upgrade && issues.isEmpty()) {
        pipelineConf = upgrade(library, pipelineConf, issues);
    }

    return (issues.isEmpty()) ? pipelineConf : null;
}

