/**
 * Converts a record and a field to a Protobuf message.
 *
 * @param record The record containing the data.
 * @param field The field to convert.
 * @param fieldPath The path of the field.
 * @param desc The descriptor of the message.
 * @param messageTypeToExtensionMap The map of message types to extensions.
 * @param defaultValueMap The map of default values.
 * @return The Protobuf message.
 * @throws DataGeneratorException If an error occurs during the conversion.
 */
private static DynamicMessage sdcFieldToProtobufMsg(Record record, Field field, String fieldPath, Descriptors.Descriptor desc, Map<String, Set<Descriptors.FieldDescriptor>> messageTypeToExtensionMap, Map<String, Object> defaultValueMap) throws DataGeneratorException {
    if (field == null) {
        return null;
    }

    // Compute all fields to look for including extensions
    DynamicMessage.Builder builder = DynamicMessage.newBuilder(desc);
    List<Descriptors.FieldDescriptor> fields = new ArrayList<>();
    fields.addAll(desc.getFields());
    if (messageTypeToExtensionMap.containsKey(desc.getFullName())) {
        fields.addAll(messageTypeToExtensionMap.get(desc.getFullName()));
    }

    // Root field is always a Map in a record representing protobuf data
    Map<String, Field> valueAsMap = field.getValueAsMap();

    for (Descriptors.FieldDescriptor f : fields) {
        Field mapField = valueAsMap.get(f.getName());

        // Handle repeated field
        if (f.isRepeated()) {
            if (mapField != null) {
                handleRepeatedField(record, mapField, fieldPath, messageTypeToExtensionMap, defaultValueMap, f, builder);
            }
        } else if (f.isMapField()) {
            // Handle map field
            handleMapField(record, mapField, fieldPath, messageTypeToExtensionMap, defaultValueMap, f, builder);
        } else {
            // Handle non-repeated field
            handleNonRepeatedField(record, valueAsMap, fieldPath, messageTypeToExtensionMap, defaultValueMap, desc, f, builder);
        }
    }

    // Handle unknown fields for this field path
    try {
        handleUnknownFields(record, fieldPath, builder);
    } catch (IOException e) {
        throw new DataGeneratorException(Errors.PROTOBUF_05, e.toString(), e);
    }

    return builder.build();
}

