/**
 * Retrieves the lineage publisher definition for a given name.
 *
 * @param name The name of the lineage publisher.
 * @return The lineage publisher definition.
 * @throws IllegalArgumentException if the definition is missing.
 * @throws IllegalStateException if the definition is invalid or the publisher cannot be found.
 */
private LineagePublisherDefinition getDefinition(String name) {
    String defConfig = LineagePublisherConstants.configDef(name);
    String publisherDefinition = configuration.get(defConfig, null);
    if (StringUtils.isEmpty(publisherDefinition)) {
        throw new IllegalArgumentException(Utils.format("Missing definition '{}'", defConfig));
    }
    String[] lineagePluginDefs = publisherDefinition.split("::");
    if (lineagePluginDefs.length != 2) {
        throw new IllegalStateException(Utils.format("Invalid definition '{}', expected $libraryName::$publisherName", publisherDefinition));
    }
    LineagePublisherDefinition def = stageLibraryTask.getLineagePublisherDefinition(lineagePluginDefs[0], lineagePluginDefs[1]);
    if (def == null) {
        throw new IllegalStateException(Utils.format("Can't find publisher '{}'", publisherDefinition));
    }
    return def;
}

