 * Retrieves the column type from a JSON field.
 * 
 * @param field The JSON field containing the column type information.
 * @return The class type of the column.
 * @throws GPUdbException If an error occurs while getting the column type.
 */
private Class<?> getColumnType(JSONObject field) throws GPUdbException {
    Class<?> columnType = null;

    // Check if the "type" element is an array (nullable type)
    if (field.get("type") instanceof JSONArray) {
        JSONArray columnTypes = field.getJSONArray("type");
        for (int j = 0; j < columnTypes.length(); j++) {
            String ct = (String) columnTypes.get(j);
            if (!ct.equals("null")) {
                columnType = getClassForType(ct);
                break;
            }
        }
    } else {
        columnType = getClassForType(field.getString("type"));
    }

    // Throw an exception if the column type is still null
    if (columnType == null) {
        throw new GPUdbException("Error getting column type for field: " + field.toString());
    }

    return columnType;
}

