 * Retrieves the decimal scale or precision from a field attribute, using a default value if the attribute is invalid.
 * 
 * @param record The record containing the field.
 * @param field The field to retrieve the attribute from.
 * @param attributeName The name of the attribute to retrieve.
 * @param defaultValue The default value to use if the attribute is invalid.
 * @param minAllowed The minimum allowed value for the attribute.
 * @return The decimal scale or precision value.
 * @throws OnRecordErrorException If the default value is invalid.
 */
private int getDecimalScaleOrPrecision(Record record, Field field, String attributeName, int defaultValue, int minAllowed) throws OnRecordErrorException {
    int finalValue = -1; // Invalid value
    // Try to retrieve the attribute value as a string
    String stringValue = field.getAttribute(attributeName);
    if (!StringUtils.isEmpty(stringValue)) {
        finalValue = Integer.valueOf(stringValue);
    }
    // If the attribute value is invalid, use the default value
    if (finalValue < minAllowed) {
        finalValue = defaultValue;
    }
    // If the default value is also invalid, throw an error
    if (finalValue < minAllowed) {
        throw new OnRecordErrorException(record, Errors.SCHEMA_GEN_0004, finalValue, field);
    }
    return finalValue;
}

