/**
 * Attempts to fast-forward the channel to the next line.
 * 
 * @return true if the channel was truncated, false otherwise.
 * @throws IOException if an I/O error occurs.
 */
private boolean fastForward() throws IOException {
    try {
        boolean stillTruncate;
        buffer.clear();
        if (channel.read(buffer) > -1 || isEof()) {
            buffer.flip();
            int firstEolIdx = findEndOfFirstLine(buffer);
            if (firstEolIdx > -1) {
                buffer.position(firstEolIdx + 1);
                buffer.compact();
                stillTruncate = false;
                offset = channel.position() - buffer.position();
            } else {
                stillTruncate = true;
                offset = channel.position();
            }
        } else {
            stillTruncate = true;
            offset = channel.position();
        }
        return stillTruncate;
    } catch (IOException ex) {
        closeChannel();
        throw ex;
    }
}

