/**
 * Executes a SQL query and processes the result using the provided execution handler.
 * 
 * @param query The SQL query to execute.
 * @param execution The handler to process the result set.
 * @return The result of the execution.
 * @throws StageException If an exception occurs during query execution or processing.
 */
private <T> T executeQuery(String query, WithResultSet<T> execution) throws StageException {
    LOG.debug("Executing SQL: {}", query);
    Timer.Context t = selectTimer.time();
    try (Statement statement = hiveConfigBean.getHiveConnection().createStatement();
         ResultSet rs = statement.executeQuery(query)) {
        // Stop timer immediately to measure only query execution time
        long time = t.stop();
        LOG.debug("Query '{}' took {} nanoseconds", query, time);
        t = null;
        return execution.run(rs);
    } catch (Exception e) {
        LOG.error("Exception while processing query: {}", query, e);
        throw new HiveStageCheckedException(Errors.HIVE_20, query, e.getMessage());
    } finally {
        // Stop timer if it wasn't stopped due to exception
        if (t != null) {
            long time = t.stop();
            LOG.debug("Query '{}' took {} nanoseconds", query, time);
        }
        selectMeter.mark();
    }
}

