 * @throws StageException If a stage exception occurs.
 */
public void executeBatch(String offsetKey, String offsetValue, long batchStartTime, ThrowingConsumer<Pipe> consumer) throws PipelineRuntimeException, StageException {
    MDC.put(LogConstants.RUNNER, String.valueOf(runnerId)); // Persist static information for the batch
    runtimeMetricGauge.put(METRIC_BATCH_START_TIME, batchStartTime);
    runtimeMetricGauge.put(METRIC_OFFSET_KEY, Optional.ofNullable(offsetKey).orElse(""));
    runtimeMetricGauge.put(METRIC_OFFSET_VALUE, Optional.ofNullable(offsetValue).orElse(""));
    runtimeMetricGauge.put(METRIC_STAGE_START_TIME, System.currentTimeMillis());

    try {
        for (Pipe p : pipes) {
            String instanceName = p.getStage().getInfo().getInstanceName();
            runtimeMetricGauge.put(METRIC_CURRENT_STAGE, instanceName);
            MDC.put(LogConstants.STAGE, instanceName);
            if (p instanceof StagePipe) {
                runtimeMetricGauge.put(METRIC_STAGE_START_TIME, System.currentTimeMillis());
            }
            acceptConsumer(consumer, p);
        }
        // We've successfully finished batch
        runtimeMetricGauge.computeIfPresent(METRIC_BATCH_COUNT, (key, value) -> ((long) value) + 1);
    } finally {
        resetBatchSpecificMetrics();
        MDC.put(LogConstants.RUNNER, "");
        MDC.put(LogConstants.STAGE, "");
    }
}

