/**
 * Executes a consumer on a given pipe and handles any exceptions that may occur.
 * If an exception is caught, it logs an error message with the instance name of the stage
 * and rethrows it as a PipelineRuntimeException or StageException if applicable.
 *
 * @param consumer The consumer to execute on the pipe.
 * @param p The pipe to process.
 * @throws PipelineRuntimeException If the exception is an instance of PipelineRuntimeException.
 * @throws StageException If the exception is an instance of StageException.
 */
private void acceptConsumer(ThrowingConsumer<Pipe> consumer, Pipe p) throws PipelineRuntimeException, StageException {
    try {
        consumer.accept(p);
    } catch (Throwable t) {
        String instanceName = p.getStage().getInfo().getInstanceName();
        LOG.error("Failed executing stage '{}': {}", instanceName, t.toString(), t);
        Throwables.propagateIfInstanceOf(t, PipelineRuntimeException.class);
        Throwables.propagateIfInstanceOf(t, StageException.class);
        Throwables.propagate(t);
    }
}

