/**
 * Determines the parameter class type based on the generic parameter type, method, parameter position, and class loader.
 * 
 * @param genParamType The generic parameter type.
 * @param method The method containing the parameter.
 * @param paramPos The position of the parameter in the method.
 * @param classLoader The class loader to use for loading classes.
 * @return The determined parameter class type, or null if not found.
 */
private Class checkParamType(Type genParamType, final Method method, final int paramPos, final ClassLoader classLoader) {
    Class paramClazz = null;
    if (genParamType instanceof ParameterizedType) {
        ParameterizedType pType = (ParameterizedType) genParamType;
        Type[] actualTypeArgs = pType.getActualTypeArguments();
        if (actualTypeArgs.length == 1) {
            try {
                paramClazz = classLoader.loadClass(actualTypeArgs[0].getTypeName());
            } catch (Exception ee) {
                JAXRS_LOGGER.classIntrospectionFailure(ee.getClass().getName(), ee.getMessage());
            }
        }
    } else {
        Class<?>[] paramArr = method.getParameterTypes();
        if (paramArr[paramPos].isArray()) {
            Class compClazz = paramArr[paramPos].getComponentType();
            if (!compClazz.isPrimitive()) {
                paramClazz = compClazz;
            }
        } else {
            if (!paramArr[paramPos].isPrimitive()) {
                paramClazz = paramArr[paramPos];
            }
        }
    }
    return paramClazz;
}

