/**
 * Returns the Java type signature for a given class.
 * 
 * @param cls The class for which to get the type signature.
 * @return The type signature as a string.
 */
private static String getSignature(Class cls) {
    if (cls.isArray()) {
        return "[" + cls.getComponentType();
    }
    if (cls.isPrimitive()) {
        switch (cls) {
            case Byte.TYPE: return "B";
            case Character.TYPE: return "C";
            case Double.TYPE: return "D";
            case Float.TYPE: return "F";
            case Integer.TYPE: return "I";
            case Long.TYPE: return "J";
            case Short.TYPE: return "S";
            case Boolean.TYPE: return "Z";
            default: throw IIOPLogger.ROOT_LOGGER.unknownPrimitiveType(cls.getName());
        }
    }
    return "L" + cls.getName().replace(' ', ' ') + ";";
}

