synchronized void addListener(final String target, final int scope, final NamingListener namingListener) {
    // Create a TargetScope object with the given target and scope
    final TargetScope targetScope = new TargetScope(target, scope);

    // Check if there is already a holder for the given listener
    ListenerHolder holder = holdersByListener.get(namingListener);
    if (holder == null) {
        // If no holder exists, create a new one and add it to the holdersByListener map
        holder = new ListenerHolder(namingListener, targetScope);
        final Map<NamingListener, ListenerHolder> byListenerCopy = new FastCopyHashMap<>(holdersByListener);
        byListenerCopy.put(namingListener, holder);
        holdersByListener = byListenerCopy;
    } else {
        // If a holder exists, add the target scope to it
        holder.addTarget(targetScope);
    }

    // Get the list of holders for the given target scope
    List<ListenerHolder> holdersForTarget = holdersByTarget.get(targetScope);
    if (holdersForTarget == null) {
        // If no list exists, create a new one and add it to the holdersByTarget map
        holdersForTarget = new CopyOnWriteArrayList<>();
        final Map<TargetScope, List<ListenerHolder>> byTargetCopy = new FastCopyHashMap<>(holdersByTarget);
        byTargetCopy.put(targetScope, holdersForTarget);
        holdersByTarget = byTargetCopy;
    }

    // Add the holder to the list of holders for the given target scope
    holdersForTarget.add(holder);
}

