synchronized void removeListener(final NamingListener namingListener) {
    // Retrieve the listener holder for the given listener
    final ListenerHolder holder = holdersByListener.get(namingListener);
    if (holder == null) {
        return;
    }

    // Create a copy of the holdersByListener map to avoid concurrent modification
    final Map<NamingListener, ListenerHolder> byListenerCopy = new FastCopyHashMap<>(holdersByListener);
    byListenerCopy.remove(namingListener);
    holdersByListener = byListenerCopy;

    // Create a copy of the holdersByTarget map to avoid concurrent modification
    final Map<TargetScope, List<ListenerHolder>> byTargetCopy = new FastCopyHashMap<>(holdersByTarget);
    for (TargetScope targetScope : holder.targets) {
        // Remove the holder from the list of holders for the target scope
        final List<ListenerHolder> holders = holdersByTarget.get(targetScope);
        holders.remove(holder);
        if (holders.isEmpty()) {
            // Remove the target scope if it is empty
            byTargetCopy.remove(targetScope);
        }
    }
    holdersByTarget = byTargetCopy;
}

