void fireEvent(EventContext context, Name name, Binding existingBinding, Binding newBinding, int type, String changeInfo, Integer... scopes) {
    String target = name.toString();
    Set<Integer> scopeSet = new HashSet<>(Arrays.asList(scopes));
    NamingEvent event = new NamingEvent(context, type, newBinding, existingBinding, changeInfo);
    Set<ListenerHolder> holdersToFire = new HashSet<>();

    // Check for OBJECT_SCOPE based listeners
    if (scopeSet.contains(EventContext.OBJECT_SCOPE)) {
        TargetScope targetScope = new TargetScope(target, EventContext.OBJECT_SCOPE);
        List<ListenerHolder> holders = holdersByTarget.get(targetScope);
        if (holders != null) {
            holdersToFire.addAll(holders);
        }
    }

    // Check for ONELEVEL_SCOPE based listeners
    if (scopeSet.contains(EventContext.ONELEVEL_SCOPE) && !name.isEmpty()) {
        TargetScope targetScope = new TargetScope(name.getPrefix(name.size() - 1).toString(), EventContext.ONELEVEL_SCOPE);
        List<ListenerHolder> holders = holdersByTarget.get(targetScope);
        if (holders != null) {
            holdersToFire.addAll(holders);
        }
    }

    // Check for SUBTREE_SCOPE based listeners
    if (scopeSet.contains(EventContext.SUBTREE_SCOPE) && !name.isEmpty()) {
        for (int i = 1; i < name.size(); i++) {
            Name parentName = name.getPrefix(i);
            TargetScope targetScope = new TargetScope(parentName.toString(), EventContext.SUBTREE_SCOPE);
            List<ListenerHolder> holders = holdersByTarget.get(targetScope);
            if (holders != null) {
                holdersToFire.addAll(holders);
            }
        }
    }

    executor.execute(new FireEventTask(holdersToFire, event));
}

