/**
 * Retrieves or creates a ContainerAnalysis for a given class.
 * 
 * @param cls The class for which to retrieve or create the ContainerAnalysis.
 * @return The ContainerAnalysis for the given class.
 * @throws RMIIIOPViolationException If an IOR violation occurs.
 */
ContainerAnalysis getAnalysis(final Class cls) throws RMIIIOPViolationException {
    ContainerAnalysis ret = null;
    boolean created = false;
    try {
        synchronized (this) {
            ret = lookupDone(cls);
            if (ret != null) {
                return ret;
            }
            final ContainerAnalysis inProgress = workInProgress.get(new InProgressKey(cls, Thread.currentThread()));
            if (inProgress != null) {
                return inProgress;
            }
            ret = createWorkInProgress(cls);
        }
        created = true;
        doTheWork(cls, ret);
    } finally {
        synchronized (this) {
            if (created) {
                workInProgress.remove(new InProgressKey(cls, Thread.currentThread()));
                workDone.put(cls, new SoftReference<>(ret));
                ClassLoader classLoader = cls.getClassLoader();
                if (classLoader != null) {
                    Set<Class<?>> classes = classesByLoader.get(classLoader);
                    if (classes == null) {
                        classesByLoader.put(classLoader, classes = new HashSet<Class<?>>());
                    }
                    classes.add(cls);
                }
            }
            notifyAll();
        }
    }
    return ret;
}

