/**
 * Determines if a method is an accessor method.
 * 
 * @param m The method to check.
 * @return true if the method is an accessor, false otherwise.
 */
protected boolean isAccessor(Method m) {
    Class<?> returnType = m.getReturnType();
    String name = m.getName();

    // Check if the method name starts with "get" or "is"
    if (!(name.startsWith("get") && name.length() > "get".length()) &&
        !(name.startsWith("is") && name.length() > "is".length() && returnType == Boolean.TYPE)) {
        return false;
    }

    // Check if the return type is not Void
    if (returnType == Void.TYPE) {
        return false;
    }

    // Check if the method has no parameters
    if (m.getParameterTypes().length != 0) {
        return false;
    }

    // Check if the method has non-application exceptions
    return hasNonAppExceptions(m);
}

