/**
 * Determines if a given method is a mutator method.
 * A mutator method is defined as a method that starts with "set", returns void, and takes exactly one parameter.
 * 
 * @param m The method to check.
 * @return true if the method is a mutator method, false otherwise.
 */
protected boolean isMutator(Method m) {
    String name = m.getName();
    if (!(name.startsWith("set") && name.length() > "set".length())) return false;
    if (m.getReturnType() != Void.TYPE) return false;
    if (m.getParameterTypes().length != 1) return false;
    return hasNonAppExceptions(m);
}

