/**
 * Checks if a method has non-RemoteException exceptions.
 *
 * @param m the method to check
 * @return true if the method has non-RemoteException exceptions, false otherwise
 */
protected boolean hasNonAppExceptions(Method m) {
    Class<?>[] ex = m.getExceptionTypes();
    for (int i = 0; i < ex.length; ++i) {
        if (!java.rmi.RemoteException.class.isAssignableFrom(ex[i])) {
            return false;
        }
    }
    return true;
}

