/**
 * Ensures that a package exists within a given container.
 * 
 * @param c The container to search within.
 * @param previous The previous package path.
 * @param remainder The remaining path to process.
 * @return The ModuleDefImpl representing the package.
 * @throws IRConstructionException If a collision is detected or an error occurs.
 */
private ModuleDefImpl ensurePackageExists(LocalContainer c, String previous, String remainder) throws IRConstructionException {
    if (remainder.isEmpty()) return (ModuleDefImpl) c; // Package already exists
    int idx = remainder.indexOf(' ');
    String base = (idx == -1) ? remainder : remainder.substring(0, idx);
    base = Util.javaToIDLName(base);
    if (previous.isEmpty()) previous = base; else previous = previous + "/" + base;
    remainder = (idx == -1) ? "" : remainder.substring(idx + 1);
    LocalContainer next = null;
    LocalContained contained = (LocalContained) c._lookup(base);
    if (contained instanceof LocalContainer) next = (LocalContainer) contained;
    else if (contained != null) throw IIOPLogger.ROOT_LOGGER.collisionWhileCreatingPackage();
    if (next == null) {
        String id = "IDL:" + previous + ":1.0";
        ModuleDefImpl m = new ModuleDefImpl(id, base, "1.0", c, impl);
        c.add(base, m);
        if (idx == -1) return m; // Package created
        next = (LocalContainer) c._lookup(base); // Ensure package is there
    } else if (next.def_kind() != DefinitionKind.dk_Module) {
        throw IIOPLogger.ROOT_LOGGER.collisionWhileCreatingPackage();
    }
    return ensurePackageExists(next, previous, remainder);
}

