/**
 * Determines the open files limit for the disk cache based on the platform and provided limits.
 *
 * @param verbose     If true, logs detailed information.
 * @param recommended The recommended open files limit.
 * @param defLimit    The default open files limit.
 * @return The open files limit for the disk cache.
 */
public int getOpenFilesLimit(boolean verbose, int recommended, int defLimit) {
    if (Platform.isLinux()) {
        OCLibrary.Rlimit rlimit = new OCLibrary.Rlimit();
        int result = C_LIBRARY.getrlimit(OCLibrary.RLIMIT_NOFILE, rlimit);
        if (result == 0 && rlimit.rlim_cur > 0) {
            if (verbose) {
                OLogManager.instance().infoNoDb(this, "Detected limit of amount of simultaneously open files is %d, " +
                        " limit of open files for disk cache will be set to %d", rlimit.rlim_cur, rlimit.rlim_cur / 2 - 512);
            }
            if (rlimit.rlim_cur < recommended) {
                OLogManager.instance().warnNoDb(this, "Value of limit of simultaneously open files is too small, recommended value is %d", recommended);
            }
            return (int) rlimit.rlim_cur / 2 - 512;
        } else {
            if (verbose) {
                OLogManager.instance().infoNoDb(this, "Can not detect value of limit of open files.");
            }
        }
    } else if (Platform.isWindows()) {
        if (verbose) {
            OLogManager.instance().infoNoDb(this, "Windows OS is detected, %d limit of open files will be set for the disk cache.", recommended);
        }
        return recommended;
    }
    if (verbose) {
        OLogManager.instance().infoNoDb(this, "Default limit of open files (%d) will be used.", defLimit);
    }
    return defLimit;
}

