/**
 * Checks if a class exists in the schema and creates it if it doesn't.
 * If the class exists but is not a subclass of the base class, throws an IllegalArgumentException.
 *
 * @param className The name of the class to check.
 * @return The class name if it exists or is created successfully.
 * @throws IllegalArgumentException If the class exists but is not a subclass of the base class.
 */
protected String checkForClassInSchema(final String className) {
    if (className == null) return null;
    OrientBaseGraph graph = getGraph();
    if (graph == null) return className;
    OSchema schema = graph.getRawGraph().getMetadata().getSchema();
    if (!schema.existsClass(className)) {
        try {
            graph.executeOutsideTx(new OCallable<OClass, OrientBaseGraph>() {
                @Override
                public OClass call(final OrientBaseGraph g) {
                    return schema.createClass(className, schema.getClass(getBaseClassName()));
                }
            }, "Committing the active transaction to create the new type '" + className + "' as subclass of '" + getBaseClassName() + "'. The transaction will be reopened right after that. To avoid this behavior create the classes outside the transaction");
        } catch (OSchemaException e) {
            if (!schema.existsClass(className)) throw e;
        }
    } else {
        OClass cls = schema.getClass(className);
        if (!cls.isSubClassOf(getBaseClassName())) throw new IllegalArgumentException("Class '" + className + "' is not an instance of " + getBaseClassName());
    }
    return className;
}

