/**
 * Retrieves the list of master servers from the cluster configuration.
 * 
 * @return A list of master server addresses.
 */
public List<String> getMasterServers() {
    // Get the list of servers from the cluster configuration.
    List<String> serverList = getClusterConfiguration(null).field(SERVERS);

    // If the server list is not null, process it.
    if (serverList != null) {
        // Create a new list to store master servers.
        List<String> masters = new ArrayList<>(serverList.size());

        // Iterate over the server list and add only those servers that are not marked as NEW_NODE_TAG.
        for (String s : serverList) {
            if (!s.equals(NEW_NODE_TAG)) {
                masters.add(s);
            }
        }

        // Get the default server role.
        ROLES defRole = getDefaultServerRole();

        // Get the server roles from the configuration.
        ODocument servers = configuration.field(SERVERS);

        // If the server roles are not null, filter the master list based on the roles.
        if (servers != null) {
            for (Iterator<String> it = masters.iterator(); it.hasNext();) {
                String server = it.next();
                String roleAsString = servers.field(server);
                ROLES role = roleAsString != null ? ROLES.valueOf(roleAsString.toUpperCase(Locale.ENGLISH)) : defRole;

                // Remove the server if it is not a master.
                if (role != ROLES.MASTER) {
                    it.remove();
                }
            }
        }

        // Return the list of master servers.
        return masters;
    }

    // Return an empty list if the server list is null.
    return Collections.EMPTY_LIST;
}

