/**
 * Compresses a given JSON string using GZIP compression.
 *
 * @param jsonStr The JSON string to be compressed.
 * @return The compressed byte array of the JSON string, or null if an error occurs.
 */
public byte[] compress(String jsonStr) {
    if (jsonStr == null || jsonStr.length() == 0) {
        return null;
    }

    GZIPOutputStream gout = null;
    ByteArrayOutputStream baos = null;

    try {
        byte[] incoming = jsonStr.getBytes("UTF-8");
        baos = new ByteArrayOutputStream();
        gout = new GZIPOutputStream(baos, 16384); // 16KB
        gout.write(incoming);
        gout.finish();
        return baos.toByteArray();
    } catch (Exception ex) {
        OLogManager.instance().error(this, "Error on compressing HTTP response", ex);
    } finally {
        try {
            if (gout != null) {
                gout.close();
            }
            if (baos != null) {
                baos.close();
            }
        } catch (Exception ex) {
        }
    }

    return null;
}

