/**
 * Retrieves a value from a map using a key, which can be a string with optional sub-key.
 * If the key is a string, it can contain a sub-key separated by a space. The method first
 * extracts the main key and, if a sub-key is present, recursively retrieves the value from
 * the nested map or document.
 *
 * @param iMap The map from which to retrieve the value.
 * @param iKey The key or sub-key to retrieve the value for.
 * @return The value associated with the key or sub-key, or null if the key is not found.
 */
@SuppressWarnings("unchecked")
public static Object getMapEntry(final Map<String, ?> iMap, final Object iKey) {
    if (iMap == null || iKey == null) return null;
    if (iKey instanceof String) {
        String iName = (String) iKey;
        int pos = iName.indexOf(' ');
        if (pos > -1) iName = iName.substring(0, pos);
        final Object value = iMap.get(iName);
        if (value == null) return null;
        if (pos > -1) {
            final String restFieldName = iName.substring(pos + 1);
            if (value instanceof ODocument) return getFieldValue(value, restFieldName);
            else if (value instanceof Map<?, ?>) return getMapEntry((Map<String, ?>) value, restFieldName);
        }
        return value;
    } else return iMap.get(iKey);
}

