    graph.setCurrentGraphInThreadLocal();
    graph.autoStartTransaction();
    ODocument doc = getRecord();
    if (doc == null) throw ExceptionFactory.vertexWithIdDoesNotExist(this.getId());

    Map<String, List<ODocument>> treeRidbagEdgesToRemove = new HashMap<>();

    if (!graph.getRawGraph().getTransaction().isActive()) {
        for (String fieldName : doc.fieldNames()) {
            OPair<Direction, String> connection = getConnection(Direction.BOTH, fieldName);
            if (connection == null) continue;
            Object fv = doc.field(fieldName);
