/**
 * Retrieves a map of console methods.
 * 
 * @return A map of methods annotated with {@link ConsoleCommand} and their corresponding candidates.
 */
protected Map<Method, Object> getConsoleMethods() {
    if (methods != null) return methods;

    Iterator<OConsoleCommandCollection> ite = ServiceLoader.load(OConsoleCommandCollection.class).iterator();
    Collection<Object> candidates = new ArrayList<>();
    candidates.add(this);

    while (ite.hasNext()) {
        try {
            OConsoleCommandCollection cc = ite.next().getClass().newInstance();
            cc.setContext(this);
            candidates.add(cc);
        } catch (InstantiationException | IllegalAccessException ex) {
            Logger.getLogger(OConsoleApplication.class.getName()).log(Level.WARNING, ex.getMessage());
        }
    }

    methods = new TreeMap<>(new Comparator<Method>() {
        public int compare(Method o1, Method o2) {
            ConsoleCommand ann1 = o1.getAnnotation(ConsoleCommand.class);
            ConsoleCommand ann2 = o2.getAnnotation(ConsoleCommand.class);
            if (ann1 != null && ann2 != null) {
                if (ann1.priority() != ann2.priority()) // PRIORITY WINS
                    return ann1.priority() - ann2.priority();
            }
            int res = o1.getName().compareTo(o2.getName());
            if (res == 0) res = o1.toString().compareTo(o2.toString());
            return res;
        }
    });

    for (Object candidate : candidates) {
        Method[] classMethods = candidate.getClass().getMethods();
        for (Method m : classMethods) {
            if (Modifier.isAbstract(m.getModifiers()) || Modifier.isStatic(m.getModifiers()) || !Modifier.isPublic(m.getModifiers())) {
                continue;
            }
            if (m.getReturnType() != Void.TYPE) {
                continue;
            }
            methods.put(m, candidate);
        }
    }

    return methods;
}

