/**
 * Acquires an entry for the given key, handling various states and logging accordingly.
 * 
 * @param key The key for which to acquire the entry.
 * @return The acquired entry, or null if the entry is retired, dead, or closed.
 * @throws InterruptedException If the thread is interrupted while waiting.
 */
public OClosableEntry<K, V> acquire(K key) throws InterruptedException {
    checkOpenFilesLimit();
    OClosableEntry<K, V> entry = data.get(key);
    if (entry == null) return null;

    boolean logOpen = false;
    entry.acquireStateLock();
    try {
        if (entry.isRetired() || entry.isDead()) {
            return null;
        } else if (entry.isClosed()) {
            entry.makeAcquiredFromClosed(entry.get());
            logOpen = true;
        } else if (entry.isOpen()) {
            entry.makeAcquiredFromOpen();
        } else {
            entry.incrementAcquired();
        }
    } finally {
        entry.releaseStateLock();
    }

    if (logOpen) {
        logOpen(entry);
    } else {
        logAcquire(entry);
    }

    assert entry.get().isOpen();
    return entry;
}

