@Override
public long skip(final long n) throws IOException {
    if (n <= avail) {
        int m = (int) n;
        pos += m;
        avail -= m;
        readBytes += n;
        return n;
    }
    long toSkip = n - avail, result = 0;
    avail = 0;
    while (toSkip != 0 && (result = is == System.in ? skipByReading(toSkip) : is.skip(toSkip)) < toSkip) {
        if (result == 0) {
            if (is.read() == -1) break;
            toSkip--;
        } else {
            toSkip -= result;
        }
    }
    long t = n - (toSkip - result);
    readBytes += t;
    return t;
}


