    String lastRefType = this.fieldPath.getLastRefTypeInPath();

    // Calculate the total number of words needed to estimate the size of the array bits.
    totalWords = readStateEngine.getTypeState(lastRefType).getPopulatedOrdinals().cardinality();

    // Initialize variables for calculating the average word length.
    averageWordLen = 0;
    double avg = 0;

