public static void writeVInt(OutputStream out, int value) throws IOException {
    // Write the most significant byte if value is greater than 0x0FFFFFFF or less than 0
    if (value > 0x0FFFFFFF || value < 0) {
        out.write((byte) (0x80 | ((value >>> 28))));
    }
    // Write the second most significant byte if value is greater than 0x1FFFFF or less than 0
    if (value > 0x1FFFFF || value < 0) {
        out.write((byte) (0x80 | ((value >>> 21) & 0x7F)));
    }
    // Write the third most significant byte if value is greater than 0x3FFF or less than 0
    if (value > 0x3FFF || value < 0) {
        out.write((byte) (0x80 | ((value >>> 14) & 0x7F)));
    }
    // Write the fourth most significant byte if value is greater than 0x7F or less than 0
    if (value > 0x7F || value < 0) {
        out.write((byte) (0x80 | ((value >>> 7) & 0x7F)));
    }
    // Write the least significant byte
    out.write((byte) (value & 0x7F));
}

