/**
 * Adds missing service parts to the given service based on the default service.
 * If the service has no spec, it takes over the complete spec from the default service.
 * If the service has no ports, it takes over the ports from the default service.
 * It also completes any missing parts by adding default ports if necessary.
 *
 * @param service       the service to be updated
 * @param defaultService the default service to use for missing parts
 */
private void addMissingServiceParts(ServiceBuilder service, Service defaultService) {
    // If service has no spec -> take over the complete spec from default service
    if (!service.hasSpec()) {
        service.withNewSpecLike(defaultService.getSpec()).endSpec();
        return;
    }

    // If service has no ports -> take over ports from default service
    List<ServicePort> ports = service.buildSpec().getPorts();
    if (ports == null || ports.isEmpty()) {
        service.editSpec().withPorts(defaultService.getSpec().getPorts()).endSpec();
        return;
    }

    // Complete missing parts: add default ports if necessary
    service.editSpec().withPorts(addMissingDefaultPorts(ports, defaultService)).endSpec();
}

