/**
 * Checks if a pod is ready.
 * 
 * @param pod The pod to check.
 * @return true if the pod is ready, false otherwise.
 */
public static boolean isPodReady(Pod pod) {
    // Check if the pod is running
    if (!isPodRunning(pod)) {
        return false;
    }

    // Get the pod status
    PodStatus podStatus = pod.getStatus();
    if (podStatus == null) {
        return true;
    }

    // Get the list of conditions
    List<PodCondition> conditions = podStatus.getConditions();
    if (conditions == null || conditions.isEmpty()) {
        return true;
    }

    // Check for the "ready" condition
    for (PodCondition condition : conditions) {
        if ("ready".equalsIgnoreCase(condition.getType())) {
            return Boolean.parseBoolean(condition.getStatus());
        }
    }

    return true;
}

