/**
 * Applies a project request to an OpenShift cluster.
 * 
 * @param entity The project request entity to apply.
 * @return true if the project request was successfully created, false otherwise.
 */
public boolean applyProjectRequest(ProjectRequest entity) {
    // Get or create metadata for the project request and log the namespace.
    String namespace = getOrCreateMetadata(entity).getName();
    log.info("Using project: " + namespace);

    // Get the name of the project request and ensure it is not null.
    String name = getName(entity);
    Objects.requireNonNull(name, "No name for " + entity);

    // Get the OpenShift client and log a warning if it is not available.
    OpenShiftClient openshiftClient = getOpenShiftClient();
    if (openshiftClient == null) {
        log.warn("Cannot check for Project " + namespace + " as not running against OpenShift!");
        return false;
    }

    // Check if the project request already exists.
    boolean exists = checkNamespace(name);

    // If the project request does not exist, attempt to create it.
    if (!exists) {
        try {
            Object answer = openshiftClient.projectrequests().create(entity);
            logGeneratedEntity("Created ProjectRequest: ", namespace, entity, answer);
            return true;
        } catch (Exception e) {
            onApplyError("Failed to create ProjectRequest: " + name + " due " + e.getMessage(), e);
        }
    }

    return false;
}

