static int[] rewindReverse64(int hi, int lo, int len) {
    int[] result = new int[2];
    if (len <= 32) {
        result[0] = 0;
        result[1] = rewindReverse32(lo, len);
    } else {
        // Perform bit manipulation on hi and lo
        for (int i = 0; i < 5; i++) {
            hi = ((hi >> S[i]) & B[i]) | ((hi << S[i]) & ~B[i]);
            lo = ((lo >> S[i]) & B[i]) | ((lo << S[i]) & ~B[i]);
        }
        // Shift off low bits
        result[1] = (hi >> (64 - len)) | (lo << (len - 32));
        result[1] = lo >> (64 - len);
    }
    return result;
}

