/**
 * Displays a video frame at the correct time.
 *
 * @param streamStartTime The start time of the stream.
 * @param picture The media picture to display.
 * @param converter The media picture converter.
 * @param image The image to be converted.
 * @param window The image frame window.
 * @param systemStartTime The start time of the system.
 * @param systemTimeBase The time base of the system.
 * @param streamTimebase The time base of the stream.
 * @return The converted image.
 * @throws InterruptedException If the thread is interrupted.
 */
private static BufferedImage displayVideoAtCorrectTime(long streamStartTime, final MediaPicture picture, final MediaPictureConverter converter, BufferedImage image, final ImageFrame window, long systemStartTime, final Rational systemTimeBase, final Rational streamTimebase) throws InterruptedException {
    long streamTimestamp = picture.getTimeStamp(); // Convert stream timestamp to system units (nano-seconds)
    streamTimestamp = systemTimeBase.rescale(streamTimestamp - streamStartTime, streamTimebase); // Get the current clock time with the most accurate clock
    long systemTimestamp = System.nanoTime(); // Loop in a sleeping loop until we're within 1 ms of the time for that video frame
    while (streamTimestamp > (systemTimestamp - systemStartTime + 1000000)) {
        Thread.sleep(1);
        systemTimestamp = System.nanoTime();
    }
    // Convert the image from Humble format into Java images
    image = converter.toImage(image, picture);
    // Ask the UI thread to repaint with the new image
    window.setImage(image);
    return image;
}

