/**
 * Retrieves the FSTClazzInfo for a given class, using a reference field info.
 * If the reference field info already has a matching FSTClazzInfo, it returns that.
 * Otherwise, it fetches the FSTClazzInfo from the registry and updates the reference field info.
 *
 * @param referencee The reference field info.
 * @param clazz The class for which to retrieve the FSTClazzInfo.
 * @return The FSTClazzInfo for the given class.
 */
protected FSTClazzInfo getFstClazzInfo(FSTClazzInfo.FSTFieldInfo referencee, Class clazz) {
    FSTClazzInfo serializationInfo = null;
    FSTClazzInfo lastInfo = referencee.lastInfo;
    if (lastInfo != null && lastInfo.getClazz() == clazz && lastInfo.conf == conf) {
        serializationInfo = lastInfo;
    } else {
        serializationInfo = getClassInfoRegistry().getCLInfo(clazz, conf);
        referencee.lastInfo = serializationInfo;
    }
    return serializationInfo;
}

