/**
 * Checks if the given DataBuffer represents a vector.
 * 
 * @param shapeInfo The DataBuffer containing shape information.
 * @return true if the shapeInfo represents a vector, false otherwise.
 */
public static boolean isVector(DataBuffer shapeInfo) {
    int rank = Shape.rank(shapeInfo);
    if (rank > 2 || rank < 1) {
        return false;
    } else {
        int len = Shape.length(shapeInfo);
        DataBuffer shape = Shape.shapeOf(shapeInfo);
        return shape.getInt(0) == len || shape.getInt(1) == len;
    }
}

