            BigDecimal resul = BigDecimal.ONE;
            BigDecimal xpowi = BigDecimal.ONE;
            BigInteger ifac = BigInteger.ONE;
            double xUlpDbl = 0.5 * x.ulp().doubleValue() * x.doubleValue();
