                xpowi = xpowi.multiply(xhighpr).multiply(xhighpr);
                BigDecimal corr = xpowi.divide(new BigDecimal(ifac), mcTay);
                resul = resul.add(corr);
                if (corr.abs().doubleValue() < 0.5 * xUlpDbl) {
                    break;
                }
