public String format(INDArray arr, boolean summarize) {
    // Initialize scientific format and precision
    this.scientificFormat = "0.";
    int addPrecision = this.precision;
    while (addPrecision > 0) {
        this.scientificFormat += "#";
        addPrecision -= 1;
    }
    this.scientificFormat += "E0";

    // Adjust padding if necessary
    if (this.scientificFormat.length() + 2 > this.padding) {
        this.padding = this.scientificFormat.length() + 2;
    }

    // Set thresholds for switching to scientific notation
    this.maxToPrintWithoutSwitching = Math.pow(10, this.precision);
    this.minToPrintWithoutSwitching = 1.0 / (this.maxToPrintWithoutSwitching);

    // If summarize is true and array length is greater than 1000, recursively call format with summarize set to false
    if (summarize && arr.length() > 1000) {
        return format(arr, 0, true);
    }

    // Otherwise, recursively call format with summarize set to false
    return format(arr, 0, false);
}

