/**
 * Fetches pending entities from the datastore.
 * 
 * @return A Result containing a map of keys to entities. If there are no entities to fetch, the map is returned immediately.
 *         Otherwise, the map is updated with the fetched entities and returned.
 */
private Result<Map<com.google.cloud.datastore.Key, Entity>> fetchPending() {
    Map<com.google.cloud.datastore.Key, Entity> combined = new HashMap<>();
    Set<com.google.cloud.datastore.Key> fetch = new HashSet<>();

    for (com.google.cloud.datastore.Key key : pending) {
        Entity ent = stuffed.get(key);
        if (ent == null) {
            fetch.add(key);
        } else {
            combined.put(key, ent);
        }
    }

    if (fetch.isEmpty()) {
        return new ResultNow<>(combined);
    } else {
        final Result<Map<com.google.cloud.datastore.Key, Entity>> fetched = loadEngine.fetch(fetch);
        return () -> {
            combined.putAll(fetched.now());
            return combined;
        };
    }
}

