/**
 * Executes a single transaction using the provided ObjectifyImpl parent and Work task.
 * 
 * @param <R> The type of result returned by the Work task.
 * @param parent The parent ObjectifyImpl instance.
 * @param work The Work task to be executed within the transaction.
 * @return The result of the Work task.
 * @throws RuntimeException If the transaction fails to commit or rollback.
 */
private <R> R transactOnce(final ObjectifyImpl parent, final Work<R> work) {
    // Open a new transaction using the parent's options and a custom TransactorYes.
    final ObjectifyImpl txnOfy = factory.open(parent.getOptions(), next -> new TransactorYes(next, this));
    boolean committedSuccessfully = false;
    try {
        // Execute the Work task and flush the transaction.
        final R result = work.run();
        txnOfy.flush();
        // Commit the transaction.
        txnOfy.getTransaction().commit();
        committedSuccessfully = true;
        return result;
    } finally {
        // If the transaction is still active, attempt to rollback.
        if (txnOfy.getTransaction().isActive()) {
            try {
                txnOfy.getTransaction().rollback();
            } catch (RuntimeException ex) {
                log.error("Rollback failed, suppressing error", ex);
            }
        }
        // Close the transaction.
        txnOfy.close();
        // If the transaction was committed successfully, run any commit listeners.
        if (committedSuccessfully) {
            ((PrivateAsyncTransaction) txnOfy.getTransaction()).runCommitListeners();
        }
    }
}

