/**
 * Converts a given singular noun to its plural form.
 * 
 * @param name The singular noun to be converted.
 * @return The plural form of the given noun.
 */
protected String makePlural(final String name) {
    String plural;
    int length = name.length();
    char lastChar = name.charAt(length - 1);

    if (lastChar != ' ') {
        plural = name + (name.endsWith("ch") ? "es" : "s");
    } else {
        if (length == 1) {
            plural = name + "s";
        } else {
            char penultimateChar = name.charAt(length - 2);
            plural = (penultimateChar == ' ' || penultimateChar == ' ' || penultimateChar == ' ' || penultimateChar == ' ' || penultimateChar == ' ') ? name + "s" : name.substring(0, length - 1) + "ies";
        }
    }

    return plural;
}

