/**
 * Splits the levels from a NetCDF variable into a list of dimensions.
 *
 * @param ds       the NetCDF dataset
 * @param levelVar the variable containing the level data
 * @return a list of dimensions representing the levels
 * @throws IOException if an I/O error occurs
 */
private List<Dimension> breakupLevels(NetcdfDataset ds, Variable levelVar) throws IOException {
    if (debugBreakup) {
        parseInfo.format("breakupLevels = %s%n", levelVar.getShortName());
    }
    List<Dimension> dimList = new ArrayList<>();
    ArrayChar levelVarData;
    try {
        levelVarData = (ArrayChar) levelVar.read();
    } catch (IOException ioe) {
        return dimList;
    }
    List<String> values = null;
    String currentUnits = null;
    ArrayChar.StringIterator iter = levelVarData.getStringIterator();
    while (iter.hasNext()) {
        String s = iter.next();
        if (debugBreakup) {
            parseInfo.format("   %s%n", s);
        }
        StringTokenizer stoke = new StringTokenizer(s);
        if (!stoke.hasMoreTokens()) {
            continue; // skip it
        }
        // first token is the unit
        String units = stoke.nextToken().trim();
        if (!units.equals(currentUnits)) {
            if (values != null) {
                dimList.add(makeZCoordAxis(ds, values, currentUnits));
            }
            values = new ArrayList<>();
            currentUnits = units;
        }
        // next token is the value
        if (stoke.hasMoreTokens()) {
            values.add(stoke.nextToken());
        } else {
            values.add("0");
        }
    }
    if (values != null) {
        dimList.add(makeZCoordAxis(ds, values, currentUnits));
    }
    if (debugBreakup) {
        parseInfo.format("  done breakup%n");
    }
    return dimList;
}

