public static boolean isMine(NetcdfFile ncfile) {
    // Check if the file has a Conventions attribute and if it is not null
    String cs = ncfile.findAttValueIgnoreCase(null, CDM.CONVENTIONS, null);
    if (cs != null) return false;

    // Check if the DataType attribute is present and has the value "LatLonGrid" or "LatLonHeightGrid"
    String s = ncfile.findAttValueIgnoreCase(null, "DataType", null);
    if ((s == null) || !(s.equalsIgnoreCase("LatLonGrid") || s.equalsIgnoreCase("LatLonHeightGrid"))) return false;

    // Check if the required global attributes are present
    if ((null == ncfile.findGlobalAttribute("Latitude")) ||
        (null == ncfile.findGlobalAttribute("Longitude")) ||
        (null == ncfile.findGlobalAttribute("LatGridSpacing")) ||
        (null == ncfile.findGlobalAttribute("LonGridSpacing")) ||
        (null == ncfile.findGlobalAttribute("Time"))) return false;

    // Check if the required dimensions are present
    return !(null == ncfile.findDimension("Lat") || null == ncfile.findDimension("Lon"));
}

