/**
 * Reads data from a variable within a section.
 * 
 * @param cdmvar The variable from which to read data.
 * @param section The section defining the subset of data to read.
 * @return An array containing the data from the specified section.
 * @throws IOException If no data is available for the variable.
 * @throws InvalidRangeException If the section rank does not match the variable rank.
 */
protected Array readData(Variable cdmvar, Section section) throws IOException, InvalidRangeException {
    assert this.dsp != null;
    Array result = arraymap.get(cdmvar);
    if (result == null) {
        throw new IOException("No data for variable: " + cdmvar.getFullName());
    }
    if (section != null) {
        if (cdmvar.getRank() != section.getRank()) {
            throw new InvalidRangeException(String.format("Section rank != %s rank", cdmvar.getFullName()));
        }
        List<Range> ranges = section.getRanges();
        if (CDMUtil.hasVLEN(ranges)) {
            ranges = ranges.subList(0, ranges.size() - 1); // May produce an empty list
        }
        if (ranges.size() > 0 && !CDMUtil.isWhole(ranges, cdmvar)) {
            result = result.sectionNoReduce(ranges);
        }
    }
    return result;
}

