/**
 * Returns a typical dataset from a list of nested datasets based on the specified mode.
 * 
 * @return The typical dataset.
 * @throws IOException If no datasets are available.
 */
protected Dataset getTypicalDataset() throws IOException {
    List<Dataset> nestedDatasets = getDatasets();
    int n = nestedDatasets.size();
    if (n == 0) throw new FileNotFoundException("No datasets in this aggregation");

    int select;
    if (typicalDatasetMode == TypicalDataset.LATEST) {
        select = n - 1;
    } else if (typicalDatasetMode == TypicalDataset.PENULTIMATE) {
        select = (n < 2) ? 0 : n - 2;
    } else if (typicalDatasetMode == TypicalDataset.FIRST) {
        select = 0;
    } else {
        // Random is the default mode
        if (r == null) r = new Random();
        select = (n < 2) ? 0 : r.nextInt(n);
    }

    return nestedDatasets.get(select);
}

