/**
 * Checks if the given dataset matches the filter criteria.
 * 
 * @param dataset The dataset to check.
 * @return true if the dataset matches the filter, false otherwise.
 */
private boolean match(InvDataset dataset) {
    // Check if the dataset is a collection and if the filter should not apply to collections
    if (this.getParentDatasetSource().isCollection(dataset) && !this.applyToCollectionDatasets) {
        return false;
    }
    // Check if the dataset is not a collection and if the filter should not apply to atomic datasets
    if (!this.getParentDatasetSource().isCollection(dataset) && !this.applyToAtomicDatasets) {
        return false;
    }
    // Set the default match pattern target if not already set
    if (this.matchPatternTarget == null) {
        if (this.getParentDatasetSource().isCollection(dataset)) {
            this.setMatchPatternTarget("name");
        } else {
            this.setMatchPatternTarget("urlPath");
        }
    }
    // Check if the filter type is regular expression
    if (this.type == DatasetFilter.Type.REGULAR_EXPRESSION) {
        boolean isMatch;
        // Match the dataset name or URL path based on the match pattern target
        if (this.getMatchPatternTarget().equals("name")) {
            java.util.regex.Matcher matcher = this.regExpPattern.matcher(dataset.getName());
            isMatch = matcher.find();
        } else if (this.getMatchPatternTarget().equals("urlPath")) {
            java.util.regex.Matcher matcher = this.regExpPattern.matcher(((InvDatasetImpl) dataset).getUrlPath());
            isMatch = matcher.find();
        } else {
            // Handle any other match pattern target (XPath-ish)
            isMatch = false;
        }
        // Invert the meaning of a match if the filter is set to reject matching datasets
        if (this.isRejectMatchingDatasets()) {
            return !isMatch;
        } else {
            return isMatch;
        }
    } else {
        // Handle unsupported filter types
        System.err.println("WARNING -- DatasetFilter.match(): unsupported type " + this.type.toString() + ".");
        return false;
    }
}

