/**
 * Loads data from a stream into an array of data objects.
 * 
 * @return 0 if data is successfully loaded, -1 if an error occurs.
 */
private int loadData() {
    if (!headerLoaded) return -1;
    if (dataLoaded) return 0;
    InputStream s = stream;
    if (s == null) return -1;
    try {
        for (int i = 0; i < nrecords; i++) {
            byte recbyte = ds.readByte();
            if (recbyte == 0x20) {
                for (int j = 0; j < nfields; j++) {
                    data[j].readRowN(ds, i);
                }
            } else {
                nrecords--;
                i--;
            }
        }
        dataLoaded = true;
    } catch (java.io.IOException e) {
        close(s);
        return -1;
    } finally {
        close(s);
    }
    return 0;
}

