    if (attr.getParent().getSort() == DapSort.DATASET) {
        for (String s : GROUPSPECIAL) {
            if (s.equals(attr.getShortName())) return true;
        }
    } else if (attr.getParent().getSort() == DapSort.VARIABLE) {
        for (String s : VARSPECIAL) {
            if (s.equals(attr.getShortName())) return true;
        }
    }
    return false;
}

