/**
 * Sends data for a variable in a specific section to an output stream using a compression algorithm.
 * 
 * @param v The variable to send data for.
 * @param section The section of the variable to send data for.
 * @param out The output stream to send the data to.
 * @param compress The compression algorithm to use.
 * @return The total number of bytes sent.
 * @throws IOException If an I/O error occurs.
 * @throws InvalidRangeException If the section is invalid.
 */
public long sendData2(Variable v, Section section, OutputStream out, NcStreamCompression compress) throws IOException, InvalidRangeException {
    if (show) System.out.printf(" %s section=%s%n", v.getFullName(), section);
    boolean isVlen = v.isVariableLength();
    if (isVlen) v.read(section);
    NcStreamDataCol encoder = new NcStreamDataCol();
    NcStreamProto.DataCol dataProto = encoder.encodeData2(v.getFullName(), isVlen, section, v.read(section));
    byte[] datab = dataProto.toByteArray();
    long size = 0;
    size += writeBytes(out, NcStream.MAGIC_DATA2);
    size += NcStream.writeVInt(out, datab.length);
    size += writeBytes(out, datab);
    return size;
}

