/**
 * Determines the axis type based on the units of a variable in a NetCDF dataset.
 *
 * @param ncDataset The NetCDF dataset containing the variable.
 * @param v The variable whose units are to be checked.
 * @return The axis type corresponding to the variable's units, or null if no match is found.
 */
protected AxisType getAxisType(NetcdfDataset ncDataset, VariableEnhanced v) {
    String unit = v.getUnitsString();
    if (unit == null) return null;
    unit = unit.trim();

    // Check for longitude units
    if (unit.equalsIgnoreCase("degrees_east") || unit.equalsIgnoreCase("degrees_E") || unit.equalsIgnoreCase("degreesE") ||
        unit.equalsIgnoreCase("degree_east") || unit.equalsIgnoreCase("degree_E") || unit.equalsIgnoreCase("degreeE")) {
        return AxisType.Lon;
    }

    // Check for latitude units
    if (unit.equalsIgnoreCase("degrees_north") || unit.equalsIgnoreCase("degrees_N") || unit.equalsIgnoreCase("degreesN") ||
        unit.equalsIgnoreCase("degree_north") || unit.equalsIgnoreCase("degree_N") || unit.equalsIgnoreCase("degreeN")) {
        return AxisType.Lat;
    }

    // Check for time units
    if (SimpleUnit.isDateUnit(unit)) {
        return AxisType.Time;
    }

    // Check for pressure units
    if (SimpleUnit.isCompatible("mbar", unit)) {
        return AxisType.Pressure;
    }

    // Check for vertical coordinate units
    if (unit.equalsIgnoreCase("level") || unit.equalsIgnoreCase("layer") || unit.equalsIgnoreCase("sigma_level")) {
        return AxisType.GeoZ;
    }

    // Check for height units
    String positive = ncDataset.findAttValueIgnoreCase((Variable) v, CF.POSITIVE, null);
    if (positive != null) {
        if (SimpleUnit.isCompatible("m", unit)) {
            return AxisType.Height;
        } else {
            return AxisType.GeoZ;
        }
    }

    // Fallback for CDC SST
    // if (checkForMeter && SimpleUnit.isCompatible("m", unit)) {
    //     return AxisType.Height;
    // }

    return null;
}

