/**
 * Determines if a scan is needed for a collection.
 * 
 * @return true if a scan is needed, false otherwise.
 */
@Override
public boolean isScanNeeded() {
    // Check if recheck is null
    if (recheck == null) {
        logger.debug("{}: scan not needed, recheck null", collectionName);
        return false;
    }

    // Check if there are no scanners
    if (!hasScans()) {
        logger.debug("{}: scan not needed, no scanners", collectionName);
        return false;
    }

    // Check if the map is null and the collection is not static
    synchronized (this) {
        if (map == null && !isStatic()) {
            logger.debug("{}: scan needed, never scanned", collectionName);
            return true;
        }
    }

    // Get the current date and the last scanned date
    Date now = new Date();
    Date lastCheckedDate = new Date(getLastScanned());
    Date need = recheck.add(lastCheckedDate);

    // Check if the current date is before the next scan date
    if (now.before(need)) {
        logger.debug("{}: scan not needed, last scanned={}, now={}", collectionName, lastCheckedDate, now);
        return false;
    }

    // Return true if a scan is needed
    return true;
}

