/**
 * Multiplies two dimensions and returns the resulting factors.
 * 
 * @param that The dimension to multiply with.
 * @return The resulting factors after multiplication.
 */
protected Factor[] mult(final Dimension that) {
    Factor[] factors1 = _factors;
    Factor[] factors2 = that._factors;
    int i1 = 0, i2 = 0, k = 0;
    Factor[] newFactors = new Factor[factors1.length + factors2.length];

    while (true) {
        if (i1 == factors1.length) {
            System.arraycopy(factors2, i2, newFactors, k, factors2.length - i2);
            break;
        }
        if (i2 == factors2.length) {
            System.arraycopy(factors1, i1, newFactors, k, factors1.length - i1);
            break;
        }

        Factor f1 = factors1[i1];
        Factor f2 = factors2[i2];
        int comp = f1.getID().compareTo(f2.getID());

        if (comp < 0) {
            newFactors[k++] = f1;
            i1++;
        } else if (comp == 0) {
            int exponent = f1.getExponent() + f2.getExponent();
            if (exponent != 0) {
                newFactors[k++] = new Factor(f1, exponent);
            }
            i1++;
            i2++;
        } else {
            newFactors[k++] = f2;
            i2++;
        }
    }

    if (k < newFactors.length) {
        Factor[] tmp = new Factor[k];
        System.arraycopy(newFactors, 0, tmp, 0, k);
        newFactors = tmp;
    }

    return newFactors;
}

