    } else if (v.getDataType() == DataType.CHAR) {
        if (v.getRank() > 1) {
            bt = new NcSDCharArray(v);
        } else {
            bt = new NcSDString(v);
        }
    } else if (v.getDataType() == DataType.STRING) {
        if (v.getRank() == 0) {
            bt = new NcSDString(v);
        } else {
            bt = new NcSDArray(v, new NcSDString(v));
        }
