/**
 * Checks if a given latitude and longitude are within a 3x3 grid cell around a specified cell.
 * 
 * @param wantLat The latitude to check.
 * @param wantLon The longitude to check.
 * @param rectIndex The index of the center cell in the grid.
 * @return true if the latitude and longitude are within the 3x3 grid cell, false otherwise.
 */
private boolean box9(double wantLat, double wantLon, int[] rectIndex) {
    int row = rectIndex[0];
    int minrow = Math.max(row - 1, 0);
    int maxrow = Math.min(row + 1, nrows);
    int col = rectIndex[1];
    int mincol = Math.max(col - 1, 0);
    int maxcol = Math.min(col + 1, ncols);

    if (debug) {
        System.out.printf("%n   box9:");
    }

    for (int i = minrow; i <= maxrow; i++) {
        for (int j = mincol; j <= maxcol; j++) {
            rectIndex[0] = i;
            rectIndex[1] = j;
            if (contains(wantLat, wantLon, rectIndex)) {
                return true;
            }
        }
    }

    return false;
}

