    if (mode == RequestMode.DMR || mode == RequestMode.DSR) {
        state = State.END; // Set state to END if mode is DMR or DSR
    } else {
        // Mode is DATA
        int flags = DapUtil.CHUNK_DATA; // Set flags to CHUNK_DATA
        if (this.writeorder == ByteOrder.LITTLE_ENDIAN) {
            flags |= DapUtil.CHUNK_LITTLE_ENDIAN; // Add CHUNK_LITTLE_ENDIAN if writeorder is LITTLE_ENDIAN
        }
        chunkheader(dxr8.length, flags, this.header); // Write chunk header
        output.write(DapUtil.extract(this.header)); // Write the header
        state = State.DATA; // Set state to DATA
    }

    output.write(dxr8); // Write the DXR data
    output.flush(); // Flush the output
}

