/**
 * Reads data from a file into a writable byte channel based on the specified data type and layout.
 *
 * @param index The layout index to read from.
 * @param dataType The data type of the elements to read.
 * @param out The writable byte channel to write the data to.
 * @return The total number of bytes read.
 * @throws IOException If an I/O error occurs.
 */
protected long readData(Layout index, DataType dataType, WritableByteChannel out) throws IOException {
    long count = 0;
    while (index.hasNext()) {
        Layout.Chunk chunk = index.next();
        int elementSize = getPrimitiveSize(dataType);
        count += raf.readToByteChannel(out, chunk.getSrcPos(), elementSize * chunk.getNelems());
    }
    return count;
}

private int getPrimitiveSize(DataType dataType) {
    if (dataType.getPrimitiveClassType() == byte.class || dataType == DataType.CHAR) {
        return 1;
    } else if (dataType.getPrimitiveClassType() == short.class) {
        return 2;
    } else if (dataType.getPrimitiveClassType() == int.class || dataType == DataType.FLOAT) {
        return 4;
    } else if (dataType == DataType.DOUBLE || dataType.getPrimitiveClassType() == long.class) {
        return 8;
    }
    throw new IllegalArgumentException("Unsupported data type: " + dataType);
}

