/**
 * Transfers inheritable metadata from one dataset to another.
 *
 * @param fromDs The source dataset from which metadata is transferred.
 * @param target The target dataset to which metadata is transferred.
 * @param copyInheritedMetadataFromParents Whether to copy inherited metadata from parent datasets.
 */
private void transferInheritableMetadata(InvDatasetImpl fromDs, ThreddsMetadata target, boolean copyInheritedMetadataFromParents) {
    if (fromDs == null) return;
    logger.debug("transferInheritedMetadata= " + fromDs.getName());
    target.add(fromDs.getLocalMetadataInheritable(), true);

    // Iterate through local metadata to find inherited InvMetadata elements
    ThreddsMetadata tmd = fromDs.getLocalMetadata();
    Iterator iter = tmd.getMetadata().iterator();
    while (iter.hasNext()) {
        InvMetadata meta = (InvMetadata) iter.next();
        if (meta.isInherited()) {
            if (!meta.isThreddsMetadata()) {
                tmc.addMetadata(meta);
            } else {
                logger.debug("transferInheritedMetadata " + meta.hashCode() + " = " + meta);
                meta.finish(); // Ensure XLink is read in.
                tmc.add(meta.getThreddsMetadata(), true);
            }
        }
    }

    // Recursively copy inherited metadata from parent datasets
    if (copyInheritedMetadataFromParents) {
        transferInheritableMetadata((InvDatasetImpl) fromDs.getParent(), target, true);
    }
}

