    name = name.trim();

    // Check if the name contains any invalid characters
    boolean ok = true;
    for (int i = 0; i < name.length(); i++) {
        int c = name.charAt(i);
        if (c < 0x20 || c == ' ') {
            ok = false;
            break;
        }
    }

    // If the name is valid, return it as is
    if (ok) {
        return name;
    }

    // If the name contains invalid characters, replace them with spaces
    StringBuilder sbuff = new StringBuilder(name.length());
    for (int i = 0, len = name.length(); i < len; i++) {
        int c = name.charAt(i);
        if (c == ' ' || c == ' ') {
            sbuff.append(' ');
        } else if (c >= 0x20) {
            sbuff.append((char) c);
        }
    }

    return sbuff.toString();
}

