/**
 * Updates the state of the collection based on the given update type.
 * If called from a background thread or a checkState() request thread, it first checks the state and updates the last invocation change time.
 * Otherwise, it creates a local copy of the current state, performs the update, and then switches to the live state.
 * 
 * @param force The type of update to perform.
 * @throws IOException If an I/O error occurs during the update.
 */
protected void update(CollectionUpdateType force) throws IOException {
    State localState;
    synchronized (lock) {
        if (first) {
            state = checkState();
            state.lastInvChange = System.currentTimeMillis();
            return;
        }
        // Do the update in a local object
        localState = state.copy();
    }
    updateCollection(localState, force);
    localState.lastInvChange = System.currentTimeMillis();
    // Switch to live
    synchronized (lock) {
        state = localState;
    }
}

