/**
 * Determines if the directory represented by the given IndexReader is a leaf node.
 * A leaf node is defined as a directory that contains more files than directories.
 * If the partition status is unknown, it will be determined by checking the first 100 entries in the directory.
 * 
 * @param indexReader The IndexReader representing the directory to check.
 * @return true if the directory is a leaf node, false otherwise.
 * @throws IOException if an I/O error occurs.
 */
private boolean isLeaf(IndexReader indexReader) throws IOException {
    if (partitionStatus == PartitionStatus.unknown) {
        int countDir = 0, countFile = 0, count = 0;
        try (DirectoryStream<Path> dirStream = Files.newDirectoryStream(dir)) {
            Iterator<Path> iterator = dirStream.iterator();
            while (iterator.hasNext() && count++ < 100) {
                Path p = iterator.next();
                BasicFileAttributes attr = Files.readAttributes(p, BasicFileAttributes.class);
                if (attr.isDirectory()) countDir++;
                else countFile++;
            }
        }
        partitionStatus = (countFile > countDir) ? PartitionStatus.isLeaf : PartitionStatus.isDirectoryPartition;
    }
    return partitionStatus == PartitionStatus.isLeaf;
}

