@Override
public void eject(Object hashKey) {
    if (disabled.get()) return; // Check if the cache is disabled
    CacheElement wantCacheElem = cache.get(hashKey);
    if (wantCacheElem == null) return; // If the cache element is not found, return
    synchronized (wantCacheElem) { // Synchronize to ensure thread safety
        for (CacheElement.CacheFile want : wantCacheElem.list) { // Iterate through the list of cache files
            files.remove(want.ncfile); // Remove the cache file from the files list
            try {
                want.ncfile.setFileCache(null); // Unhook the caching
                want.ncfile.close(); // Close the file
                log.debug("close " + want.ncfile.getLocation()); // Log the closure
            } catch (IOException e) {
                log.error("close failed on " + want.ncfile.getLocation(), e); // Log any errors during closure
            }
            want.ncfile = null; // Set the cache file reference to null
            if (debugPrint) System.out.println("  FileCache " + name + " eject " + hashKey); // Debug print
        }
        wantCacheElem.list.clear(); // Clear the list of cache files
    }
    cache.remove(hashKey); // Remove the cache element from the cache
}

