/**
 * Releases a file from the cache.
 *
 * @param ncfile The file to be released.
 * @return true if the file was successfully released, false otherwise.
 * @throws IOException if an I/O error occurs.
 */
@Override
public boolean release(FileCacheable ncfile) throws IOException {
    if (ncfile == null) return false;
    if (disabled.get()) {
        ncfile.setFileCache(null); // Prevent infinite loops
        ncfile.close();
        return false;
    }
    CacheElement.CacheFile file = files.get(ncfile); // Using hashCode of the FileCacheable
    if (file != null) {
        if (!file.isLocked.get()) {
            cacheLog.warn("FileCache " + name + " release " + ncfile.getLocation() + " not locked; hash= " + ncfile.hashCode());
        }
        file.lastAccessed = System.currentTimeMillis();
        file.countAccessed++;
        file.isLocked.set(false);
        file.ncfile.release();
        if (cacheLog.isDebugEnabled()) {
            cacheLog.debug("FileCache " + name + " release " + ncfile.getLocation() + "; hash= " + ncfile.hashCode());
        }
        if (debugPrint) {
            System.out.printf("  FileCache %s release %s lock=%s count=%d%n", name, ncfile.getLocation(), file.isLocked.get(), countLocked());
        }
        return true;
    }
    return false;
}

