/**
 * Converts a unit string to a corresponding {@link CalendarPeriod.Field}.
 * 
 * @param udunit The unit string to convert.
 * @return The corresponding {@link CalendarPeriod.Field}.
 * @throws IllegalArgumentException if the unit string cannot be converted.
 */
public static CalendarPeriod.Field fromUnitString(String udunit) {
    udunit = udunit.trim().toLowerCase();
    if (udunit.equals("s")) return Field.Second;
    if (udunit.equals("ms")) return Field.Millisec;
    if (udunit.endsWith("s")) udunit = udunit.substring(0, udunit.length() - 1);
    switch (udunit) {
        case "second":
        case "sec":
            return Field.Second;
        case "millisecond":
        case "millisec":
        case "msec":
            return Field.Millisec;
        case "minute":
        case "min":
            return Field.Minute;
        case "hour":
        case "hr":
        case "h":
            return Field.Hour;
        case "day":
        case "d":
            return Field.Day;
        case "month":
        case "mon":
            return Field.Month;
        case "year":
        case "yr":
            return Field.Year;
        default:
            throw new IllegalArgumentException("Cannot convert " + udunit + " to CalendarPeriod");
    }
}

