/**
 * Reads a concept definition from an input stream and stores it.
 *
 * @param is          the input stream containing the concept definition
 * @param conceptName the name of the concept
 * @throws IOException if an I/O error occurs
 */
private void addLocalConcept(InputStream is, String conceptName) throws IOException {
    try (BufferedReader br = new BufferedReader(new InputStreamReader(is, ENCODING))) {
        String line = br.readLine();
        while (!line.startsWith("#")) {
            line = br.readLine(); // Skip lines until a line starting with '#' is found
        }
        while (true) {
            HashMap<String, String> items = new HashMap<>();
            line = br.readLine();
            if (line == null) {
                break; // End of file
            }
            if ((line.length() == 0) || line.startsWith("#")) {
                continue; // Skip empty lines or lines starting with '#'
            }
            line = cleanLine(line);
            if (line.contains("{")) {
                String paramName = line.split("=")[0].trim();
                line = br.readLine();
                if (line == null) {
                    break; // End of file
                }
                line = cleanLine(line);
                while (line.contains("=")) {
                    String[] kvp = line.split("=");
                    items.put(kvp[0].trim(), kvp[1].trim());
                    line = br.readLine();
                    if (line == null) {
                        break; // End of file
                    }
                    line = cleanLine(line);
                }
                String tableVersion = items.get(TABLE_VERSION_ID);
                String parameterNumber = items.get(PARAM_NUM_ID);
                storeConcept(tableVersion, parameterNumber, conceptName, paramName);
            }
        }
    }
}

