/**
 * Names datasets in the given dataset container based on the structure.
 * If the dataset namer list is empty, it returns immediately.
 * If the structure is FLAT, it calls `nameDatasetList` on the dataset container.
 * If the structure is DIRECTORY_TREE, it iterates through each dataset in the container and calls `nameDatasetTree` on each one.
 *
 * @param datasetContainer The dataset container to name datasets in.
 */
private void nameDatasets(InvDatasetImpl datasetContainer) {
    if (this.getDatasetNamerList().isEmpty()) return;
    if (this.isFlatten()) {
        logger.debug("nameDatasets(): structure is FLAT calling nameDatasetList()");
        this.nameDatasetList(datasetContainer);
    } else {
        logger.debug("nameDatasets(): structure is DIRECTORY_TREE calling nameDatasetTree() on each dataset in dataset container");
        InvDatasetImpl curDs = null;
        for (int j = 0; j < datasetContainer.getDatasets().size(); j++) {
            curDs = (InvDatasetImpl) datasetContainer.getDatasets().get(j);
            this.nameDatasetTree(curDs);
        }
    }
    return;
}

