/**
 * Retrieves the next frame from a GIF image.
 * 
 * @return The next frame as a Bitmap, or null if an error occurs.
 */
synchronized Bitmap getNextFrame() {
    if (header.frameCount <= 0 || framePointer < 0) {
        logError("unable to decode frame");
        status = STATUS_FORMAT_ERROR;
    }
    if (status == STATUS_FORMAT_ERROR || status == STATUS_OPEN_ERROR) {
        logError("Unable to decode frame, status=" + status);
        return null;
    }
    status = STATUS_OK;
    GifFrame currentFrame = header.frames.get(framePointer);
    GifFrame previousFrame = null;
    int previousIndex = framePointer - 1;
    if (previousIndex >= 0) {
        previousFrame = header.frames.get(previousIndex);
    }
    // Set the appropriate color table.
    ColorTable act = currentFrame.lct != null ? currentFrame.lct : header.gct;
    if (act == null) {
        logError("No Valid Color Table for frame #" + framePointer);
        status = STATUS_FORMAT_ERROR;
        return null;
    }
    // Reset the transparent pixel in the color table if specified.
    if (currentFrame.transparency) {
        ColorTable pct = new ColorTable(act);
        pct[currentFrame.transIndex] = 0;
        act = pct;
    }
    // Transfer pixel data to image.
    return setPixels(currentFrame, previousFrame);
}

