/**
 * Accesses a member with the given callable and error message.
 * 
 * @param <T> the type of the member to access
 * @param member the AccessibleObject to access
 * @param callable the Callable to execute
 * @param errorMessage the error message to use if an exception occurs
 * @return the result of the callable
 * @throws IllegalStateException if an exception occurs during the callable execution
 */
public static <T> T accessMember(final AccessibleObject member, final Callable<T> callable, String errorMessage) {
    if (callable == null) {
        return null;
    }
    return AccessController.doPrivileged((PrivilegedAction<T>) () -> {
        boolean wasAccessible = member.isAccessible();
        try {
            member.setAccessible(true);
            return callable.call();
        } catch (Exception exception) {
            throw new IllegalStateException(errorMessage, exception);
        } finally {
            member.setAccessible(wasAccessible);
        }
    });
}

