 * Retrieves the appropriate TileMatrix for a given CoverageDataRequest.
 * 
 * @param request The CoverageDataRequest object containing the request details.
 * @return The TileMatrix that matches the request, or null if no matching TileMatrix is found.
 */
private TileMatrix getTileMatrix(CoverageDataRequest request) {
    TileMatrix tileMatrix = null;

    // Check if the request overlaps the coverage data bounding box
    if (request.overlap(coverageBoundingBox) != null) {
        // Get the projected bounding box and calculate the width and height
        BoundingBox projectedBoundingBox = request.getProjectedBoundingBox();
        double distanceWidth = projectedBoundingBox.getMaxLongitude() - projectedBoundingBox.getMinLongitude();
        double distanceHeight = projectedBoundingBox.getMaxLatitude() - projectedBoundingBox.getMinLatitude();

        // Get the closest zoom level based on the tile size
        Long zoomLevel = tileDao.getClosestZoomLevel(distanceWidth, distanceHeight);

        // If a matching zoom level is found, retrieve the corresponding TileMatrix
        if (zoomLevel != null) {
            tileMatrix = tileDao.getTileMatrix(zoomLevel);
        }
    }

    return tileMatrix;
}

