private void adjustGoogleBounds() {
    // Set the tile matrix set bounding box to be the world BoundingBox
    BoundingBox standardWgs84Box = new BoundingBox(
        -ProjectionConstants.WGS84_HALF_WORLD_LON_WIDTH,
        ProjectionConstants.WEB_MERCATOR_MIN_LAT_RANGE,
        ProjectionConstants.WGS84_HALF_WORLD_LON_WIDTH,
        ProjectionConstants.WEB_MERCATOR_MAX_LAT_RANGE
    );

    // Create a transformation from WGS84 to Web Mercator
    ProjectionTransform wgs84ToWebMercatorTransform = ProjectionFactory.getProjection(
        ProjectionConstants.EPSG_WORLD_GEODETIC_SYSTEM
    ).getTransformation(
        ProjectionConstants.EPSG_WEB_MERCATOR
    );

    // Transform the bounding box to Web Mercator coordinates
    tileGridBoundingBox = standardWgs84Box.transform(wgs84ToWebMercatorTransform);
}

