 *
 * @param database       The name of the database to validate.
 * @param validateHeader Whether to validate the database header.
 * @param validateIntegrity Whether to validate the database integrity.
 * @return true if the database is valid, false otherwise.
 */
private boolean isValid(String database, boolean validateHeader, boolean validateIntegrity) {
    boolean valid = false;
    if (exists(database)) {
        GeoPackageCursorFactory cursorFactory = new GeoPackageCursorFactory();
        String path = null;
        SQLiteDatabase sqlite;
        GeoPackageMetadata metadata = getGeoPackageMetadata(database);
        if (metadata != null && metadata.isExternal()) {
            path = metadata.getExternalPath();
            try {
                sqlite = SQLiteDatabase.openDatabase(path, cursorFactory, SQLiteDatabase.OPEN_READWRITE | SQLiteDatabase.NO_LOCALIZED_COLLATORS);
            } catch (Exception e) {
                sqlite = SQLiteDatabase.openDatabase(path, cursorFactory, SQLiteDatabase.OPEN_READONLY | SQLiteDatabase.NO_LOCALIZED_COLLATORS);
            }
        } else {
            path = context.getDatabasePath(database).getAbsolutePath();
            sqlite = context.openOrCreateDatabase(database, Context.MODE_PRIVATE, cursorFactory);
        }
        try {
            valid = (!validateHeader || isDatabaseHeaderValid(sqlite)) && (!validateIntegrity || sqlite.isDatabaseIntegrityOk());
        } catch (Exception e) {
            Log.e(GeoPackageManagerImpl.class.getSimpleName(), "Failed to validate database", e);
        } finally {
            sqlite.close();
        }
    }
    return valid;
}

