/**
 * Calculates the bounding box for a given set of feature tiles in a GeoPackage.
 *
 * @param geoPackage The GeoPackage containing the feature tiles.
 * @param featureTiles The feature tiles for which to calculate the bounding box.
 * @param boundingBox The initial bounding box, or null if not provided.
 * @param projection The projection to use for the bounding box calculation.
 * @return The calculated bounding box, or null if no bounding box can be determined.
 */
private static BoundingBox getBoundingBox(GeoPackage geoPackage, FeatureTiles featureTiles, BoundingBox boundingBox, Projection projection) {
    String tableName = featureTiles.getFeatureDao().getTableName();
    boolean manualQuery = boundingBox == null;
    BoundingBox featureBoundingBox = geoPackage.getBoundingBox(projection, tableName, manualQuery);

    if (featureBoundingBox != null) {
        if (boundingBox == null) {
            boundingBox = featureBoundingBox;
        } else {
            boundingBox = boundingBox.overlap(featureBoundingBox);
        }
    }

    if (boundingBox != null) {
        boundingBox = featureTiles.expandBoundingBox(boundingBox, projection);
    }

    return boundingBox;
}

