 * 
 * @param parent The parent view.
 * @param view The current view.
 * @param name The name of the view.
 * @param context The context.
 * @param attrs The attributes.
 * @return The created view.
 */
private View createCustomViewInternal(View parent, View view, String name, Context context, AttributeSet attrs) {
    // If view is null and name contains a space, attempt to create a custom view.
    if (view == null && name.indexOf(' ') > -1) {
        // Get the mConstructorArgs field from LayoutInflater.
        if (mConstructorArgs == null) {
            mConstructorArgs = ReflectionUtils.getField(LayoutInflater.class, "mConstructorArgs");
        }
        // Get the current mConstructorArgs array.
        final Object[] mConstructorArgsArr = (Object[]) ReflectionUtils.getValue(mConstructorArgs, this);
        // Store the current context.
        final Object lastContext = mConstructorArgsArr[0];
        // Set the context to the parent's context if available, otherwise use the provided context.
        mConstructorArgsArr[0] = parent != null ? parent.getContext() : context;
        // Set the modified mConstructorArgs array back.
        ReflectionUtils.setValue(mConstructorArgs, this, mConstructorArgsArr);
        try {
            // Attempt to create the view.
            view = createView(name, null, attrs);
        } catch (ClassNotFoundException ignored) {
        } finally {
            // Restore the original context.
            mConstructorArgsArr[0] = lastContext;
            ReflectionUtils.setValue(mConstructorArgs, this, mConstructorArgsArr);
        }
    }
    return view;
}

