            result = Loader.getResource(logbackConfigFile, this.classLoader);
            if (result != null) {
                return result;
            }
        } finally {
            if (updateStatus) {
                statusOnResourceSearch(logbackConfigFile, this.classLoader, result != null ? result.toString() : null);
            }
        }
    }
    return null;
}

