/**
 * Steps over the current line in the debugger, handling MVEL-specific logic.
 * If the top stack frame is an instance of MVELStackFrame, it performs a MVEL-specific step over.
 * Otherwise, it calls the superclass's stepOver method.
 * 
 * @throws DebugException if an error occurs during the step over operation.
 */
public synchronized void stepOver() throws DebugException {
    // Check if the top stack frame is an instance of MVELStackFrame
    if (!(getTopStackFrame() instanceof MVELStackFrame)) {
        super.stepOver();
        return;
    }

    // Cast the top stack frame to MVELStackFrame
    MVELStackFrame mvelStack = (MVELStackFrame) getTopStackFrame();

    // Check if stepping over is possible
    if (!canStepOver() || !mvelStack.canStepOver()) {
        return;
    }

    // Set remote on break return
    if (!setRemoteOnBreakReturn(Debugger.STEP)) {
        return;
    }

    // Set running state
    setRunning(true);

    // Preserve stack frames
    preserveStackFrames();

    // Fire a resume event
    fireEvent(new DebugEvent(this, DebugEvent.RESUME, DebugEvent.STEP_OVER));

    try {
        // Resume the underlying thread
        getUnderlyingThread().resume();
    } catch (RuntimeException e) {
        // Handle runtime exception during stepping
        // stepEnd();
        targetRequestFailed(MessageFormat.format(JDIDebugModelMessages.JDIThread_exception_stepping, e.toString()), e);
    }
}

