 * Returns the class of the given argument, handling primitive types and their corresponding wrapper classes.
 * If the argument is null, returns null.
 * If the argument is a wrapper class for a primitive type, returns the corresponding primitive type class.
 * If the argument is a Number, returns the most specific primitive type class (e.g., Integer, Double).
 * If the argument is a Character, returns Character.TYPE.
 * Otherwise, returns the original class of the argument.
 *
 * @param arg the argument to get the class of
 * @return the class of the argument, or null if the argument is null
 */
public static final Class getArgClass(Object arg) {
    if (arg == null) return null;
    Class<?> c = arg.getClass();
    if (c == Boolean.class) return Boolean.TYPE;
    else if (c.getSuperclass() == Number.class) {
        if (c == Integer.class) return Integer.TYPE;
        if (c == Double.class) return Double.TYPE;
        if (c == Byte.class) return Byte.TYPE;
        if (c == Long.class) return Long.TYPE;
        if (c == Float.class) return Float.TYPE;
        if (c == Short.class) return Short.TYPE;
    } else if (c == Character.class) return Character.TYPE;
    return c;
}

