    // Extract namespace and local name from the attribute name
    String namespace = namespace(name, true);
    String localName = localName(name);

    // Check if the attribute already exists in the AttributesImpl object
    int i = atts.getIndex(name);
    if (i == -1) {
        // If the attribute does not exist, add it with the specified namespace, local name, type, and value
        name = name.intern();
        if (type == null) type = "CDATA";
        if (!type.equals("CDATA")) value = normalize(value);
        atts.addAttribute(namespace, localName, name, type, value);
    } else {
        // If the attribute already exists, update it with the specified namespace, local name, type, and value
        if (type == null) type = atts.getType(i);
        if (!type.equals("CDATA")) value = normalize(value);
        atts.setAttribute(i, namespace, localName, name, type, value);
    }
}

