/**
 * Adjusts the given matrix to properly scale and center a bitmap within a view.
 * 
 * @param bitmap The bitmap to be scaled and centered.
 * @param matrix The matrix to be adjusted.
 */
private void getProperBaseMatrix(RotateBitmap bitmap, Matrix matrix) {
    float viewWidth = getWidth();
    float viewHeight = getHeight();
    float w = bitmap.getWidth();
    float h = bitmap.getHeight();

    matrix.reset(); // Reset the matrix to its default state.

    // Calculate the maximum scaling factor to avoid up-scaling more than 2x.
    float widthScale = Math.min(viewWidth / w, 2.0f);
    float heightScale = Math.min(viewHeight / h, 2.0f);
    float scale = Math.min(widthScale, heightScale);

    // Apply the bitmap's rotation matrix.
    matrix.postConcat(bitmap.getRotateMatrix());

    // Scale the matrix by the calculated scale factor.
    matrix.postScale(scale, scale);

    // Translate the matrix to center the bitmap within the view.
    matrix.postTranslate((viewWidth - w * scale) / 2F, (viewHeight - h * scale) / 2F);
}

