/**
 * Completes the store snapshot by adding missing instance snapshots.
 * 
 * @param targetStoresPath The path to the target stores directory.
 */
private static void completeStoreSnapshotWithMissingInstanceSnapshots(Path targetStoresPath) {
    // Define regex patterns for transaction ID extraction and replacement.
    String transactionIdRegexAlone = "\"transactionId\"\\s*:\\s*\\d+\\s*,";
    String transactionIdRegexReplace = "(.*\"transactionId\"\\s*:\\s*)\\d+(\\s*,.*)";
    Pattern transactionIdPattern = Pattern.compile(transactionIdRegexAlone);

    // Set to store previous snapshots.
    Set<File> previousSnapshots = new HashSet<>();

    // Iterate over snapshots in the target stores directory.
    Arrays.stream(targetStoresPath.resolve(SNAPSHOT_DIRECTORY_NAME).toFile().listFiles())
        .sorted()
        .forEach(snapshot -> {
            // Collect names of files in the current snapshot.
            Set<String> snapshotNames = Arrays.stream(snapshot.listFiles())
                .map(File::getName)
                .collect(Collectors.toSet());

            // Filter and process previous snapshots that are missing in the current snapshot.
            previousSnapshots.stream()
                .filter(previousSnapshot -> !snapshotNames.contains(previousSnapshot.getName()))
                .forEach(previousSnapshot -> {
                    try {
                        // Resolve target and source paths.
                        Path targetPath = snapshot.toPath().resolve(previousSnapshot.getName());
                        Path sourcePath = previousSnapshot.toPath();

                        // Count occurrences of transaction ID in the source path.
                        long count = countTransactionId(transactionIdPattern, sourcePath);
                        if (count != 1L) {
                            throw new StoreException("transactionId not found once", args -> args.add("found count", count));
                        }

                        // Generate new transaction ID from the snapshot name.
                        BigInteger newTransactionId = new BigInteger(snapshot.getName());

                        // Replace transaction ID in the source path with the new transaction ID.
                        replaceTransactionIdValue(transactionIdRegexReplace, sourcePath, targetPath, newTransactionId.toString());
                    } catch (IOException e) {
                        throw new UncheckedIOException(e);
                    }
                });

            // Clear and update the set of previous snapshots.
            previousSnapshots.clear();
            previousSnapshots.addAll(Arrays.stream(snapshot.listFiles()).collect(Collectors.toSet()));
        });
}

