/**
 * Performs an Amazon action with retry logic.
 * 
 * @param <T> The type of the result returned by the action.
 * @param actionLabel A label for the action being performed.
 * @param action A supplier that represents the action to be performed.
 * @param retryLimit The maximum number of retries allowed.
 * @param durationInMillis The duration to wait between retries in milliseconds.
 * @return The result of the action if successful.
 * @throws AwsException If the action fails after the maximum number of retries.
 */
public static <T> T performAmazonActionWithRetry(String actionLabel, Supplier<T> action, int retryLimit, int durationInMillis) {
    int retryCount = 0;
    do {
        try {
            return action.get();
        } catch (LimitExceededException | ProvisionedThroughputExceededException | KMSThrottlingException e) {
            int remainingRetries = retryLimit - retryCount;
            LOG.debug("Amazon exception caught", args -> args.add("exception", e.getClass().getName()).add("action", actionLabel).add("remainingRetryCount", remainingRetries));
        }
        sleepUntilInterrupted(actionLabel, durationInMillis);
    } while (++retryCount < retryLimit);
    throw new AwsException("Limit exceeded, all retries failed", args -> args.add("action", actionLabel).add("retryLimit", retryLimit));
}

