    LOG.debug("Applying gzip on resource: " + req.getRequestURI());
    response.setHeader(HttpHeader.CONTENT_ENCODING.toString(), "gzip");

    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    CountingOutputStream countingStream = new CountingOutputStream(new GZIPOutputStream(new BufferedOutputStream(baos)));

    HttpServletResponseWrapper wrappedResponse = new RedirectedStreamServletResponseWrapper(countingStream, response);
    chain.doFilter(req, wrappedResponse);

    countingStream.close();
    response.setContentLength(countingStream.getCount());

    if (countingStream.getCount() > 0) {
        IOUtils.write(baos.toByteArray(), response.getOutputStream());
    }
}

