 * @param out       the writer to output the data URI
 * @param mimeType  the MIME type of the data
 * @throws IOException if an I/O error occurs
 */
private void generateDataURI(final byte[] bytes, final Writer out, final String mimeType) throws IOException {
    // Create the output buffer
    final StringBuffer buffer = new StringBuffer();
    // Append the data URI prefix
    buffer.append(DATA_URI_PREFIX);
    // Append the MIME type
    buffer.append(mimeType);
    // Append the base64-encoded data
