/**
 * Parses a group element and returns its resources.
 * 
 * @param element The group element to parse.
 * @return The resources of the parsed group.
 * @throws RecursiveGroupDefinitionException If a recursive group definition is detected.
 */
private Collection<Resource> parseGroup(final Element element) {
    final String name = element.getAttribute(ATTR_GROUP_NAME);
    final boolean isAbstractGroup = StringUtils.isNotEmpty(element.getAttribute(ATTR_GROUP_ABSTRACT)) && Boolean.valueOf(element.getAttribute(ATTR_GROUP_ABSTRACT));

    if (groupsInProcess.contains(name)) {
        throw new RecursiveGroupDefinitionException("Infinite Recursion detected for the group: " + name + ". Recursion path: " + groupsInProcess);
    }

    LOG.debug("\tadding group: {}", name);
    groupsInProcess.add(name);

    // Skip if this group is already parsed
    final Group parsedGroup = new WroModelInspector(model).getGroupByName(name);
    if (parsedGroup != null) {
        groupsInProcess.remove(name);
        return parsedGroup.getResources();
    }

    final Group group = createGroup(element);
    groupsInProcess.remove(name);

    if (!isAbstractGroup) {
        model.addGroup(group);
    }

    return group.getResources();
}

