/**
 * Updates the counters for finished jobs and ensures that all contexts for processed jobs are marked as saturated.
 * 
 * @param localStatistics The local statistics object to update.
 * @throws InterruptedException If the thread is interrupted.
 */
private void updateFinishedCounters(ThisStatistics localStatistics) throws InterruptedException {
    int snapshotJobsProcessed = countJobsProcessedLower_.get();

    // Ensure all contexts for processed jobs are marked as saturated
    for (;;) {
        int snapshotCountContextsSaturatedLower = countContextsSaturatedLower_.get();
        saturationState_.setContextsSaturated(snapshotCountContextsSaturatedLower);
        if (saturationState_.getContextSetSaturatedCount() < snapshotCountContextsSaturatedLower) {
            // Another worker marked contexts as saturated, so mark finished jobs instead
            return;
        }

        // Ensure the counter for processed jobs is still up to date
        int updatedSnapshotJobsProcessed = countJobsProcessedLower_.get();
        if (updatedSnapshotJobsProcessed == snapshotJobsProcessed) {
            break;
        }
        // Else refresh counters
        snapshotJobsProcessed = updatedSnapshotJobsProcessed;
    }

    // Ensure all processed jobs are finished
    for (;;) {
        int snapshotJobsFinished = countJobsFinishedUpper_.get();
        if (snapshotJobsFinished >= snapshotJobsProcessed) {
            break;
        }

        // Update the finished context counter and mark the corresponding number of jobs as processed
        if (!countJobsFinishedUpper_.compareAndSet(snapshotJobsFinished, snapshotJobsFinished + 1)) {
            // Retry
            continue;
        }

        Job nextJob = jobsInProgress_.poll();
        IndexedContextRoot root = nextJob.getInput();
        Context rootSaturation = saturationState_.getContext(root);
        if (rootSaturation.isInitialized() && !rootSaturation.isSaturated()) {
            LOGGER_.error("{}: context for a finished job not saturated!", rootSaturation);
        }
        nextJob.setOutput(rootSaturation);
        LOGGER_.trace("{}: saturation finished", root);
        localStatistics.jobsProcessedNo++;
        listener_.notifyFinished(nextJob); // Can be interrupted
    }
}

