/**
 * Puts a key-value pair into the arrays and returns the old value associated with the key.
 * If the key does not exist, it is added and null is returned.
 * If the key already exists, its value is updated and the old value is returned.
 *
 * @param keys   the array of keys
 * @param values the array of values
 * @param key    the key to be inserted or updated
 * @param value  the value to be associated with the key
 * @param <K>    the type of the keys
 * @param <V>    the type of the values
 * @return the old value associated with the key, or null if the key was not previously present
 */
private static <K, V> V putKeyValue(K[] keys, V[] values, K key, V value) {
    int pos = LinearProbing.getPosition(keys, key);
    if (keys[pos] == null) {
        keys[pos] = key;
        values[pos] = value;
        return null;
    } else {
        V oldValue = values[pos];
        values[pos] = value;
        return oldValue;
    }
}

