/**
 * Removes an entry from the key-value pairs based on the given key.
 *
 * @param keys   the array of keys
 * @param values the array of values
 * @param key    the key to remove
 * @param <K>    the type of keys
 * @param <V>    the type of values
 * @return the value associated with the removed key, or null if the key is not found
 */
private static <K, V> V removeEntry(K[] keys, V[] values, Object key) {
    int pos = LinearProbing.getPosition(keys, key);
    if (keys[pos] == null) {
        return null;
    } else {
        V result = values[pos];
        LinearProbing.remove(keys, values, pos);
        return result;
    }
}

