/**
 * Processes a taxonomy and writes the declarations and member axioms to a writer.
 * 
 * @param taxonomy The taxonomy to process.
 * @param writer The writer to write the output to.
 * @throws IOException If an I/O error occurs.
 */
protected static <T extends ElkEntity> void processTaxonomy(final Taxonomy<T> taxonomy, final Appendable writer) throws IOException {
    // Create an object factory.
    final ElkObject.Factory factory = new ElkObjectEntityRecyclingFactory();

    // Collect members, excluding top and bottom nodes.
    final List<T> members = new ArrayList<>(taxonomy.getNodes().size() * 2);
    for (final TaxonomyNode<T> node : taxonomy.getNodes()) {
        for (final T member : node) {
            if (!member.getIri().equals(taxonomy.getTopNode().getCanonicalMember().getIri()) &&
                !member.getIri().equals(taxonomy.getBottomNode().getCanonicalMember().getIri())) {
                members.add(member);
            }
        }
    }
    Collections.sort(members, taxonomy.getKeyProvider().getComparator());
    printDeclarations(members, factory, writer);

    // Process relations.
    final TreeSet<T> canonicalMembers = new TreeSet<>(taxonomy.getKeyProvider().getComparator());
    for (final TaxonomyNode<T> node : taxonomy.getNodes()) {
        canonicalMembers.add(node.getCanonicalMember());
    }
    for (final T canonicalMember : canonicalMembers) {
        final TaxonomyNode<T> node = taxonomy.getNode(canonicalMember);
        final ArrayList<T> orderedEquivalentMembers = new ArrayList<>(node.size());
        for (final T member : node) {
            orderedEquivalentMembers.add(member);
        }
        Collections.sort(orderedEquivalentMembers, taxonomy.getKeyProvider().getComparator());
        final TreeSet<T> orderedSuperMembers = new TreeSet<>(taxonomy.getKeyProvider().getComparator());
        for (final TaxonomyNode<T> superNode : node.getDirectSuperNodes()) {
            orderedSuperMembers.add(superNode.getCanonicalMember());
        }
        printMemberAxioms(canonicalMember, orderedEquivalentMembers, orderedSuperMembers, taxonomy, factory, writer);
    }
}

