/**
 * Verifies that the start position exists in the given full chain of object properties.
 * 
 * @param fullChain The full chain of object properties to be checked.
 * @param startPos The start position to be verified.
 * @throws IllegalArgumentException If the start position is out of bounds for the given chain.
 */
protected static void checkChainMatch(final ElkSubObjectPropertyExpression fullChain, final int startPos) {
    fullChain.accept(new ElkSubObjectPropertyExpressionVisitor<Void>() {
        void fail() {
            throw new IllegalArgumentException(fullChain + ", " + startPos);
        }

        Void defaultVisit(ElkObjectPropertyExpression expression) {
            if (startPos != 0) {
                fail();
            }
            return null;
        }

        @Override
        public Void visit(ElkObjectPropertyChain expression) {
            if (startPos < 0 || startPos >= expression.getObjectPropertyExpressions().size()) {
                fail();
            }
            return null;
        }

        @Override
        public Void visit(ElkObjectInverseOf expression) {
            return defaultVisit(expression);
        }

        @Override
        public Void visit(ElkObjectProperty expression) {
            return defaultVisit(expression);
        }
    });
}

