/**
 * Removes an object from the specified slot in the data structure.
 *
 * @param s the slot index
 * @param o the object to remove
 * @return true if the object was successfully removed, false otherwise
 * @throws NullPointerException if the object is null
 */
public boolean remove(int s, Object o) {
    if (o == null) throw new NullPointerException();
    int mask = 1 << s;
    int oldMask = removeMask(logs, data, masks, o, mask);
    int newMask = oldMask & ~mask;
    if (newMask == oldMask) return false;
    sizes[s]--;
    return true;
}

