/**
 * This method performs a fold operation on an iterable source using a series of operations.
 * @param <H> The type of the result.
 * @param source The iterable source to process.
 * @param ops An array of operations to apply.
 * @param opIdx The starting index of operations to apply.
 * @param ident The identity value for the reduction.
 * @param reducer The function to combine elements.
 * @return The result of the fold operation.
 */
@SuppressWarnings("unchecked")
private static <H> H _fold(Iterable source, Operation[] ops, int opIdx, H ident, Fn2 reducer) {
    Object ret = ident; // Initialize the result with the identity value.
    sourceLoop: for (Object o : source) {
        for (int j = opIdx; j < ops.length; j++) {
            Operation op = ops[j];
            if (op.filter != null && !op.filter.apply(o)) {
                // Skip this item if it does not pass the filter.
                continue sourceLoop;
            }
            if (op.map != null) {
                o = op.map.apply(o);
                if (o == TERMINATE) {
                    return (H) ret; // Terminate if the map function returns TERMINATE.
                }
            } else if (op.flatMap != null) {
                ret = _fold(op.flatMap.apply(o), ops, j + 1, (H) ret, reducer);
                continue sourceLoop; // Continue with the next item in the source.
            }
            // Combine the current item with the result using the reducer.
            ret = reducer.apply(ret, o);
        }
    }
    return (H) ret; // Return the final result.
}

