private void verifyConfigProperties(ConfigProperties newProperties) throws InvalidConfigurationException {
    if (doTraceLogs) {
        logger.trace("verifyConfigProperties( newProperties = " + newProperties + " )");
    }

    // Merge properties
    for (ConfigProperties.Property configProperty : configProperties.getProperties()) {
        if (newProperties.getProperty(configProperty.getName()) == null) {
            newProperties.addProperty(configProperty);
        }
    }

    // Validate properties
    for (ConfigProperties.Property entityProperty : newProperties.getProperties()) {
        if (entityProperty.getValue() == null) {
            throw new InvalidConfigurationException("the property " + entityProperty.getName() + " has null value");
        }
    }

    // Validate in RA object
    object.raVerifyConfiguration(newProperties);

    // Switch config
    configProperties = newProperties;
}

