    URL url = du.getUrl();
    if (logger.isTraceEnabled()) {
        logger.trace("Method accepts called for " + url + " [DU: " + deployableUnitName + "]");
    }
    try {
        String fullPath = url.getFile();
        String fileName = fullPath.substring(fullPath.lastIndexOf('/') + 1, fullPath.length());
        // Check if the file is in the toAccept list
        if (toAccept.containsKey(fileName)) {
            if (logger.isTraceEnabled()) {
                logger.trace("Accepting " + url.toString() + ".");
            }
            return true;
        }
        // Check if the file is a jar and might be a DU jar
        else if (fileName.endsWith(".jar")) {
            JarFile duJarFile = null;
            try {
                // Try to obtain the DU descriptor
                if (du.getEntry("META-INF/deployable-unit.xml") != null) {
                    if (logger.isTraceEnabled()) {
                        logger.trace("Accepting " + url.toString() + ".");
                    }
                    return true;
                }
            } finally {
                // Clean up
                if (duJarFile != null) {
                    try {
                        duJarFile.close();
                    } catch (IOException ignore) {
                    } finally {
                        duJarFile = null;
                    }
                }
            }
        }
    } catch (Exception ignore) {
        // Ignore exception, will reject
    }
    // Reject if no conditions are met
    return false;
}

