/**
 * Validates the transition between two states in a sleep system.
 * 
 * @param oldState The previous state.
 * @param newState The new state.
 * @throws InvalidStateException If the transition is not allowed.
 */
private void validateStateTransition(SleeState oldState, SleeState newState) throws InvalidStateException {
    if (oldState == SleeState.STOPPED) {
        if (newState == SleeState.STARTING) return;
    } else if (oldState == SleeState.STARTING) {
        if (newState == SleeState.RUNNING || newState == SleeState.STOPPING) return;
    } else if (oldState == SleeState.RUNNING) {
        if (newState == SleeState.STOPPING) return;
    } else if (oldState == SleeState.STOPPING) {
        if (newState == SleeState.STOPPED) return;
    }
    throw new InvalidStateException("illegal sleep state transition: " + oldState + " -> " + newState);
}

