        barberShop.addField(FieldSpec.builder(WeakHashSet.class, "lastStyledTargets", Modifier.PROTECTED)
            .initializer("new $T()", WeakHashSet.class)
            .build());
    } else {
        // Set the superclass if parentBarbershop is not null
