        Class<?> keyType = (Class<?>) field.getParameterizedType().getActualTypeArguments()[0];
        Class<?> valueType = (Class<?>) field.getParameterizedType().getActualTypeArguments()[1];
        Set<Map.Entry> set = mapInner.entrySet();
