public void nextBufferToWrite(final ByteBuffer bufferOut) throws InterruptedException {
    dirty = true;
    int size = bufferOut.limit();
    write(bufferOut);
    if (!error.get()) {
        totalBytesTransferred += size;
        bytesTransferred += size;
        bytesSinceLastFlush += size;
