    if (this.bytesTransferred >= FILE_SIZE_BYTES || fileTimeOut.get()) {
        try {
            outputStream.close();
        } catch (IOException e) {
            cleanupOutputStream();
            e.printStackTrace(System.err);
        } finally {
            outputStream = null;
        }
    }
}


