/**
 * Writes data from a ByteBuffer to an output stream, handling exceptions and flushing periodically.
 * 
 * @param bufferOut The ByteBuffer containing the data to write.
 * @throws InterruptedException If the operation is interrupted.
 */
private void write(final ByteBuffer bufferOut) throws InterruptedException {
    initOutputStream();
    try {
        if (outputStream != null) {
            outputStream.write(bufferOut);
        } else {
            error.set(true);
        }
        if (bytesSinceLastFlush > FLUSH_EVERY_N_BYTES) {
            syncToDisk();
            bytesSinceLastFlush = 0;
        }
    } catch (ClosedByInterruptException cbie) {
        throw new InterruptedException("File closed by interruption");
    } catch (Exception e) {
        cleanupOutputStream();
        error.set(true);
        e.printStackTrace(System.err);
        diagnose();
        Exceptions.handle(e);
    }
}

