/**
 * Determines the HTTP verb for the given server exchange.
 * If the request is a query type, it is treated as a GET request.
 * Otherwise, it retrieves the verb based on the request method.
 * If the method is not handled, it defaults to a read access verb.
 *
 * @param serverExchange The server exchange to determine the verb for.
 * @return The HTTP verb as a String.
 */
private String getVerb(HttpServerExchange serverExchange) {
    if (isQuery(serverExchange)) {
        return VERBS.get(GET);
    } else {
        String verb = VERBS.get(serverExchange.getRequestMethod());
        if (verb == null) {
            log.debugf("Unhandled http method '%s'. Checking for read access.", serverExchange.getRequestMethod());
            verb = VERBS_DEFAULT;
        }
        return verb;
    }
}

