 * Completes a multi-part upload to an object in a bucket.
 *
 * @param objectKey The key of the object to upload.
 * @param fileName The name of the file being uploaded.
 * @param eTag The ETag of the uploaded parts.
 * @param uploadID The upload ID for the multi-part upload.
 * @param length The total length of the uploaded data.
 * @throws QSException If an error occurs during the upload.
 */
private void completeMultiUpload(String objectKey, String fileName, String eTag, String uploadID, long length) throws QSException {
    CompleteMultipartUploadInput input = new CompleteMultipartUploadInput(uploadID, partCounts, 0);
    input.setContentLength(length);

    if (!QSStringUtil.isEmpty(fileName)) {
        try {
            String keyName = QSStringUtil.percentEncode(fileName, "UTF-8");
            input.setContentDisposition(String.format("attachment; filename=\"%s\"; filename*=utf-8''%s", keyName, keyName));
        } catch (UnsupportedEncodingException e) {
            e.printStackTrace();
        }
    }

    if (!QSStringUtil.isEmpty(eTag)) {
        input.setETag(eTag);
    }

    RequestHandler requestHandler = bucket.completeMultipartUploadRequest(objectKey, input);
    sign(requestHandler);
    Bucket.CompleteMultipartUploadOutput response = (Bucket.CompleteMultipartUploadOutput) requestHandler.send();

    if (response.getStatueCode() == 200 || response.getStatueCode() == 201) {
        uploadModel.setUploadComplete(true);
        setData(objectKey, recorder);
    }

    if (callBack != null) {
        callBack.onAPIResponse(objectKey, response);
    }
}

