/**
 * Finds the closest point on a plane to a given point.
 * 
 * @param P The point to find the closest point to.
 * @param closestPt The closest point on the plane.
 */
public void closestPoint(Point3D_F64 P, Point3D_F64 closestPt) {
    // Calculate the vector from point B to point P
    GeometryMath_F64.sub(B, P, D);

    // Calculate dot products
    double a = E0.dot(E0);
    double b = E0.dot(E1);
    double c = E1.dot(E1);
    double d = E0.dot(D);
    double e = E1.dot(D);

    // Calculate determinant
    double det = a * c - b * b;

    // Calculate s and t
    double s = b * e - c * d;
    double t = b * d - a * e;

    // Determine region and call corresponding method
    if (s + t <= det) {
        if (s < 0) {
            if (t < 0) {
                region4();
            } else {
                region3();
            }
        } else if (t < 0) {
            region5();
        } else {
            region0(det);
        }
    } else {
        if (s < 0) {
            region2();
        } else if (t < 0) {
            region6();
        } else {
            region1();
        }
    }

    // Calculate the closest point on the plane
    closestPt.x = B.x + s * E0.x + t * E1.x;
    closestPt.y = B.y + s * E0.y + t * E1.y;
    closestPt.z = B.z + s * E0.z + t * E1.z;
}

