/**
 * Calculates the bounding rectangle for a given polygon.
 * 
 * @param polygon The input polygon.
 * @param rectangle The output rectangle that will be set to the bounding box of the polygon.
 */
public static void bounding(Polygon2D_F64 polygon, Rectangle2D_F64 rectangle) {
    // Initialize the rectangle's corners with the first point of the polygon
    rectangle.p0.set(polygon.get(0));
    rectangle.p1.set(polygon.get(0));

    // Iterate through each point in the polygon
    for (int i = 0; i < polygon.size(); i++) {
        Point2D_F64 p = polygon.get(i);

        // Update the minimum x-coordinate
        if (p.x < rectangle.p0.x) {
            rectangle.p0.x = p.x;
        }

        // Update the maximum x-coordinate
        else if (p.x > rectangle.p1.x) {
            rectangle.p1.x = p.x;
        }

        // Update the minimum y-coordinate
        if (p.y < rectangle.p0.y) {
            rectangle.p0.y = p.y;
        }

        // Update the maximum y-coordinate
        else if (p.y > rectangle.p1.y) {
            rectangle.p1.y = p.y;
        }
    }
}

