/**
 * Checks if a point is contained within a quadrilateral by dividing it into two triangles and checking if the point is in either triangle.
 *
 * @param quad The quadrilateral to check.
 * @param pt The point to check.
 * @return true if the point is inside the quadrilateral, false otherwise.
 */
public static boolean contains(Quadrilateral_F64 quad, Point2D_F64 pt) {
