/**
 * Calculates the intersection point of two parametric lines.
 *
 * @param a The first parametric line.
 * @param b The second parametric line.
 * @param ret The point to store the intersection result, or null to create a new point.
 * @return The intersection point if it exists, otherwise null.
 */
public static Point2D_F64 intersection(LineParametric2D_F64 a, LineParametric2D_F64 b, Point2D_F64 ret) {
    double t_b = a.getSlopeX() * (b.getY() - a.getY()) - a.getSlopeY() * (b.getX() - a.getX());
    double bottom = a.getSlopeY() * b.getSlopeX() - b.getSlopeY() * a.getSlopeX();
    if (bottom == 0) return null;
    t_b /= bottom;
    double x = b.getSlopeX() * t_b + b.getX();
    double y = b.getSlopeY() * t_b + b.getY();
    if (ret == null) ret = new Point2D_F64();
    ret.set(x, y);
    return ret;
}

