/**
 * Calculates the intersection point of two lines defined by four points.
 *
 * @param lineA0 The first point of the first line.
 * @param lineA1 The second point of the first line.
 * @param lineB0 The first point of the second line.
 * @param lineB1 The second point of the second line.
 * @param output The point to store the intersection result. If null, a new point is created.
 * @return The intersection point if the lines intersect, otherwise null.
 */
public static Point2D_F64 intersection(Point2D_F64 lineA0, Point2D_F64 lineA1, Point2D_F64 lineB0, Point2D_F64 lineB1, Point2D_F64 output) {
    if (output == null) {
        output = new Point2D_F64();
    }

    double slopeAx = lineA1.x - lineA0.x;
    double slopeAy = lineA1.y - lineA0.y;
    double slopeBx = lineB1.x - lineB0.x;
    double slopeBy = lineB1.y - lineB0.y;

    double top = slopeAy * (lineB0.x - lineA0.x) + slopeAx * (lineA0.y - lineB0.y);
    double bottom = slopeAx * slopeBy - slopeAy * slopeBx;

    if (bottom == 0) {
        return null;
    }

    double t = top / bottom;
    output.x = lineB0.x + t * slopeBx;
    output.y = lineB0.y + t * slopeBy;

    return output;
}

