public void setParamVector(double x, double y, double z) {
    // Calculate the absolute values of x, y, and z
    double ax = Math.abs(x);
    double ay = Math.abs(y);
    double az = Math.abs(z);

    // Determine the maximum absolute value
    double max = Math.max(ax, ay);
    max = Math.max(max, az);

    // If the maximum value is zero, set theta to 0 and unitAxisRotation to (1, 0, 0)
    if (max == 0) {
        theta = 0;
        unitAxisRotation.set(1, 0, 0);
    } else {
        // Normalize the vector (x, y, z) by dividing each component by the maximum value
        x /= max;
        y /= max;
        z /= max;

        // Calculate the magnitude of the normalized vector
        theta = Math.sqrt(x * x + y * y + z * z);

        // Set the components of unitAxisRotation to the normalized vector components
        unitAxisRotation.x = x / theta;
        unitAxisRotation.y = y / theta;
        unitAxisRotation.z = z / theta;

        // Scale theta by the maximum value
        theta *= max;
    }
}

