/**
 * Converts an {@link EllipseRotated_F64} to an {@link EllipseQuadratic_F64}.
 *
 * @param input The input ellipse in rotated form.
 * @param output The output ellipse in quadratic form. If null, a new one will be created.
 * @return The converted ellipse in quadratic form.
 */
public static EllipseQuadratic_F64 convert(EllipseRotated_F64 input, EllipseQuadratic_F64 output) {
    if (output == null) {
        output = new EllipseQuadratic_F64();
    }

    double x0 = input.center.x;
    double y0 = input.center.y;
    double a = input.a;
    double b = input.b;
    double phi = input.phi;

    double cphi = Math.cos(phi);
    double sphi = Math.sin(phi);
    double cphi2 = cphi * cphi;
    double sphi2 = sphi * sphi;
    double a2 = a * a;
    double b2 = b * b;
    double x02 = x0 * x0;
    double y02 = y0 * y0;

    output.A = cphi2 / a2 + sphi2 / b2;
    output.B = sphi * cphi / a2 - sphi * cphi / b2;
    output.C = sphi2 / a2 + cphi2 / b2;
    output.D = -x0 * cphi2 / a2 - y0 * sphi * cphi / a2 - x0 * sphi2 / b2 + y0 * sphi * cphi / b2;
    output.E = -x0 * sphi * cphi / a2 - y0 * sphi2 / a2 + x0 * sphi * cphi / b2 - y0 * cphi2 / b2;
    output.F = x02 * cphi2 / a2 + 2 * x0 * y0 * sphi * cphi / a2 + y02 * sphi2 / a2 + x02 * sphi2 / b2 - 2 * x0 * y0 * sphi * cphi / b2 + y02 * cphi2 / b2 - 1;

    return output;
}

