/**
 * Calculates the shortest distance from a point to a line segment in 3D space.
 *
 * @param l The line segment.
 * @param p The point.
 * @return The shortest distance from the point to the line segment.
 */
public static double distance(LineSegment3D_F64 l, Point3D_F64 p) {
    // Calculate the vector components from point p to the start of the line segment l.a
    double dx = p.x - l.a.x;
    double dy = p.y - l.a.y;
    double dz = p.z - l.a.z;

    // Calculate the squared distance from point p to the start of the line segment
    double cc = dx * dx + dy * dy + dz * dz;

    // Calculate the direction vector of the line segment
    double slope_x = l.b.x - l.a.x;
    double slope_y = l.b.y - l.a.y;
    double slope_z = l.b.z - l.a.z;

    // Calculate the length of the line segment
    double n = Math.sqrt(slope_x * slope_x + slope_y * slope_y + slope_z * slope_z);

    // Calculate the projection of the vector from p to l.a onto the line segment
    double d = (slope_x * dx + slope_y * dy + slope_z * dz) / n;

    // Check if the projection is outside the line segment
    if (d <= 0) {
        return p.distance(l.a);
    } else if (d >= n) {
        return p.distance(l.b);
    }

    // Calculate the squared distance from the projection to the point
    double distanceSq = cc - d * d;

    // Handle potential numerical errors that could make distanceSq negative
    if (distanceSq < 0) {
        return 0;
    } else {
        return Math.sqrt(distanceSq);
    }
}

