public static Vector3D_F64 perpendicularCanonical(Vector3D_F64 A, Vector3D_F64 output) {
    if (output == null) {
        output = new Vector3D_F64();
    }

    // Normalize the input vector for scaling
    double scale = Math.abs(A.x) + Math.abs(A.y) + Math.abs(A.z);
    if (scale == 0) {
        output.set(0, 0, 0);
    } else {
        double x = A.x / scale;
        double y = A.y / scale;
        double z = A.z / scale;

        // Ensure numerical stability by swapping the largest variable
        if (Math.abs(x) > Math.abs(y)) {
            output.set(z, 0, -x);
        } else {
            output.set(0, z, -y);
        }
    }

    return output;
}

