    try (JarFile jarFile = new JarFile(artifact)) {
        Manifest manifest = jarFile.getManifest();
        if (manifest != null) {
            Attributes attributes = manifest.getMainAttributes();
            if (attributes.getValue(BOOT_VERSION_ATTRIBUTE) != null && attributes.getValue(BOOT_START_CLASS_ATTRIBUTE) != null) {
                return true;
            } else {
                Enumeration<JarEntry> entries = jarFile.entries();
                while (entries.hasMoreElements()) {
                    JarEntry entry = entries.nextElement();
                    String entryName = entry.getName();
                    if (!entryName.startsWith("org") && (entryName.matches(BOOT_JAR_EXPRESSION) || entryName.matches(BOOT_WAR_EXPRESSION))) {
                        return true;
                    }
                }
            }
        }
    } catch (IOException e) {
        // Handle IOException
    }
    return false;
}

