/**
 * Starts a process with transaction handling.
 * 
 * <ol>
 *   <li>Calls the `before` method.</li>
 *   <li>Wraps the transaction using `transactionWrapper`.</li>
 *   <li>Calls the `success` method if no exceptions occur.</li>
 *   <li>Calls the `error` method and handles the exception if an exception occurs.</li>
 *   <li>Finally, calls the `finish` method.</li>
 * </ol>
 * 
 * @throws Exception if an exception occurs and no exception handler is provided.
 */
private void start() {
    try {
        before();
        transactionWrapper.wrap();
        success();
    } catch (Exception e) {
        error();
        if (exceptionHandler != null) {
            exceptionHandler.onException(e);
        } else {
            throw e;
        }
    } finally {
        finish();
    }
}

