/**
 * Parses a regular expression and constructs a Subre (subregular expression) tree.
 * 
 * @param stopper The character that stops the parsing.
 * @param type The type of the regular expression.
 * @param initState The initial state of the NFA (Nondeterministic Finite Automaton).
 * @param finalState The final state of the NFA.
 * @return The root of the constructed Subre tree.
 * @throws RegexException If there are unbalanced parentheses.
 */
private Subre parse(int stopper, int type, State initState, State finalState) throws RegexException {
    State left, right;
    Subre branches, branch, t;
    int firstbranch = 1;

    assert stopper == ' ' || stopper == EOS;
    branches = new Subre(' ', Subre.LONGER, initState, finalState);
    branch = branches;

    do {
        if (0 == firstbranch) {
            branch.right = new Subre(' ', Subre.LONGER, initState, finalState);
            branch = branch.right;
        }
        firstbranch = 0;

        left = nfa.newstate();
        right = nfa.newstate();
        nfa.emptyarc(initState, left);
        nfa.emptyarc(right, finalState);

        branch.left = parsebranch(stopper, type, left, right, false);
        branch.flags |= up(branch.flags | branch.left.flags);

        if ((branch.flags & ~branches.flags) != 0) {
            for (t = branches; t != branch; t = t.right) {
                t.flags |= branch.flags;
            }
        }
    } while (eat(' '));

    assert see(stopper) || see(EOS);
    if (!see(stopper)) {
        assert stopper == ' ' && see(EOS);
        throw new RegexException("Unbalanced parentheses.");
    }

    if (branch == branches) {
        assert branch.right == null;
        t = branch.left;
        branch.left = null;
        branches = t;
    } else if (!messy(branches.flags)) {
        branches.left = null;
        branches.right = null;
        branches.op = ' ';
    }

    return branches;
}

