void freestate(State s) {
    assert s != null;
    assert s.nins == 0;
    assert s.nouts == 0;

    if (s.next != null) {
        s.next.prev = s.prev;
    } else {
        assert s == slast;
        slast = s.prev;
    }

    if (s.prev != null) {
        s.prev.next = s.next;
    } else {
        assert s == states;
        states = s.next;
    }
}


