    } else if (result && !reader.matchesETag(tag)) {
        // Translation error if <jsp:attribute> is present but not followed by <jsp:body> or the end tag
        err.jspError(reader.mark(), "jsp.error.jspbody.required", "&lt;" + tag);
    }
    return result;
}

