/**
 * Locates the URI root for a given file.
 * 
 * @param f The file to locate the URI root for.
 */
private void locateUriRoot(File f) {
    String tUriBase = uriBase;
    if (tUriBase == null) {
        tUriBase = "/";
    }
    try {
        if (f.exists()) {
            f = new File(f.getCanonicalPath());
            while (f != null) {
                File g = new File(f, "WEB-INF");
                if (g.exists() && g.isDirectory()) {
                    uriRoot = f.getCanonicalPath();
                    uriBase = tUriBase;
                    if (log.isLoggable(Level.INFO)) {
                        log.info(Localizer.getMessage("jspc.implicit.uriRoot", uriRoot));
                    }
                    break;
                }
                if (f.exists() && f.isDirectory()) {
                    tUriBase = "/" + f.getName() + "/" + tUriBase;
                }
                String fParent = f.getParent();
                if (fParent == null) {
                    break;
                } else {
                    f = new File(fParent);
                }
            }
            if (uriRoot != null) {
                File froot = new File(uriRoot);
                uriRoot = froot.getCanonicalPath();
            }
        }
    } catch (IOException ioe) {
        // Ignore the exception as a null value for uriRoot is non-error meaning.
    }
}

