 *
 * @param srcType The source rollup type.
 * @param srcGran The source granularity.
 * @return The corresponding rollup computation type.
 * @throws IllegalArgumentException if the rollup computation is not supported for the given source type and granularity.
 */
public static Rollup.Type getRollupComputer(RollupType srcType, Granularity srcGran) {
    switch (srcType) {
        case COUNTER:
            return Rollup.CounterFromCounter;
        case TIMER:
            return Rollup.TimerFromTimer;
        case GAUGE:
            return Rollup.GaugeFromGauge;
        case BF_BASIC:
            return srcGran == Granularity.FULL ? Rollup.BasicFromRaw : Rollup.BasicFromBasic;
