public ThreadPoolBuilder withName(String name) {
    // Ensure the name contains a placeholder for the thread ID.
    if (!name.contains("%d")) {
        name = name + "-%d";
    }
    // Store the name and initialize the thread ID counter.
    nameMap.putIfAbsent(name, new AtomicInteger(0));
    int id = nameMap.get(name).incrementAndGet();
    // Set the pool name with the current thread ID.
    this.poolName = String.format(name, id);
    // Set the thread name format based on the thread ID.
    if (id > 1) {
        this.threadNameFormat = name.replace("%d", id + "-%d");
