/**
 * Determines the granularity based on the requested duration and points.
 * If the requested duration divided by the granularity's milliseconds is greater than the points,
 * it attempts to get a coarser granularity. If it reaches the coarsest granularity (1440 milliseconds),
 * it returns the coarsest granularity without throwing an exception.
 *
 * @param requestedDuration The requested duration.
 * @param points The number of points.
 * @param assumedIntervalMillis The assumed interval in milliseconds.
 * @return The determined granularity.
 */
private static Granularity granularityFromPointsLessThanEqual(double requestedDuration, int points, long assumedIntervalMillis) {
    Granularity gran = granularityFromPointsLinear(requestedDuration, points, assumedIntervalMillis);
    if (requestedDuration / gran.milliseconds() > points) {
        try {
            gran = gran.coarser();
        } catch (GranularityException e) {
            // Do nothing, already at the coarsest granularity (1440 milliseconds)
        }
    }
    return gran;
}

