protected Set<Locator> getLocators(RollupExecutionContext executionContext, boolean isReroll, Granularity delayedMetricsRerollGranularity, Granularity delayedMetricsStorageGranularity) {
    Set<Locator> locators = new HashSet<>();

    if (RECORD_DELAYED_METRICS && isReroll && !getGranularity().isCoarser(delayedMetricsRerollGranularity)) {
        if (getGranularity().isCoarser(delayedMetricsStorageGranularity)) {
            for (SlotKey slotKey : parentSlotKey.getChildrenKeys(delayedMetricsStorageGranularity)) {
                locators.addAll(getDelayedLocators(executionContext, slotKey));
            }
        } else {
            locators = getDelayedLocators(executionContext, parentSlotKey.extrapolate(delayedMetricsStorageGranularity));
        }
    } else {
        locators = getLocators(executionContext);
    }

    return locators;
}

