/**
 * Converts a country name to its ISO 2-letter code.
 *
 * @param country The country name to convert.
 * @return The ISO 2-letter code of the country, or null if not found.
 */
public static String getCountryISO2(String country) {
    // Trim the input country name and check if it's null or has a length of 2
    country = StringUtils.trimToNull(country);
    if (country == null || country.length() == 2) {
        return country;
    }

    // Get all ISO 2-letter country codes
    String[] iso2Codes = Locale.getISOCountries();

    // If the input country name has a length of 3, try to convert it to ISO 2-letter code
    if (country.length() == 3) {
        String iso2Code = LocaleUtils.getCountryISO2FromISO3(country);
        if (iso2Code != null) {
            return iso2Code;
        }
    }

    // Iterate through all ISO 2-letter country codes
    for (String iso2Code : iso2Codes) {
        Locale countryLocale = new Locale(iso2Code, iso2Code);
        // Iterate through available locales to get the display country name
        for (Locale translationLocale : LocaleUtils.availableLocaleList()) {
            String name = StringUtils.trimToNull(countryLocale.getDisplayCountry(translationLocale));
            if (name != null && name.equalsIgnoreCase(country)) {
                return iso2Code;
            }
        }
    }

    // Return null if no ISO 2-letter code is found
    return null;
}

