    Vector<String> otherArgs = new Vector<>();
    int position = 0;
    this.values = new Hashtable<>(10);

    while (position < argv.length) {
        String curArg = argv[position];
        if (curArg.startsWith("-")) {
            if (curArg.equals("--")) {
                position += 1;
                break;
            }
            String valueArg = null;
            if (curArg.startsWith("--")) {
                int equalsPos = curArg.indexOf("=");
