    // Check if staticMethod is not null
    if (this.staticMethod != null) {
        // Validate the format of staticMethod
        int lastDotIndex = this.staticMethod.lastIndexOf(' ');
        if (lastDotIndex == -1 || lastDotIndex == this.staticMethod.length()) {
            throw new IllegalArgumentException("staticMethod must be a fully qualified class plus method name: e.g. 'example.MyExampleClass.myExampleMethod'");
        }
        // Extract class name and method name
        String className = this.staticMethod.substring(0, lastDotIndex);
        String methodName = this.staticMethod.substring(lastDotIndex + 1);
        // Resolve the class name
        this.targetClass = resolveClassName(className);
        // Set the method name
        this.targetMethod = methodName;
    }

    // Get the target class and method
    Class<?> targetClass = getTargetClass();
    String targetMethod = getTargetMethod();

    // Validate that either targetClass or targetObject is provided
    if (targetClass == null) {
        throw new IllegalArgumentException("Either 'targetClass' or 'targetObject' is required");
    }

    // Validate that targetMethod is provided
    if (targetMethod == null) {
        throw new IllegalArgumentException("Property 'targetMethod' is required");
    }

    // Get the arguments and their types
    Object[] arguments = getArguments();
    Class<?>[] argTypes = new Class<?>[arguments.length];
    for (int i = 0; i < arguments.length; ++i) {
        argTypes[i] = (arguments[i] != null ? arguments[i].getClass() : Object.class);
    }

    // Try to get the exact method first
    try {
        this.methodObject = targetClass.getMethod(targetMethod, argTypes);
    } catch (NoSuchMethodException ex) {
        // If no exact match, find a matching method
        this.methodObject = findMatchingMethod();
        if (this.methodObject == null) {
            throw ex;
        }
    }
}

