public static void writeKeyValuePairs(@Nullable final List<String> keys,
                                      @Nullable final List<Object> values,
                                      final JsonGenerator jsonGenerator,
                                      final ObjectMapper objectMapper,
                                      final StenoEncoder encoder) throws IOException {
    if (keys != null) {
        final int contextValuesLength = values == null ? 0 : values.size();
        for (int i = 0; i < keys.size(); ++i) {
            final String key = keys.get(i);
            if (i >= contextValuesLength) {
                jsonGenerator.writeObjectField(key, null);
            } else {
                final Object value = values.get(i);
                if (isSimpleType(value)) {
                    jsonGenerator.writeObjectField(key, value);
                } else {
                    jsonGenerator.writeFieldName(key);
                    objectMapper.writeValue(jsonGenerator, value);
                }
            }
        }
    }
}

