/**
 * Converts a Ptg array for a watch list by adjusting cell references based on the current row and shift formula reference.
 * 
 * @param ptgs The array of Ptg objects to be converted.
 * @param position The current position in the Ptg array.
 * @param shiftFormulaRef The ShiftFormulaRef object containing the current rows mapping list.
 * @param ptg The current Ptg object being processed.
 * @param originalOperandClass The original operand class of the Ptg.
 * @param currentRow The current row number.
 * @return The converted Ptg array.
 */
private static Ptg[] convertPtgForWatchList(final Ptg[] ptgs, final int position, final ShiftFormulaRef shiftFormulaRef, final Object ptg, final byte originalOperandClass, final int currentRow) {
    List<SerialRow> rowlist = getRowsList(currentRow, shiftFormulaRef.getCurrentRowsMappingList());
    if (rowlist == null || rowlist.isEmpty()) {
        // No need to change the ptg
        return singlePtg(ptg, originalOperandClass, -1);
    }
    shiftFormulaRef.setFormulaChanged(1); // One to one or has no round brackets
    if (rowlist.size() == 1 || (position + 1) >= ptgs.length || !(ptgs[position + 1] instanceof ParenthesisPtg)) {
        // Change ptg one to one
        return singlePtg(fixupRefRelativeRowOneToOne(ptg, rowlist.get(0).getRow()), originalOperandClass, -1);
    }
    shiftFormulaRef.setFormulaChanged(rowlist.size());
    return fixupRefRelativeRowOneToMany(ptg, originalOperandClass, rowlist, ptgs, position);
}

