/**
 * Finds an item in a collection at a specified index.
 * 
 * @param collection The collection to search.
 * @param index The index of the item to find.
 * @return The item at the specified index, or null if the index is out of bounds or the collection is empty.
 */
@SuppressWarnings("rawtypes")
public static Object findItemInCollection(final Collection collection, final int index) {
    if (index >= 0) {
        if (collection instanceof List) {
            List list = (List) collection;
            return list.get(index);
        }
        int i = 0;
        for (Object object : collection) {
            if (i == index) {
                return object;
            }
            i++;
        }
    }
    return null;
}

