/**
 * Sets the parent command for a given child command in a list of commands.
 * 
 * @param commandList The list of commands.
 * @param i The index of the child command in the list.
 * @param child The child command to set the parent for.
 */
private void setParentForChildCommand(final List<ConfigCommand> commandList, final int i, final ConfigCommand child) {
    int matchIndex = -1;
    ConfigRange matchRange = null;

    for (int j = 0; j < commandList.size(); j++) {
        if (j != i) {
            Command commandParent = commandList.get(j);
            if (!commandParent.getCommandTypeName().equalsIgnoreCase(TieConstants.COMMAND_FORM) &&
                WebSheetUtility.insideRange(child.getConfigRange(), commandParent.getConfigRange()) &&
                ((matchRange == null) || WebSheetUtility.insideRange(commandParent.getConfigRange(), matchRange))) {
                matchRange = commandParent.getConfigRange();
                matchIndex = j;
            }
        }
    }

    if (matchIndex >= 0) {
        commandList.get(matchIndex).getConfigRange().addCommand(child);
        child.setParentFound(true);
    }
}

