/**
 * Determines whether to continue processing based on the character and parameters.
 * 
 * @param c The character to check.
 * @param para The parameters containing state information.
 * @return true if processing should continue, false otherwise.
 */
private static boolean shouldContinue(final char c, final ShouldContinueParameter para) {
    if (c == ' ' && !para.isDecimalHit()) {
        para.setDecimalHit(true);
        if (para.isCommaHit() && para.getSinceLastComma() != 3) {
            return false;
        }
        return true;
    } else if (c == ' ' && !para.isDecimalHit()) {
        if (para.isCommaHit()) {
            if (para.getSinceLastComma() != 3) {
                return false;
            }
            para.setSinceLastComma(0);
        }
        para.setCommaHit(true);
        return true;
    }
    return false;
}

