@Override
public synchronized int read() throws IOException {
    // Use local refs to avoid invalidation by unsynchronized close()
    byte[] localBuf = buf;
    final InputStream localIn = in;

    if (localBuf == null || localIn == null) {
        throw new IOException("Stream is closed");
    }

    // Check if there are buffered bytes available
    if (pos >= count && fillbuf(localIn, localBuf) == -1) {
        return -1; // No more bytes available
    }

    // Ensure localBuf is up-to-date
    if (localBuf != buf) {
        localBuf = buf;
        if (localBuf == null) {
            throw new IOException("Stream is closed");
        }
    }

    // Return the next byte if available, otherwise return -1
    if (count - pos > 0) {
        return localBuf[pos++] & 0xFF;
    }
    return -1;
}

