@Override
public synchronized void reset() throws IOException {
    // Check if the buffer is null, if so, throw an IOException indicating the stream is closed.
    if (buf == null) {
        throw new IOException("Stream is closed");
    }
    // Check if the mark position is -1, if so, throw an IOException indicating the mark has been invalidated.
    if (-1 == markpos) {
