/**
 * Executes a function within an execution context and collects the results.
 * 
 * @param <T> The type of the elements in the resulting collection.
 * @param execution The execution context in which the function will be executed.
 * @param function The function to be executed.
 * @return A collection of results, or null if the result collection is empty.
 * @throws Exception If an error occurs during execution or if a NullPointerException is caught.
 */
@SuppressWarnings("unchecked")
public static <T> Collection<T> exeWithResults(Execution<?, ?, ?> execution, Function<?> function) throws Exception {
    ResultCollector<?, ?> resultCollector;
    try {
        resultCollector = execution.execute(function);
    } catch (FunctionException e) {
        if (e.getCause() instanceof NullPointerException) {
            throw new RuntimeException("Unable to execute function: " + function.getId() + 
                " assert hostnames(s) for locators and cache server can be resolved. " + 
                " If you do not have access to the host file, create host.properties and add to the CLASSPATH. " + 
                " Example: locahost=127.1.0.0 " + 
                " also assert that all cache servers have been initialized. Check if the server's cache.xml has all required <initializer>..</initializer> configurations", e);
        } else {
            throw e;
        }
    }
    Object resultsObject = resultCollector.getResult();
    Collection<Object> collectionResults = (Collection<Object>) resultsObject;
    if (collectionResults.isEmpty()) {
        return null;
    }
    Collection<Object> list = new ArrayList<>(collectionResults.size());
    flatten(collectionResults, list);
    if (list.isEmpty()) {
        return null;
    }
    return (Collection<T>) list;
}

