/**
 * Executes a query and returns the results as a Collection.
 * 
 * @param queryObj The query object to be executed.
 * @param rfc The region function context, or null if not applicable.
 * @param params Optional parameters for the query.
 * @return A Collection containing the results of the query, or null if no results are found.
 * @throws FunctionDomainException If the query domain is invalid.
 * @throws TypeMismatchException If there is a type mismatch in the query parameters.
 * @throws NameResolutionException If a name resolution error occurs.
 * @throws QueryInvocationTargetException If an exception is thrown during query execution.
 */
@SuppressWarnings("unchecked")
public static <ReturnType> Collection<ReturnType> query(Query queryObj, RegionFunctionContext rfc, Object... params) 
    throws FunctionDomainException, TypeMismatchException, NameResolutionException, QueryInvocationTargetException {

    SelectResults<ReturnType> selectResults;

    if (rfc == null || JvmRegionFunctionContext.class.isAssignableFrom(rfc.getClass())) {
        if (params == null || params.length == 0) {
            selectResults = (SelectResults<ReturnType>) queryObj.execute();
        } else {
            selectResults = (SelectResults<ReturnType>) queryObj.execute(params);
        }
    } else {
        if (params == null || params.length == 0) {
            selectResults = (SelectResults<ReturnType>) queryObj.execute(rfc);
        } else {
            selectResults = (SelectResults<ReturnType>) queryObj.execute(rfc, params);
        }
    }

    if (selectResults == null || selectResults.isEmpty()) {
        return null;
    }

    if (rfc == null || JvmRegionFunctionContext.class.isAssignableFrom(rfc.getClass())) {
        ArrayList<ReturnType> results = new ArrayList<>(selectResults.size());
        results.addAll(selectResults.asList());
        return results;
    } else {
        return selectResults;
    }
}

