public void constructComparison(Map<?, BigInteger> sourceChecksumMap, Map<?, BigInteger> targetMap) {
    if (sourceChecksumMap == null) {
        if (targetMap != null && !targetMap.isEmpty()) {
            keysRemovedFromSource.addAll(targetMap.keySet());
        }
        return;
    }
    if (targetMap == null) {
        keysMissingOnTarget.addAll(sourceChecksumMap.keySet());
        return;
    }

    BigInteger targetBi = null;
    BigInteger sourceBi = null;
    for (Map.Entry<?, BigInteger> entrySource : sourceChecksumMap.entrySet()) {
        targetBi = targetMap.get(entrySource.getKey());
        sourceBi = sourceChecksumMap.get(entrySource.getKey());
        if (targetBi == null) {
            keysMissingOnTarget.add(entrySource.getKey());
        } else if (!targetBi.equals(sourceBi)) {
            keysDifferentOnTarget.add(entrySource.getKey());
        }
    }

    // Determine keysRemovedFromSource
    Set<?> sourceKeySet = sourceChecksumMap.keySet();
    for (Map.Entry<?, ?> targetEntry : targetMap.entrySet()) {
        if (!sourceKeySet.contains(targetEntry.getKey())) {
            keysRemovedFromSource.add(targetEntry.getKey());
        }
    }
}


**Summary:**
The `constructComparison` method compares two maps, `sourceChecksumMap` and `targetMap`, to determine the differences between them. It populates three lists: `keysRemovedFromSource`, `keysMissingOnTarget`, and `keysDifferentOnTarget`. If `sourceChecksumMap` is null, it adds all keys from `targetMap` to `keysRemovedFromSource`. If `targetMap` is null, it adds all keys from `sourceChecksumMap` to `keysMissingOnTarget`. The method then iterates through `sourceChecksumMap` to find keys that are missing in `targetMap` and keys with different values in `targetMap`. Finally, it iterates through `targetMap` to find keys that are missing in `sourceChecksumMap`.

