/**
 * Checks for fields in a table object and processes them.
 * 
 * @param tableObject The table object to process.
 * @param columnElement The element representing the column.
 */
private void checkForFields(TableObject tableObject, Element columnElement) {
    Column columnAnnotation = columnElement.getAnnotation(Column.class);
    if (columnAnnotation == null) return;

    Element typeElement = typeUtils.asElement(columnElement.asType());
    String type = typeElement == null ? columnElement.asType().toString() : elementUtils.getBinaryName((TypeElement) typeElement).toString();

    TableColumn tableColumn = new TableColumn(columnElement, type, columnAnnotation.name());
    if (tableColumn.isBlob() && !tableColumn.isByteArray()) {
        String columnType = columnElement.asType().toString();
        logger.d("Column Element Type: " + columnType);
        if (!checkForSuperType(columnElement, Serializable.class) && !columnType.equals("java.lang.Byte[]") && !columnType.startsWith("java.util.Map") && !columnType.startsWith("java.util.List")) {
            logger.e(String.format("%s in %s is not Serializable and will not be able to be converted to a byte array", columnElement.toString(), tableObject.getTableName()));
        }
    } else if (tableColumn.isOneToMany()) {
        TypeMirror typeMirror = ((DeclaredType) columnElement.asType()).getTypeArguments().get(0);
        if (typeUtils.asElement(typeMirror).getAnnotation(Table.class) == null) {
            logger.e("One to many relationship in class %s where %s is not annotated with @Table", tableObject.getTableName(), tableColumn.getColumnName());
        }
        oneToManyCache.put(typeMirror.toString(), tableObject);
        TypeElement childColumnElement = elementUtils.getTypeElement(typeMirror.toString());
        tableColumn.setType(getClassName(childColumnElement, getPackageName(childColumnElement)));
    } else if (tableColumn.getSqlType() == SqliteType.UNKNOWN) {
        @SuppressWarnings("ConstantConditions")
        Table annotation = typeElement.getAnnotation(Table.class);
        if (annotation == null) {
            logger.e(String.format("%s in %s needs to be marked as a blob or should be annotated with @Table", columnElement.toString(), tableObject.getTableName()));
        }
        tableColumn.setOneToOne(true);
    }
    tableObject.addColumn(tableColumn);
}

