/**
 * Generates a SQL schema string for a table based on the columns and their properties.
 * 
 * @return A string representing the SQL schema.
 */
private String getSchema() {
    StringBuilder sb = new StringBuilder();
    Iterator<TableColumn> iterator = columns.iterator();
    while (iterator.hasNext()) {
        TableColumn column = iterator.next();
        if (column.isOneToMany()) {
            if (!iterator.hasNext()) {
                // Remove the extra ", " after one to many
                int length = sb.length();
                sb.replace(length - 2, length, "");
            }
            continue;
        }
        sb.append(column);
        if (iterator.hasNext()) {
            sb.append(", ");
        }
    }
    // Writes out id_missing for logging, the actual idMissing check happens by the annotation processor.
    String idCol = idColumn == null ? "id_missing" : idColumn.getColumnName();
    return String.format(CREATE_TABLE_DEFAULT, getTableName(), idCol, sb.toString());
}

