/**
 * Computes the natural logarithm of a given BigDecimal number with a specified scale.
 * 
 * @param x The input BigDecimal number, must be greater than 0.
 * @param scale The number of decimal places in the result.
 * @return The natural logarithm of the input number, rounded to the specified scale.
 * @throws IllegalArgumentException if x is less than or equal to 0.
 */
public static BigDecimal ln(@Nonnull final BigDecimal x, final int scale) {
    // Check that x > 0
    if (x.signum() <= 0) {
        throw new IllegalArgumentException("x <= 0: " + x);
    }

    // The number of digits to the left of the decimal point
    final int magnitude = x.toString().length() - x.scale() - 1;

    // If magnitude is less than 3, use Newton's method directly
    if (magnitude < 3) {
        return _lnNewton(x, scale);
    }

    // Compute magnitude * ln(x^(1/magnitude))
    // x^(1/magnitude)
    final BigDecimal root = intRoot(x, magnitude, scale);
    // ln(x^(1/magnitude))
    final BigDecimal lnRoot = _lnNewton(root, scale);
    // magnitude * ln(x^(1/magnitude))
    return BigDecimal.valueOf(magnitude).multiply(lnRoot).setScale(scale, RoundingMode.HALF_EVEN);
}

