/**
 * Calculates the natural logarithm of a given BigDecimal number using the Newton-Raphson method.
 *
 * @param px The input BigDecimal number for which the natural logarithm is to be calculated.
 * @param scale The number of decimal places to which the result should be rounded.
 * @return The natural logarithm of the input number rounded to the specified scale.
 */
private static BigDecimal _lnNewton(@Nonnull final BigDecimal px, final int scale) {
    BigDecimal x = px;
    final int sp1 = scale + 1;
    final BigDecimal n = x;
    BigDecimal term;

    // Convergence tolerance = 5*(10^-(scale+1))
    final BigDecimal tolerance = BigDecimal.valueOf(5).movePointLeft(sp1);

    // Loop until the approximations converge
    do {
        // e^x
        final BigDecimal eToX = exp(x, sp1);
        // (e^x - n)/e^x
        term = eToX.subtract(n).divide(eToX, sp1, RoundingMode.DOWN);
        // x - (e^x - n)/e^x
        x = x.subtract(term);
        Thread.yield();
    } while (term.compareTo(tolerance) > 0);

    return x.setScale(scale, RoundingMode.HALF_EVEN);
}

