/**
 * Calculates the arctangent of a given BigDecimal value using the Taylor series method.
 *
 * @param x     the input value for which the arctangent is to be calculated
 * @param scale the number of decimal places to which the result should be rounded
 * @return the arctangent of the input value as a BigDecimal
 * @throws IllegalArgumentException if the absolute value of x is greater than or equal to 1
 */
public static BigDecimal arctan(@Nonnull final BigDecimal x, final int scale) {
    // Check that |x| < 1
    if (x.abs().compareTo(BigDecimal.ONE) >= 0) {
        throw new IllegalArgumentException("|x| >= 1: " + x);
    }
    // If x is negative, return -arctan(-x)
    if (x.signum() == -1) {
        return arctan(x.negate(), scale).negate();
    }
    // Calculate arctan using the Taylor series method
    return _arctanTaylor(x, scale);
}

