/**
 * Evaluates an attribute filter expression against an event attribute.
 *
 * @param attributeDefinitionUuid The UUID of the attribute definition.
 * @param attributeFilter The attribute filter expression to evaluate.
 * @param eventAttributes A map of event attributes.
 * @param attributeDefinitions A list of attribute definitions.
 * @return true if the filter evaluates to true, false otherwise.
 * @throws ParseException if there is an error parsing the attribute value.
 */
protected boolean evaluate(final UUID attributeDefinitionUuid, final AttributeFilterExpression attributeFilter, final Map<UUID, String> eventAttributes, final List<AttributeDefinition> attributeDefinitions) throws ParseException {
    if (LOG.isTraceEnabled()) {
        LOG.entry(attributeDefinitionUuid, attributeFilter, eventAttributes, attributeDefinitions);
    }

    // Retrieve the attribute value from the event attributes
    String attributeValue = eventAttributes.get(attributeDefinitionUuid);
    if (attributeValue == null) {
        if (LOG.isTraceEnabled()) {
            LOG.trace("An attributeValue was not specified for this attribute definition.");
        }
        LOG.exit(false);
        return false;
    }

    // Find the matching attribute definition
    AttributeDefinition attributeDefinition = getApplicableAttributeDefinition(attributeDefinitionUuid, attributeDefinitions);
    if (attributeDefinition == null) {
        if (LOG.isTraceEnabled()) {
            LOG.trace("The attributeDefinition did not exist.");
        }
        LOG.exit(false);
        return false;
    }

    // Get the unit from the attribute definition
    Unit unit = attributeDefinition.getUnits();

    try {
        // Evaluate the attribute filter expression
        boolean result = unit.evaluate(attributeFilter.getOperator(), attributeValue, attributeFilter.getOperand());
        if (LOG.isTraceEnabled()) {
            LOG.exit(result);
        }
        return result;
    } catch (ParseException e) {
        if (LOG.isTraceEnabled()) {
            LOG.throwing(e);
        }
        throw e;
    }
}

