/**
 * Sets the class loader for the current thread to load classes from a specified JAR file.
 * 
 * @param jarPath The path to the JAR file.
 * @throws ParsingException If the provided path does not represent a JAR file or if the JAR file is invalid.
 */
private void setClassLoader(String jarPath) {
    if (!jarPath.endsWith(".jar")) {
        throw new ParsingException("The jarPath received doesn't represent a jar file.");
    }

    ClassLoader originalCl = Thread.currentThread().getContextClassLoader();
    URL url = originalCl.getResource(jarPath);
    if (url == null) {
        try {
            url = new URL("file:/" + jarPath);
        } catch (MalformedURLException e) {
            throw new ParsingException("Invalid jar name.");
        }
    }

    // Create a new URLClassLoader with the specified JAR file and the original class loader as the parent
    ClassLoader urlCl = URLClassLoader.newInstance(new URL[]{url}, originalCl);
    Thread.currentThread().setContextClassLoader(urlCl);
    classLoader = urlCl;
}

