 * 
 * @param ruleEntity The rule entity containing the whitelist rules.
 * @param violationEntity The violation entity to be evaluated.
 * @return true if the violation entity matches any of the whitelist rules, false otherwise.
 */
@Override
public Boolean apply(final RuleEntity ruleEntity, final ViolationEntity violationEntity) {
    List<Predicate<ViolationEntity>> predicates = new ArrayList<>();

    // Add predicates based on non-empty rule entity fields
    trimOptional(ruleEntity.getAccountId()).map(WhitelistRulesEvaluator::accountIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getRegion()).map(WhitelistRulesEvaluator::regionIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getViolationTypeEntityId()).map(WhitelistRulesEvaluator::violationTypeIdIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getImageName()).map(WhitelistRulesEvaluator::imageNameMatches).ifPresent(predicates::add);
    trimOptional(ruleEntity.getImageOwner()).map(WhitelistRulesEvaluator::imageOwnerIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getApplicationId()).map(WhitelistRulesEvaluator::applicationIdIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getApplicationVersion()).map(WhitelistRulesEvaluator::applicationVersionIsEqual).ifPresent(predicates::add);
    trimOptional(ruleEntity.getMetaInfoJsonPath()).map(this::metaInfoJsonPathExists).ifPresent(predicates::add);

    // Combine all predicates using logical AND
    Optional<Predicate<ViolationEntity>> whiteListTest = predicates.stream().reduce(Predicate::and);

    // Return true if there are any predicates and they all match the violation entity
    return whiteListTest.isPresent() && whiteListTest.get().test(violationEntity);
}

