/**
 * Removes a node from the queue at the specified index.
 * 
 * @param index The index of the node to remove.
 * @return The removed node.
 * 
 * @pre index > 0
 * @pre index <= size
 * @post res != null
 * @post res.index == index
 * @post size is decremented if the removed node was not the last node
 * @post if the removed node was not the last node, it is swapped with the last node
 * @post if the removed node was not the last node and the queue is not empty, it is normalized up
 * @post if the removed node was not the last node and the queue is not empty and the node moved up, it should not move down
 */
private TimeoutExtImpl removeNode(int index) {
    TimeoutExtImpl res = queue[index];
    if (index == size) {
        --size;
        queue[index] = null;
        return res;
    }
    swap(index, size);
    --size;
    if (normalizeUp(index)) {
        return res;
    }
    long t = queue[index].time;
    int c = index << 1;
    while (c <= size) {
        TimeoutExtImpl l = queue[c];
        if (c + 1 <= size) {
            TimeoutExtImpl r = queue[c + 1];
            if (l.time <= r.time) {
                if (t <= l.time) {
                    break;
                }
                swap(index, c);
                index = c;
            } else {
                if (t <= r.time) {
                    break;
                }
                swap(index, c + 1);
                index = c + 1;
            }
        } else {
            if (t <= l.time) {
                break;
            }
            swap(index, c);
            index = c;
        }
        c = index << 1;
    }
    return res;
}

