/**
 * Reads the next token from the input file, skipping over whitespace and comments.
 * @return The next token as a String, or null if the end of the file is reached.
 * @throws IOException If an I/O error occurs.
 */
protected String nextToken() throws IOException {
    String token = "";
    int ch, nextch;

    if (!tokenStack.empty()) {
        return (String) tokenStack.pop();
    }

    // Skip over leading whitespace and comments
    while (true) {
        ch = catfile.read();
        while (ch <= ' ') {
            ch = catfile.read();
            if (ch < 0) {
                return null;
            }
        }
        nextch = catfile.read();
        if (nextch < 0) {
            return null;
        }
        if (ch == ' ' && nextch == ' ') {
            // Skip comment
            ch = ' ';
            nextch = nextChar();
            while (ch != ' ' || nextch != ' ') {
                ch = nextch;
                nextch = nextChar();
            }
        } else {
            stack[++top] = nextch;
            stack[++top] = ch;
            break;
        }
    }

    ch = nextChar();
    if (ch == ' ' || ch == ' ') {
        int quote = ch;
        while ((ch = nextChar()) != quote) {
            char[] chararr = new char[1];
            chararr[0] = (char) ch;
            String s = new String(chararr);
            token = token.concat(s);
        }
        return token;
    } else {
        // Return the next whitespace or comment delimited string
        while (ch > ' ') {
            nextch = nextChar();
            if (ch == ' ' && nextch == ' ') {
                stack[++top] = ch;
                stack[++top] = nextch;
                return token;
            } else {
                char[] chararr = new char[1];
                chararr[0] = (char) ch;
                String s = new String(chararr);
                token = token.concat(s);
                ch = nextch;
            }
        }
        return token;
    }
}

