public static void forceLoad(final Class type) {
    if (type == null) throw new NullArgumentException("type"); // Check if the type is null and throw an exception if it is.
    if (type.isPrimitive()) return; // Do not attempt to force load primitive types.
    String packageName = Classes.getPackageName(type); // Get the package name of the class.
    if (packageName.startsWith("java.") || packageName.startsWith("javax.")) return; // Do not attempt to force load classes in the java.* or javax.* packages.
    try {
        Method[] methods = type.getDeclaredMethods(); // Get all declared methods of the class.
        Method method = null;
        for (int i = 0; i < methods.length; i++) {
            int modifiers = methods[i].getModifiers();
            if (Modifier.isStatic(modifiers)) { // Find the first static method.
                method = methods[i];
                break;
            }
        }
        if (method != null) {
            method.invoke(null, (Object[]) null); // Invoke the static method if found.
        } else {
            type.newInstance(); // Create a new instance of the class if no static method is found.
        }
    } catch (Exception ignore) {
        ThrowableHandler.add(ignore); // Handle any exceptions that occur during the process.
