/**
 * Recursively adds files and directories to a JAR file.
 *
 * @param src The source file or directory to be added.
 * @param prefix The prefix for the entry in the JAR file.
 * @param info The JAR information containing the output stream and buffer.
 * @throws IOException If an I/O error occurs.
 */
private static void jar(File src, String prefix, JarInfo info) throws IOException {
    JarOutputStream jout = info.out;
    if (src.isDirectory()) {
        // Create and initialize the zip entry for the directory
        prefix = prefix + src.getName() + "/";
        ZipEntry entry = new ZipEntry(prefix);
        entry.setTime(src.lastModified());
        entry.setMethod(JarOutputStream.STORED);
        entry.setSize(0L);
        entry.setCrc(0L);
        jout.putNextEntry(entry);
        jout.closeEntry();

        // Process sub-directories
        File[] files = src.listFiles(info.filter);
        for (int i = 0; i < files.length; i++) {
            jar(files[i], prefix, info);
        }
    } else if (src.isFile()) {
        // Get the required info objects
        byte[] buffer = info.buffer;

        // Create and initialize the zip entry for the file
        ZipEntry entry = new ZipEntry(prefix + src.getName());
        entry.setTime(src.lastModified());
        jout.putNextEntry(entry);

        // Dump the file
        FileInputStream in = new FileInputStream(src);
        int len;
        while ((len = in.read(buffer, 0, buffer.length)) != -1) {
            jout.write(buffer, 0, len);
        }
        in.close();
        jout.closeEntry();
    }
}

