 * Sets the plan variables for a given agent and plan instance based on the selected belief.
 * 
 * @param agent The agent for which the plan variables are being set.
 * @param planInstance The plan instance to which the variables will be applied.
 * @param results A set of beliefs from which to select the belief.
 * @param choice The index of the belief to select from the results set.
 */
private final void setPlanVariables(Agent agent, Plan planInstance, Set<Belief> results, int choice) {
    if (agent == null || planInstance == null) {
        return;
    }
    Belief belief = getResultAtIndex(results, choice);
    if (belief == null) {
        return;
    }
    Object[] tuple = belief.getTuple();
    if (tuple == null) {
        return;
    }
    int index = 0;
    HashMap<String, Object> vars = new HashMap<>();
    for (Object o : belief.getTuple()) {
        try {
            String fieldname = ABeliefStore.getFieldName(agent.getId(), belief.getBeliefset(), index);
            vars.put(fieldname, o);
        } catch (BeliefBaseException e) {
            Log.error("Agent " + agent.getId() + " could not retrieve belief set field: " + e.getMessage());
        }
        index++;
    }
    planInstance.setPlanVariables(vars);
}

