/**
 * Retrieves the belief at the specified index from the given set of beliefs.
 *
 * @param results The set of beliefs to search.
 * @param index   The index of the belief to retrieve.
 * @return The belief at the specified index, or null if the index is out of bounds or the set is null.
 */
private Belief getResultAtIndex(Set<Belief> results, int index) {
    if (results == null || index < 0 || index >= results.size()) {
        return null;
    }
    int idx = 0;
    for (Belief b : results) {
        if (idx == index) {
            return b;
        }
        idx++;
    }
    return null;
}

