/**
 * Retrieves the target file for a given artifact and filename, ensuring the directory structure exists and the file can be generated.
 * 
 * @param artifactName The name of the artifact.
 * @param filename The name of the file.
 * @param logInfo Log information for the file.
 * @return A GeneratedFile object representing the target file.
 * @throws IllegalStateException If the directory does not exist and creation is not allowed.
 */
protected final GeneratedFile getTargetFile(final String artifactName, final String filename, final String logInfo) {
    // Find the target folder for the artifact
    Folder folder = getGeneratorConfig().findTargetFolder(artifactName);
    // Get the canonical directory of the folder
    File dir = folder.getCanonicalDir();
    // Create the file object
    File file = new File(dir, filename);

    // Ensure the directory exists
    if (!dir.exists()) {
        if (folder.isCreate()) {
            dir.mkdirs();
        } else {
            throw new IllegalStateException("Directory '" + dir + "' does not exist, but configuration does not allow creation: " + "<folder name=\"" + folder.getName() + "\" create=\"false\" ... />");
        }
    }

    // Ensure the parent directory for the file exists
    if (!file.getParentFile().exists()) {
        file.getParentFile().mkdirs();
    }

    // Check if the file exists and if overriding is allowed
    if (file.exists() && !folder.overrideAllowed(file)) {
        // Skip file because override is not allowed
        return new GeneratedFile(file, logInfo, true);
    }

    // Return the GeneratedFile object
    return new GeneratedFile(file, logInfo);
}

