/**
 * Executes a mutable transaction for a given managed method.
 * 
 * <p>This method performs the following steps:
 * <ol>
 *   <li>Creates a transaction using the provided transactional resource.</li>
 *   <li>Stores the transaction session on the current thread.</li>
 *   <li>Invokes the managed method with the provided arguments.</li>
 *   <li>Commits the transaction if the method invocation is successful.</li>
 *   <li>Logs a debug message if the method is superfluously declared transactional.</li>
 *   <li>Rollbacks the transaction and rethrows any exceptions if the method invocation fails.</li>
 *   <li>Releases the transaction session from the current thread if the transaction is closed.</li>
 * </ol>
 * 
 * @param managedMethod The managed method to be executed within the transaction.
 * @param args The arguments to be passed to the managed method.
 * @return The result of the managed method invocation.
 * @throws Throwable If an exception occurs during the method invocation or transaction management.
 */
private Object executeMutableTransaction(ManagedMethodSPI managedMethod, Object[] args) throws Throwable {
    Transaction transaction = transactionalResource.createTransaction();
    transactionalResource.storeSession(transaction.getSession());
    try {
        Object result = managedMethod.invoke(managedInstance, args);
        transaction.commit();
        if (transaction.unused()) {
            log.debug("Method |%s| superfluously declared transactional.", managedMethod);
        }
        return result;
    } catch (Throwable throwable) {
        transaction.rollback();
        throw throwable(throwable, "Mutable transactional method |%s| invocation fail.", managedMethod);
    } finally {
        if (transaction.close()) {
            transactionalResource.releaseSession();
        }
    }
}

