/**
 * Executes an immutable transaction for a given managed method.
 *
 * @param managedMethod The managed method to execute within the transaction.
 * @param args The arguments to pass to the managed method.
 * @return The result of the managed method execution.
 * @throws Throwable If an error occurs during the transaction execution.
 */
private Object executeImmutableTransaction(ManagedMethodSPI managedMethod, Object[] args) throws Throwable {
    Transaction transaction = transactionalResource.createReadOnlyTransaction(); // Create a read-only transaction
    transactionalResource.storeSession(transaction.getSession()); // Store the session in the transaction

    try {
        Object result = managedMethod.invoke(managedInstance, args); // Invoke the managed method
        if (transaction.unused()) {
            log.debug("Method |%s| superfluously declared transactional.", managedMethod); // Log if the method was declared transactional unnecessarily
        }
        return result; // Return the result of the method invocation
    } catch (Throwable throwable) {
        throw throwable(throwable, "Immutable transactional method |%s| invocation fail.", managedMethod); // Handle any exceptions thrown during the method invocation
    } finally {
        if (transaction.close()) {
            transactionalResource.releaseSession(); // Release the session after closing the transaction
        }
    }
}

