/**
 * Frees the buffer by unmapping it if the UNMAP_SUPPORTED flag is true.
 * If the buffer is null, the method returns immediately.
 * If unmapping is supported, it uses reflection to access the cleaner method
 * of the buffer and invokes the clean method to free the buffer.
 * If an exception occurs during unmapping, it throws an IOException with the cause.
 *
 * @param buffer the ByteBuffer to be freed
 * @throws IOException if unmapping fails
 */
protected void freeBuffer(final ByteBuffer buffer) throws IOException {
    if (buffer == null) {
        return;
    }
    if (UNMAP_SUPPORTED) {
        try {
            AccessController.doPrivileged(new PrivilegedExceptionAction<Void>() {
                @Override
                public Void run() throws Exception {
                    final Method getCleanerMethod = buffer.getClass().getMethod("cleaner");
                    getCleanerMethod.setAccessible(true);
                    final Object cleaner = getCleanerMethod.invoke(buffer);
                    if (cleaner != null) {
                        cleaner.getClass().getMethod("clean").invoke(cleaner);
                    }
                    return null;
                }
            });
        } catch (PrivilegedActionException e) {
            final IOException ioe = new IOException("unable to unmap the mapped buffer");
            ioe.initCause(e.getCause());
            throw ioe;
        }
    }
}

