public void return_(final Integer request_type, final String name, final String pattern, final byte[] response_info, final byte[] response, final Integer timeout, final byte[] trans_id, final OtpErlangPid pid) throws ReturnAsyncException, ReturnSyncException, InvalidInputException {
    if (request_type == API.ASYNC) {
        return_async(name, pattern, response_info, response, timeout, trans_id, pid);
