/**
 * Sends a synchronous return message to a specified Erlang process.
 *
 * @param name       The name of the process.
 * @param pattern    The pattern for the return message.
 * @param response_info Additional information about the response.
 * @param response   The actual response data.
 * @param timeout    The timeout for the return message.
 * @param trans_id   The transaction ID for the return message.
 * @param pid        The PID of the Erlang process to send the message to.
 * @throws ReturnSyncException If an error occurs during the message sending process.
 */
public void return_sync(final String name, final String pattern, byte[] response_info, byte[] response, Integer timeout, final byte[] trans_id, final OtpErlangPid pid) throws ReturnSyncException {
    try {
        OtpOutputStream return_sync = new OtpOutputStream();
        return_sync.write(OtpExternal.versionTag);
        final OtpErlangObject[] tuple = {
            new OtpErlangAtom("return_sync"),
            new OtpErlangString(name),
            new OtpErlangString(pattern),
            new OtpErlangBinary(response_info),
            new OtpErlangBinary(response),
            new OtpErlangUInt(timeout),
            new OtpErlangBinary(trans_id),
            pid
        };
        return_sync.write_any(new OtpErlangTuple(tuple));
        send(return_sync);
    } catch (OtpErlangRangeException e) {
        e.printStackTrace(API.err);
        return;
    }
    throw new ReturnSyncException();
}

