/**
 * Deregisters a worker thread and handles any associated tasks.
 * 
 * @param wt The worker thread to deregister.
 * @param ex The exception, if any, that caused the worker to terminate.
 */
final void deregisterWorker(ForkJoinWorkerThread wt, Throwable ex) {
    WorkQueue w = null;
    if (wt != null && (w = wt.workQueue) != null) {
        WorkQueue[] ws;
        int idx = w.config & SMASK;
        int rs = lockRunState();
        if ((ws = workQueues) != null && ws.length > idx && ws[idx] == w) {
            ws[idx] = null;
        }
        unlockRunState(rs, rs & ~RSLOCK);
    }

    long c;
    do {
    } while (!U.compareAndSwapLong(this, CTL, c = ctl, ((AC_MASK & (c - AC_UNIT)) | (TC_MASK & (c - TC_UNIT)) | (SP_MASK & c))));

    if (w != null) {
        w.qlock = -1; // Ensure set
        w.transferStealCount(this);
        w.cancelAll(); // Cancel remaining tasks
    }

    for (;;) {
        WorkQueue[] ws;
        int m, sp;
        if (tryTerminate(false, false) || w == null || w.array == null || (runState & STOP) != 0 || (ws = workQueues) == null || (m = ws.length - 1) < 0) // already terminating
            break;
        if ((sp = (int)(c = ctl)) != 0) { // Wake up replacement
            if (tryRelease(c, ws[sp & m], AC_UNIT))
                break;
        } else if (ex != null && (c & ADD_WORKER) != 0L) {
            tryAddWorker(c); // Create replacement
            break;
        } else // Don't need replacement
            break;
    }

    if (ex == null)
        ForkJoinTask.helpExpungeStaleExceptions(); // Help clean on way out
    else
        ForkJoinTask.rethrow(ex); // Rethrow
}

