/**
 * Signals workers to work on a set of work queues.
 *
 * @param ws Array of work queues.
 * @param q  Work queue.
 */
final void signalWork(WorkQueue[] ws, WorkQueue q) {
    long c;
    int sp, i;
    WorkQueue v;
    Thread p;
    while ((c = ctl) < 0L) { // Check if there are too few active workers
        if ((sp = (int)c) == 0) { // Check if there are no idle workers
            if ((c & ADD_WORKER) != 0L) // Check if there are too few workers
                tryAddWorker(c);
            break;
        }
        if (ws == null) // Check if the work queues are unstarted or terminated
            break;
        if (ws.length <= (i = sp & SMASK)) // Check if the work queue index is out of bounds
            break;
        if ((v = ws[i]) == null) // Check if the work queue at the index is null
            break;
        int vs = (sp + SS_SEQ) & ~INACTIVE; // Calculate the next scan state
        int d = sp - v.scanState; // Calculate the difference between current and previous scan states
        long nc = (UC_MASK & (c + AC_UNIT)) | (SP_MASK & v.stackPred); // Calculate the new control value
        if (d == 0 && U.compareAndSwapLong(this, CTL, c, nc)) { // Atomically update the control value
            v.scanState = vs; // Set the new scan state
            if ((p = v.parker) != null) U.unpark(p); // Unpark the worker thread
            break;
        }
        if (q != null && q.base == q.top) // Check if there is no more work in the queue
            break;
    }
}

