/**
 * Retrieves the statistics of the thread pool.
 *
 * @return An instance of {@link AThreadPoolStatistics} containing the statistics of worker threads and shared queues.
 */
@Override
public AThreadPoolStatistics getStatistics() {
    // Initialize an array to hold statistics of worker threads
    AWorkerThreadStatistics[] workerStats = new AWorkerThreadStatistics[localQueues.length];
    // Iterate over each local queue to get the statistics of the worker thread
    for (int i = 0; i < localQueues.length; i++) {
        workerStats[i] = localQueues[i].thread.getStatistics();
    }

    // Initialize an array to hold statistics of shared queues
    ASharedQueueStatistics[] sharedQueueStats = new ASharedQueueStatistics[sharedQueues.length];
    // Iterate over each shared queue to get the approximate size
    for (int i = 0; i < sharedQueues.length; i++) {
        sharedQueueStats[i] = new ASharedQueueStatistics(sharedQueues[i].approximateSize());
    }

    // Return a new instance of AThreadPoolStatistics containing the collected statistics
    return new AThreadPoolStatistics(workerStats, sharedQueueStats);
}

