/**
 * Applies a function to each element of an iterable, accumulating the result.
 *
 * @param <T>      the type of elements in the iterable
 * @param <R>      the type of the result
 * @param <E>      the type of exception that may be thrown by the function
 * @param coll     the iterable to process
 * @param startValue the initial value for the accumulator
 * @param f        the function to apply to each element
 * @return the accumulated result
 * @throws E if the function throws an exception
 */
public static <T, R, E extends Throwable> R foldLeft(Iterable<T> coll, R startValue, AFunction2<R, ? super T, R, E> f) throws E {
    R result = startValue;
    for (T e : coll) {
        result = f.apply(result, e);
    }
    return result;
}

