/**
 * Applies a function from right to left to a list, accumulating the result.
 *
 * @param <T>      the type of elements in the list
 * @param <R>      the type of the result
 * @param <E>      the type of exception that may be thrown by the function
 * @param coll     the list to fold
 * @param startValue the initial value for the accumulator
 * @param f        the function to apply
 * @return the accumulated result
 * @throws E if the function throws an exception
 */
public static <T, R, E extends Throwable> R foldRight(List<T> coll, R startValue, AFunction2<R, ? super T, R, E> f) throws E {
    R result = startValue;
    ListIterator<T> i = coll.listIterator(coll.size());
    while (i.hasPrevious()) {
        result = f.apply(result, i.previous());
    }
    return result;
}

