/**
 * Determines the charset of a file based on its first two bytes.
 * 
 * @param file The file to check.
 * @return An Optional containing the detected charset, or Optional.absent() if the file does not exist or an error occurs.
 */
public static Optional<Charset> charset(File file) {
    if (!file.exists()) {
        logger.error("The file [{}] is not exist.", file.getAbsolutePath());
        return Optional.absent();
    }

    FileInputStream fileInputStream = null;
    BufferedInputStream bin = null;
    try {
        fileInputStream = new FileInputStream(file);
        bin = new BufferedInputStream(fileInputStream);
        int p = (bin.read() << 8) + bin.read();
        Optional<Charset> charset;
        switch (p) {
            case 0xefbb: charset = Optional.of(Charsets.UTF_8); break;
            case 0xfffe: charset = Optional.of(Charset.forName("Unicode")); break;
            case 0xfeff: charset = Optional.of(Charsets.UTF_16BE); break;
            case 0x5c75: charset = Optional.of(Charsets.US_ASCII); break;
            default: charset = Optional.of(Charset.forName("GBK"));
        }
        return charset;
    } catch (FileNotFoundException e) {
        logger.error("The file [{}] is not exist.", file.getAbsolutePath(), e);
    } catch (IOException e) {
        logger.error("Read file has error, {}.", file.getAbsolutePath(), e);
    } finally {
        IOUtils.closeQuietly(fileInputStream);
        IOUtils.closeQuietly(bin);
    }
    return Optional.absent();
}

