/**
 * Returns the next solution in the sequence, if available.
 * If the next solution has already been cached, it is returned immediately.
 * Otherwise, the next solution is generated using the `nextInSequence` method.
 * If the generated solution is null, it indicates that the search space is exhausted, and the `exhausted` flag is set to true.
 * @return The next solution in the sequence, or null if the search space is exhausted.
 */
private E nextInternal() {
    if (nextSolution != null) {
        return nextSolution;
    }
    nextSolution = nextInSequence();
    if (nextSolution == null) {
        exhausted = true;
    }
    return nextSolution;
}

