public SearchNode search(QueueSearchState<O, T> initSearch, Collection<T> startStates, int maxSteps, int searchSteps) throws SearchNotExhaustiveException {
    // Initialize the queue with start states and get the goal predicate.
    Queue<SearchNode<O, T>> queue = initSearch.enqueueStartStates(startStates);
    UnaryPredicate<T> goalPredicate = initSearch.getGoalPredicate();

    // Continue searching until the queue is empty or a goal state is found.
    while (!queue.isEmpty()) {
        // Extract the head node from the queue.
        SearchNode<O, T> headNode = peekAtHead ? queue.peek() : queue.remove();

        // Expand successors if the node has not been expanded yet.
        if (!headNode.isExpanded()) {
            headNode.expandSuccessors(queue, reverseEnqueue);
        }

        // Get the node to be goal checked.
        SearchNode<O, T> currentNode = peekAtHead ? queue.peek() : headNode;

        // Goal check if the node is expanded.
        if (currentNode.isExpanded()) {
            currentNode = peekAtHead ? queue.remove() : headNode;
            if (goalPredicate.evaluate(currentNode.getState())) {
                return currentNode;
            }
        }

        // Check if the maximum number of steps limit is reached.
        if (maxSteps > 0) {
            searchSteps++;
            initSearch.setStepsTaken(searchSteps);
            if (searchSteps >= maxSteps) {
                if (queue.isEmpty()) {
                    return null;
                } else {
                    throw new SearchNotExhaustiveException("Maximum number of steps reached.", null);
                }
            }
        }
    }

    // No goal state found.
    return null;
}

