            break;
        case FLOATING_POINT_LITERAL:
            term = doubleLiteral();
            break;
        case STRING_LITERAL:
            term = stringLiteral();
            break;
        case ATOM:
            term = atom();
            break;
        case LPAREN:
            consumeToken(LPAREN);
            term = term();
            term.setBracketed(true);
            consumeToken(RPAREN);
            break;
