/**
 * Peeks at the next directive and consumes it if it matches any of the predefined directives.
 * 
 * @return The consumed directive if a match is found, otherwise null.
 * @throws SourceCodeException If an error occurs during the peek and consume operation.
 */
public Directive peekAndConsumeDirective() throws SourceCodeException {
    if (peekAndConsumeTrace()) {
        return Directive.Trace;
    }
    if (peekAndConsumeInfo()) {
        return Directive.Info;
    }
    if (peekAndConsumeUser()) {
        return Directive.User;
    }
    return null;
