/**
 * Consumes the next token from the token source if it matches the specified kind.
 * If the token does not match, throws a SourceCodeException.
 *
 * @param kind The kind of token to consume.
 * @return The consumed token if it matches the specified kind.
 * @throws SourceCodeException If the token does not match the specified kind.
 */
protected Token consumeToken(int kind) throws SourceCodeException {
    Token nextToken = tokenSource.peek();
    if (nextToken.kind != kind) {
        throw new SourceCodeException(
            "Was expecting " + tokenImage[kind] + " but got " + tokenImage[nextToken.kind] + ".",
            null, null, null,
            new SourceCodePositionImpl(nextToken.beginLine, nextToken.beginColumn, nextToken.endLine, nextToken.endColumn)
        );
    } else {
        nextToken = tokenSource.poll();
        return nextToken;
    }
}

