/**
 * Calculates the number of milliseconds from the start of the given year to the Unix epoch (January 1, 1970).
 * 
 * @param year The year for which to calculate the milliseconds.
 * @return The number of milliseconds from the start of the given year to the Unix epoch.
 */
public static long millisToYearStart(int year) {
    // Calculate the number of leap years elapsed prior to the year in question.
    int leapYears = year / 100;
    if (year < 0) {
        leapYears = ((year + 3) >> 2) - leapYears + ((leapYears + 3) >> 2) - 1;
    } else {
        leapYears = (year >> 2) - leapYears + (leapYears >> 2);
        if (isLeapYear(year)) {
            leapYears--;
        }
    }
    // Calculate the number of milliseconds from the start of the given year to the Unix epoch.
    return ((year * 365L) + leapYears - DAYS_TO_1970) * MILLIS_PER_DAY;
}

