public SearchNode search(QueueSearchState<O, T> initSearch, Collection<T> startStates, int maxSteps, int searchSteps) throws SearchNotExhaustiveException {
    // Initialize the queue with start states and get the goal predicate.
    Queue<SearchNode<O, T>> queue = initSearch.enqueueStartStates(startStates);
    UnaryPredicate<T> goalPredicate = initSearch.getGoalPredicate();

    // Flags and variables for tracking beyond-fringe states and their bounds.
    boolean beyondFringe = false;
    float minBeyondBound = Float.POSITIVE_INFINITY;

    // Continue searching until the queue is empty or a goal state is found.
    while (!queue.isEmpty()) {
        // Extract the head node from the queue.
        SearchNode<O, T> headNode = peekAtHead ? queue.peek() : queue.remove();

        // Expand successors and add them to the queue if they are within the max bound.
        Queue<SearchNode<O, T>> successors = new LinkedList<>();
        headNode.expandSuccessors(successors, reverseEnqueue);
        for (SearchNode<O, T> successor : successors) {
            float boundProperty = boundPropertyExtractor.getBoundProperty(successor);
            if (boundProperty <= maxBound) {
                queue.offer(successor);
            } else {
                beyondFringe = true;
                minBeyondBound = Math.min(boundProperty, minBeyondBound);
            }
        }

        // Check if the current node is a goal state.
        SearchNode<O, T> currentNode = peekAtHead ? queue.remove() : headNode;
        if (currentNode.isExpanded() && goalPredicate.evaluate(currentNode.getState())) {
            return currentNode;
        }

        // Check if the maximum number of steps limit has been reached.
        if (maxSteps > 0) {
            searchSteps++;
            initSearch.setStepsTaken(searchSteps);
            if (searchSteps >= maxSteps) {
                if (queue.isEmpty()) {
                    return null;
                } else {
                    throw new SearchNotExhaustiveException("Maximum number of steps reached.", null);
                }
            }
        }
    }

    // If no goal state is found, check for beyond-fringe states and throw an exception if any are found.
    if (beyondFringe) {
        throw new MaxBoundException("Max bound reached.", null);
    } else {
        return null;
    }
}

