/**
 * Sets the attribute for a specific row in the rowAttributes list.
 * If the row index is greater than or equal to the current size of the list,
 * the list is expanded with null values up to the specified row index.
 * 
 * @param attributes The AttributeSet to be set for the row.
 * @param r The index of the row to set the attribute for.
 */
private void setRowAttribute(AttributeSet attributes, int r) {
    if (r >= rowAttributes.size()) {
        for (int i = rowAttributes.size(); i <= r; i++) {
            rowAttributes.add(null);
        }
    }
    rowAttributes.set(r, attributes);
}

