public void setValue(T value) throws IllegalArgumentException {
    Integer b = attributeClass.lookupInt.get(value); // Retrieve the integer value from the lookup map.
    if (b == null) { // Check if the value is not already a member of the attribute class.
        if (attributeClass.finalized) { // Check if the attribute class has been finalized.
            throw new IllegalArgumentException("The value to set, " + value + ", is not already a member of the finalized IdType, " + attributeClass.attributeClassName + ".");
        } else {
            // Add the new value to the attribute class.
            IdAttribute newAttribute = attributeClass.createIdAttribute(value);
            b = newAttribute.value;
        }
    }
    // Set the new value as the value of this attribute.
    this.value = b;
}

