 * @param buffer The ByteBuffer to write the code into.
 * @param machine The WAMMachine that will host the code.
 * @param callPoint The call point of the functor within the machine.
 * @throws LinkageException If the instruction listing size exceeds Integer.MAX_VALUE.
 */
public void emmitCode(ByteBuffer buffer, WAMMachine machine, WAMCallPoint callPoint) throws LinkageException {
    // Ensure the instruction listing size does not exceed max int.
    if (sizeof() > Integer.MAX_VALUE) {
        throw new IllegalStateException("The instruction listing size exceeds Integer.MAX_VALUE.");
    }

    // Track the size of the emitted code in bytes.
    int length = 0;

    // Insert the compiled code into the machine's code area.
    for (WAMInstruction instruction : instructions) {
        instruction.emmitCode(buffer, machine);
        length += instruction.sizeof();
    }

    // Record the machine and call point.
    this.machine = machine;
    this.callPoint = callPoint;

    // Mark the code as linked into a machine.
    this.status = LinkStatus.Linked;
}

