    // Derive the integer priority of the element and adjust it to the queue's range
    int level = priorityToLevel(p.apply(o));

    // Create a new node to hold the element
    Node<E> newNode = new DataNode<>(o, markers[level + 1]);

    // Add the element to the tail of the queue
    while (true) {
        // Get the current tail and the next reference
        Node<E> t = markers[level + 1].getTail();
        Node<E> s = t.getNext();

        // Recheck the tail reference to ensure it hasn't changed
        if (t == markers[level + 1].getTail()) {
            // Check if the next element reference is the tail marker
            if (s == markers[level + 1]) {
                // Try to join the new tail onto the old one
                if (t.casNext(s, newNode)) {
                    // Update the queue's tail reference
                    markers[level + 1].casTail(t, newNode);
