/**
 * Notifies all registered property change listeners about a property change event.
 * 
 * @param evt The PropertyChangeEvent to be fired.
 */
protected void firePropertyChange(PropertyChangeEvent evt) {
    // Take a copy of the event as a final variable
    final PropertyChangeEvent finalEvent = evt;

    // Check if there are any listeners
    if (listeners == null) {
        return; // No listeners, do nothing
    }

    // Synchronize on the list of listeners to prevent concurrent modification
    synchronized (listeners) {
        Iterator it = listeners.iterator();
        while (it.hasNext()) {
            // Get the next listener
            final PropertyChangeListener l = (PropertyChangeListener) it.next();

            // Create a Runnable to fire the property change event
            Runnable r = new Runnable() {
                public void run() {
                    l.propertyChange(finalEvent);
                }
            };

            // Run the Runnable in the Swing event queue
            SwingUtilities.invokeLater(r);
        }
    }
}

