/**
 * Attempts to unify two terms in a unification data structure.
 * 
 * @param a1 The first term to unify.
 * @param a2 The second term to unify.
 * @return true if the unification is successful, false otherwise.
 */
private boolean unify(int a1, int a2) {
    uPush(a1);
    uPush(a2);
    boolean fail = false;
    while (!uEmpty() && !fail) {
        int d1 = deref(uPop());
        int d2 = deref(uPop());
        int t1 = derefTag(d1);
        int v1 = derefVal(d1);
        int t2 = derefTag(d2);
        int v2 = derefVal(d2);
        if (d1 != d2) {
            if (t1 == WAMInstruction.REF || t2 == WAMInstruction.REF) {
                bind(d1, d2);
            } else if (t2 == WAMInstruction.STR) {
                int fn1 = data.get(v1);
                int fn2 = data.get(v2);
                byte n1 = (byte) (fn1 >>> 24);
                if (fn1 == fn2) {
                    for (int i = 1; i <= n1; i++) {
                        uPush(v1 + i);
                        uPush(v2 + i);
                    }
                } else {
                    fail = true;
                }
            } else if (t2 == WAMInstruction.CON) {
                if ((t1 != WAMInstruction.CON) || (v1 != v2)) {
                    fail = true;
                }
            } else if (t2 == WAMInstruction.LIS) {
                if (t1 != WAMInstruction.LIS) {
                    fail = true;
                } else {
                    uPush(v1);
                    uPush(v2);
                    uPush(v1 + 1);
                    uPush(v2 + 1);
                }
            }
        }
    }
    return !fail;
}

