/**
 * Swaps a tile to a specified location and counts the number of illegal swaps.
 * 
 * @param t The tile to be moved.
 * @param x The target x-coordinate.
 * @param y The target y-coordinate.
 * @return The count of illegal swaps performed.
 */
protected int swapTileToLocationCountingIllegal(char t, int x, int y) {
    int illegal = 0;
    int tileX = getXForTile(t);
    int tileY = getYForTile(t);

    // Shift the tile into the correct column
    while (tileX != x) {
        if ((tileX - x) > 0) {
            if (swapTiles(tileX, tileY, tileX - 1, tileY)) {
                illegal++;
            }
            tileX--;
        } else {
            if (swapTiles(tileX, tileY, tileX + 1, tileY)) {
                illegal++;
            }
            tileX++;
        }
    }

    // Shift the tile into the correct row
    while (tileY != y) {
        if (swapTiles(tileX, tileY, tileX, tileY - 1)) {
            illegal++;
        }
        tileY--;
    }

    return illegal;
}

