/**
 * Generates a UUID time by using the current system time and a counter.
 * If the counter reaches a certain threshold, the timestamp is incremented.
 * 
 * @return The UUID time.
 */
private static long getUUIDTime() {
    // Update the current timestamp if it has changed
    if (_currentMillis != System.currentTimeMillis()) {
        _currentMillis = System.currentTimeMillis();
        _counter = 0; // Reset counter
    }

    // Check if the counter has reached the threshold
    if (_counter + 1 >= MILLI_MULT) {
        _currentMillis++; // Increment timestamp
        _counter = 0; // Reset counter
    }

    // Calculate the UUID time
    long currentTime = (_currentMillis + GREG_OFFSET) * MILLI_MULT;
    return currentTime + _counter++; // Return UUID time plus incremented counter
}

