void addEntry(int hash, K key, V value, int bucketIndex) {
    // Insert a new entry at the specified bucket index.
    table[bucketIndex] = new Entry<>(hash, key, value, table[bucketIndex]);

    // If auto-commit is not enabled, set the entry status to ADDED for the current thread.
    if (!auto_commit) {
        table[bucketIndex].setStatus(Entry.ADDED, getCurrentThreadId());
    }

    // Increment the size and check if resizing is needed.
    if (++size >= threshold) {
        resize(2 * table.length);
    }
}

