/**
 * Creates an immutable map that is a delegate of the given base map, with additional entries for keys that are not in the base map.
 * 
 * @param <K> the type of keys in the map
 * @param <V> the type of values in the map
 * @param base the base map to delegate to
 * @param keys the set of keys to include in the resulting map
 * @param augmentation a function that provides values for keys that are not in the base map
 * @return an immutable map that is a delegate of the base map with additional entries for the specified keys
 */
private static <K, V> ImmutableMap<K, V> createDelegate(final Map<K, V> base, final Set<? extends K> keys, final Function<K, V> augmentation) {
    final ImmutableMap.Builder<K, V> builder = ImmutableMap.builder();
    builder.putAll(base);
    keys.stream()
        .filter(key -> !base.containsKey(key))
        .forEach(key -> builder.put(key, augmentation.apply(key)));
    return builder.build();
}

