/**
 * Updates a single entity in the database.
 * 
 * @param object The entity to update.
 * @param properties The properties to update.
 * @throws RuntimeException If the entity is not persisted or if a collection property is provided.
 */
@Override
public void updateOne(E object, String... properties) {
    if (object.getId() == null) {
        throw new RuntimeException("Not a Persisted entity");
    }
    if (properties == null || properties.length == 0) {
        entityManager.merge(object);
        return;
    }
    StringBuilder sb = new StringBuilder();
    sb.append("Update " + clazz.getName() + " SET ");
    Map<String, Object> cache = new HashMap<>();
    for (String prop : properties) {
        try {
            Field field = object.getClass().getDeclaredField(prop);
            field.setAccessible(true);
            Object value = field.get(object);
            if (value instanceof Collection) {
                throw new RuntimeException("Collection property is not supported.");
            }
            cache.put(prop, value);
            if (cache.size() > 1) {
                sb.append(" ,");
            }
            sb.append(prop).append(" = :").append(prop);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
    if (cache.size() == 0) {
        return;
    }
    sb.append(" WHERE id = " + object.getId());
    Query query = entityManager.createQuery(sb.toString());
    for (Entry<String, Object> entry : cache.entrySet()) {
        query.setParameter(entry.getKey(), entry.getValue());
    }
    query.executeUpdate();
}

