synchronized void notifyConnectionError(Exception e) {
    // If packetReader and packetWriter are already done, return immediately.
    if ((packetReader == null || packetReader.done) && (packetWriter == null || packetWriter.done)) return;

    // Mark packetReader and packetWriter as done.
    if (packetReader != null) packetReader.done = true;
    if (packetWriter != null) packetWriter.done = true;

    // Temporarily close the connection, allowing for reconnection.
    shutdown(new Presence(Presence.Type.unavailable));

    // Notify all connection listeners of the error.
    for (ConnectionListener listener : getConnectionListeners()) {
        try {
            listener.connectionClosedOnError(e);
        } catch (Exception e2) {
            // Catch and print any exception from a faulty listener to recover.
            e2.printStackTrace();
        }
    }
}

