public static boolean verify(EventModel eventModel, Capabilities capabilities, Identifiable player, List<Identifiable> activators) {
    // Check if the event model contains a descriptor for StartMusicRequest
    if (!eventModel.containsDescriptor(StartMusicRequest.ID)) return false;

    // Check if the capabilities handle play requests from outside
    if (!capabilities.handlesPlayRequestFromOutside()) {
        // If not, check if any activator is the owner of the event model's source
        if (activators.stream().noneMatch(identifiable -> identifiable.isOwner(eventModel.getSource()))) return false;
    }

    // Verify the playlist associated with the event model
    if (!PlaylistResource.getPlaylist(eventModel).map(playlist -> playlist.verify(capabilities)).orElse(true)) return false;

    // Check if the player is the target of the event model
    return SelectorResource.isTarget(eventModel, player).orElse(false);
}

