/**
 * Initializes the output directory for the application.
 * 
 * <p>
 * This method performs the following steps:
 * 1. Retrieves the parent directory of the user's current working directory.
 * 2. Constructs the target directory path by appending the application's target directory name.
 * 3. Checks if the target directory exists:
 *    - If it exists, it verifies if it is a directory and writable. If not, it exits with an error.
 *    - If it does not exist, it checks if the parent directory is a directory and writable. If not, it exits with an error.
 *    - If the parent directory is valid, it attempts to create the target directory. If creation fails, it exits with an error.
 * 4. If all checks pass, it sets the output directory to the target directory and returns 0.
 * </p>
 * 
 * @return 0 if the output directory is successfully initialized, -1 otherwise.
 */
protected final int initOutputDir() {
    String parent = System.getProperty("user.dir");
    String target = parent + File.separator + this.target;
    File targetDir = new File(target);
    File parentDir = targetDir.getParentFile();

    if (targetDir.exists()) {
        if (!targetDir.isDirectory()) {
            System.err.println(this.getAppName() + ": target dir <" + target + "> exists but is not a directory, exiting");
            return -1;
        }
        if (!targetDir.canWrite()) {
            System.err.println(this.getAppName() + ": target dir <" + target + "> exists but cannot write into it, exiting");
            return -1;
        }
    } else {
        if (!parentDir.isDirectory()) {
            System.err.println(this.getAppName() + ": target dir parent <" + parent + "> exists but is not a directory, exiting");
            return -1;
        }
        if (!parentDir.canWrite()) {
            System.err.println(this.getAppName() + ": target dir parent <" + parent + "> exists but cannot write into it, exiting");
            return -1;
        }
        if (!targetDir.mkdir()) {
            System.err.println(this.getAppName() + ": could not create target dir <" + target + ">, exiting");
            return -1;
        }
    }

    this.outputDir = target;
    return 0;
}

