/**
 * Checks if the current execution is taking place within a JAR file.
 * 
 * @return true if the execution is within a JAR file, false otherwise.
 */
protected boolean inExecJar() {
    Class<Gen_ExecJarScripts> clazz = Gen_ExecJarScripts.class;
    String className = clazz.getSimpleName() + ".class";
    String classPath = clazz.getResource(className).toString();

    // Check if the class path starts with "jar"
    if (!classPath.startsWith("jar")) {
        System.err.println(this.getAppName() + ": not started in a jar, cannot proceed");
        return false;
    }

    // Construct the path to the MANIFEST.MF file
    String manifestPath = classPath.substring(0, classPath.lastIndexOf("!") + 1) + "/META-INF/MANIFEST.MF";
    Manifest manifest;

    try {
        // Load the MANIFEST.MF file
        manifest = new Manifest(new URL(manifestPath).openStream());
    } catch (IOException ex) {
        System.err.println(this.getAppName() + ": exception while retrieving manifest: " + ex.getMessage());
        return false;
    }

    // Get the main attributes from the manifest
    Attributes attr = manifest.getMainAttributes();

    // Check if the main class is specified in the manifest
    if (StringUtils.isBlank(attr.getValue("Main-Class"))) {
        System.err.println(this.getAppName() + ": no main class in manifest, probably not an executable JAR, cannot continue");
        return false;
    }

    return true;
}

