 * This method implements a hash function for a given key, similar to the JDK 1.4 implementation.
 * It performs a series of bitwise operations to ensure a good distribution of hash values.
 * 
 * @param key The object for which the hash code is to be computed.
 * @return The computed hash code.
 */
protected int hash(Object key) {
    int h = key.hashCode();
    h += ~ (h << 9);
    h ^= (h >>> 14);
    h += (h << 4);
    h ^= (h >>> 10);
    return h;
